namespace App\Services\Ai\Pricing;

use App\Models\Branch;
use App\Models\Customer;
use App\Models\ProductVariant;
use App\Models\User;
use App\Services\Ai\EntityResolver;
use App\Services\Ai\ToolOutcome;
use App\Services\BranchAccess;

final class PricingArgs
{
    /**
     * @param  array<string,mixed>  $args
     * @return array<string,mixed>
     */
    public static function normalize(array $args): array
    {
        foreach ($args as $key => $value) {
            if (is_string($value)) {
                $converted = EntityResolver::normalizeDigits($value);
                if (in_array($key, ['variant_id', 'customer_id', 'customer_group_id', 'price_list_id', 'price_list_item_id', 'branch_id', 'limit', 'page', 'per_page', 'expiring_within_days'], true) && is_numeric($converted)) {
                    $args[$key] = (int) $converted;
                } elseif (in_array($key, ['qty', 'min_qty'], true) && is_numeric($converted)) {
                    $args[$key] = (float) $converted;
                } elseif (in_array($key, ['sku', 'barcode', 'code'], true)) {
                    $args[$key] = strtoupper(trim($converted));
                } else {
                    $args[$key] = $value;
                }
            } elseif (is_array($value)) {
                $args[$key] = self::normalize($value);
            }
        }

        return $args;
    }

    /**
     * @param  array<string,mixed>  $args
     * @return array{variant: ProductVariant}|ToolOutcome
     */
    public static function resolveVariant(User $actor, EntityResolver $resolver, array $args): array|ToolOutcome
    {
        return \App\Services\Ai\Inventory\InventoryArgs::resolveVariant($actor, $resolver, $args);
    }

    /**
     * Branch scoping with the same 404-style behavior as PriceListService::assertListAccess:
     * a branch-restricted user can only see their own branch lists.
     *
     * @param  array<string,mixed>  $args
     * @return array{branchId: int|null}|ToolOutcome
     */
    public static function scopeBranchId(User $actor, BranchAccess $branches, array $args): array|ToolOutcome
    {
        try {
            $restricted = $branches->restrictedBranch($actor);
        } catch (\Throwable) {
            return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
        }
        $requested = isset($args['branch_id']) ? (int) $args['branch_id'] : null;
        if ($restricted !== null) {
            if ($requested !== null && $requested !== $restricted) {
                return ToolOutcome::denied('قائمة الأسعار غير موجودة.', auditable: false);
            }

            return ['branchId' => $restricted];
        }
        if ($requested !== null) {
            $branch = Branch::find($requested);
            if (! $branch) {
                return ToolOutcome::denied('الفرع مش موجود.', auditable: false);
            }

            return ['branchId' => $branch->id];
        }
        if (isset($args['branch_query']) && trim((string) $args['branch_query']) !== '') {
            $found = app(EntityResolver::class)->exactBranch($actor, (string) $args['branch_query']);
            if (! $found) {
                return ToolOutcome::denied('اسم الفرع مش واضح. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
            }

            return ['branchId' => $found->id];
        }

        return ['branchId' => null];
    }

    /**
     * @param  array<string,mixed>  $args
     * @return array{customer: Customer|null}|ToolOutcome
     */
    public static function resolveCustomer(User $actor, EntityResolver $resolver, array $args): array|ToolOutcome
    {
        $query = trim((string) ($args['customer_query'] ?? ''));
        if ((! empty($args['customer_id']) || $query !== '') && ! $actor->can('customers.view')) {
            return ToolOutcome::denied('معندكش صلاحية عرض العملاء.');
        }

        if (! empty($args['customer_id'])) {
            $customer = Customer::query()->find((int) $args['customer_id']);
            if (! $customer) {
                return ToolOutcome::denied('العميل مش موجود.', auditable: false);
            }

            return ['customer' => $customer];
        }
        if ($query === '') {
            return ['customer' => null];
        }
        $options = $resolver->customers($actor, $query);
        if (count($options) === 0) {
            return ToolOutcome::denied('مش لاقي عميل بالوصف ده.', auditable: false);
        }
        if (count($options) > 1) {
            return ToolOutcome::denied('لقيت أكتر من عميل. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
        }
        $customer = Customer::query()->find($options[0]['id']);
        if (! $customer) {
            return ToolOutcome::denied('العميل مش موجود.', auditable: false);
        }

        return ['customer' => $customer];
    }

}<?php

declare(strict_types=1);

namespace App\Services\Ai\Pricing;

use App\Models\User;
use App\Services\Ai\AgentTool;
use App\Services\Ai\Contracts\ToolProvider;
use App\Services\SettingService;

/**
 * Pricing AI domain (P07): price-list, coupon and promotion tools.
 *
 * Disabled by default behind ai_pricing_tools_enabled. Tool classes land
 * per phase under Tools/ and are registered in TOOL_CLASSES below.
 */
final class PricingToolProvider implements ToolProvider
{
    /** @var array<string, AgentTool>|null */
    private ?array $toolsCache = null;

    /** @var list<class-string<AgentTool>> */
    private const TOOL_CLASSES = [
        // Phase 1: Read tools
        \App\Services\Ai\Pricing\Tools\ExplainPriceTool::class,
        \App\Services\Ai\Pricing\Tools\QuotePriceTool::class,
        \App\Services\Ai\Pricing\Tools\CompareCustomerPricesTool::class,
        \App\Services\Ai\Pricing\Tools\ListPriceListsTool::class,
        \App\Services\Ai\Pricing\Tools\GetPriceListTool::class,
        \App\Services\Ai\Pricing\Tools\ListCouponsTool::class,
        \App\Services\Ai\Pricing\Tools\GetCouponTool::class,
        \App\Services\Ai\Pricing\Tools\ListPromotionsTool::class,
        \App\Services\Ai\Pricing\Tools\PricingHealthReportTool::class,
        \App\Services\Ai\Pricing\Tools\SimulateCartTool::class,

        // Phase 2: Price-list write tools
        \App\Services\Ai\Pricing\Tools\CreatePriceListTool::class,
        \App\Services\Ai\Pricing\Tools\UpdatePriceListTool::class,
        \App\Services\Ai\Pricing\Tools\SetPriceListStatusTool::class,
        \App\Services\Ai\Pricing\Tools\UpsertPriceListItemsTool::class,
        \App\Services\Ai\Pricing\Tools\DeletePriceListItemsTool::class,
        \App\Services\Ai\Pricing\Tools\ClonePriceListTool::class,
        \App\Services\Ai\Pricing\Tools\SchedulePriceChangeTool::class,
        \App\Services\Ai\Pricing\Tools\RefreshCatalogPricesTool::class,

        // Phase 4: Vision
        \App\Services\Ai\Pricing\Tools\ParsePriceSheetTool::class,

        // Phase 4: Import (CSV → single upsert proposal)
        \App\Services\Ai\Pricing\Tools\ImportPriceListItemsTool::class,
        \App\Services\Ai\Pricing\Tools\ExportPriceListTool::class,

        // Phase 3: Coupon & promotion write tools
        \App\Services\Ai\Pricing\Tools\CreateCouponsTool::class,
        \App\Services\Ai\Pricing\Tools\UpdateCouponTool::class,
        \App\Services\Ai\Pricing\Tools\SetCouponStatusTool::class,
        \App\Services\Ai\Pricing\Tools\CreatePromotionTool::class,
        \App\Services\Ai\Pricing\Tools\UpdatePromotionTool::class,
        \App\Services\Ai\Pricing\Tools\SetPromotionStatusTool::class,
        \App\Services\Ai\Pricing\Tools\CouponPerformanceTool::class,
        \App\Services\Ai\Pricing\Tools\WhatIfPriceChangeTool::class,
        \App\Services\Ai\Pricing\Tools\MarginRiskReportTool::class,
        // Phase 1: Read tools (explain_price, quote_price, ...).
        // Phase 2: Price-list write tools (upsert_price_list_items, ...).
        // Phase 3: Coupon & promotion tools (create_coupons, ...).
        // Phase 4: Vision/import tools (parse_price_sheet, ...).
        // Phase 5: What-if & proactive tools (what_if_price_change, ...).
    ];

    public function __construct(private SettingService $settings) {}

    /** @return array<string, AgentTool> */
    public function tools(): array
    {
        if ($this->toolsCache !== null) {
            return $this->toolsCache;
        }
        $tools = [];
        foreach (self::TOOL_CLASSES as $class) {
            if (class_exists($class)) {
                /** @var AgentTool $tool */
                $tool = app($class);
                $tools[$tool->name()] = $tool;
            }
        }

        return $this->toolsCache = $tools;
    }

    public function enabled(): bool
    {
        return $this->settings->getBool('ai_pricing_tools_enabled', false);
    }

    public function isToolHidden(string $name): bool
    {
        return match ($name) {
            'parse_price_sheet' => ! $this->settings->getBool('ai_pricing_vision_enabled', false),
            'list_coupons', 'get_coupon', 'create_coupons', 'update_coupon', 'set_coupon_status',
            'list_promotions', 'create_promotion', 'update_promotion', 'set_promotion_status',
            'coupon_performance', 'simulate_cart', 'margin_risk_report' => ! $this->settings->getBool('ai_promotions_tools_enabled', false),
            default => false,
        };
    }

    public function domain(): string
    {
        return 'pricing';
    }

    public function usesGlobalAdminLock(): bool
    {
        return false;
    }

    public function canReadEntity(User $actor, string $type): ?bool
    {
        if (! in_array($type, ['price_list', 'coupon', 'promotion'], true)) {
            return null;
        }
        if (! $this->enabled()) {
            return false;
        }

        return match ($type) {
            'price_list' => $actor->can('price_lists.view'),
            'coupon' => ! $this->isToolHidden('get_coupon') && $actor->can('coupons.view'),
            'promotion' => ! $this->isToolHidden('list_promotions') && $actor->can('promotions.view'),
            default => false,
        };
    }

    public function systemPromptSection(User $actor): ?string
    {
        if (! $this->enabled()) {
            return null;
        }
        if (! $actor->can('price_lists.view') && ! $actor->can('coupons.view')) {
            return null;
        }

        return implode("\n", [
            'دومين التسعير:',
            '— ترتيب السعر: قائمة العميل الخاصة ← قائمة المجموعة ← قائمة القناة (جملة/موزع/قطاعي) ← السعر الأساسي للمتغير.',
            '— خصم المجموعة بيتطبق على سعر القناة أو الأساسي بس، مش على قوائم العميل أو المجموعة.',
            '— عميل الجملة أو الموزع اللي مش معتمد بيتسعّر قطاعي.',
            '— لأي سؤال "ليه السعر كده" استخدم explain_price. ماتحسبش أسعار بنفسك أبدًا.',
            '— العروض (promotions) بتتسجل بس ومش بتتطبق تلقائيًا على السلة حاليًا. قول كده بوضوح.',
            '— الكوبون في الحساب بيخصم من البضاعة. كوبون free_shipping خصمه على الشحن مش البضاعة.',
            '— التواريخ النسبية ("من أول الشهر"، "لحد الخميس") تتحسب بتوقيت القاهرة.',
            '— ماتعرضش سعر تكلفة إلا لو الأداة رجّعته.',
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Services\Ai;

interface AgentTool
{
    public function name(): string;

    /** @return array<string,mixed> */
    public function declaration(): array;

    /** @return list<string> */
    public function permissions(): array;

    public function kind(): ToolKind;

    public function risk(): string;
}import { num, day } from './helpers';
import { WALLET_TYPE } from './constants';

const QUOTE_ST = { priced_by_admin: 'priced', converted_to_order: 'converted' };
const NOTICE_ST = { pending_review: 'pending' };
const RETURN_ST = { pending: 'requested' };

export const mapAccount = (me, dash) => ({
  id: me.id, name: me.name, phone: me.phone, email: me.email,
  company: me.company_name, tax_number: me.tax_number, commercial_register: me.commercial_register,
  status: me.status, approved_at: day(me.approved_at),
  credit_limit: num(dash?.credit_limit ?? me.credit_limit),
  used_credit: num(dash?.used_credit), available_credit: num(dash?.available_credit),
  in_progress_orders_count: dash?.in_progress_orders_count ?? 0,
  wallet: num(me.wallet_balance),
});

export const mapVariant = (v, p) => ({
  id: v.id, sku: v.sku, barcode: v.barcode, label: v.label || v.sku,
  price: num(v.your_price), base: num(v.base_price), qty: num(v.available_qty) ?? 0,
  tiers: (v.tier_prices || []).map((t) => [num(t.min_qty), num(t.unit_price)]),
  product: p,
});

export const mapProduct = (p) => {
  const prod = { id: p.id, name_ar: p.name, name_en: p.name_en, image: p.image };
  prod.variants = (p.variants || []).map((v) => mapVariant(v, prod));
  prod.base = prod.variants.length ? Math.max(...prod.variants.map((v) => v.base ?? 0)) : 0;
  return prod;
};

export const mapOrder = (o) => ({
  id: o.id, number: o.order_number, date: day(o.created_at),
  status: o.status, method: o.payment_method, pay: o.payment_status,
  subtotal: num(o.subtotal), discount: num(o.discount_amount), shipping: num(o.shipping_cost),
  cod_fee: num(o.cod_fee), tax: num(o.tax_amount), total: num(o.grand_total),
  cancellable: !!o.cancellable, returnable: !!o.returnable,
  recipient: o.recipient_name, phone: o.recipient_phone, city: o.city_name, address: o.shipping_address_line,
  items: (o.items || []).map((i) => ({ id: i.id, name: i.product_name, sku: i.sku, qty: num(i.qty), unit: num(i.unit_price), discount: num(i.discount_amount), line_total: num(i.line_total) })),
  track: buildTrack(o.status, o.status_history || []),
});

