            'checkout', 'storefront',
        ],
    ];

    public function __construct(private ToolRegistry $registry) {}

    /**
     * @param  list<array<string,mixed>>  $mentions
     * @param  array<string,mixed>|null  $selection
     * @param  list<string>  $attachments
     * @return list<string>|null
     */
    public function route(
        string $text,
        array $mentions = [],
        ?array $selection = null,
        ?AiConversation $conversation = null,
        array $attachments = [],
    ): ?array {
        $domains = [];

        if ($attachments !== []) {
            $domains['catalog'] = true;
        }

        $refs = $mentions;
        if ($selection !== null) {
            $refs[] = $selection;
        }
        foreach ($refs as $ref) {
            $entity = (string) ($ref['entity'] ?? '');
            $mapped = match ($entity) {
                'category', 'product', 'variant' => 'catalog',
                'customer', 'customer_group' => 'customers',
                'branch', 'user', 'role', 'permission', 'location' => 'admin',
                'transfer', 'stocktake', 'production_receipt' => 'inventory',
                'price_list', 'coupon', 'promotion' => 'pricing',
                'treasury', 'treasury_transfer', 'expense' => 'finance',
                'shipping_company', 'shipping_zone', 'shipping_rate' => 'shipping',
                'banner', 'cart' => 'storefront',
                default => null,
            };
            if ($mapped !== null) {
                $domains[$mapped] = true;
            }
        }

        $norm = EntityResolver::normalizeForSearch(EntityResolver::normalizeDigits($text));
        $lower = mb_strtolower($text);

        foreach (self::KEYWORDS as $domain => $words) {
            foreach ($words as $word) {
                $normWord = EntityResolver::normalizeForSearch($word);
                if ($normWord === '') {
                    continue;
                }
                // Short keywords ('عد' count vs 'تعديل' modify, 'رف' shelf vs
                // 'ارفض' reject) must match whole words, or every sentence
                // containing them misroutes.
                if (mb_strlen($normWord) <= 2) {
                    $matched = (bool) preg_match('/(^|\s)'.preg_quote($normWord, '/').'(\s|$)/u', $norm);
                } else {
                    $matched = str_contains($norm, $normWord) || str_contains($lower, mb_strtolower($word));
                }
                if ($matched) {
                    $domains[$domain] = true;
                    break;
                }
            }
        }

        $domains = array_fill_keys($this->disambiguate($norm, array_keys($domains), $refs), true);

        if ($conversation !== null) {
            $lastToolName = $this->lastToolInConversation($conversation);
            if ($lastToolName !== null) {
                $lastDomain = $this->toolDomain($lastToolName);
                if ($lastDomain !== null) {
                    $domains[$lastDomain] = true;
                }
            }
        }

        if ($domains === []) {
            return null;
        }

        return array_keys($domains);
    }

    /**
     * تمييز محفظة المنتج من محفظة العميل، وتحويل البضاعة من تحويل الفلوس،
     * ورصيد الصنف من رصيد الخزنة — بعد مطابقة الكلمات وقبل إرجاع الدومينات.
     *
     * @param  list<string>  $domains
     * @param  list<array<string,mixed>>  $refs
     * @return list<string>
     */
    private function disambiguate(string $norm, array $domains, array $refs): array
    {
        if ($domains === []) {
            return $domains;
        }
        $has = fn (string $word): bool => str_contains($norm, EntityResolver::normalizeForSearch($word));
        $hasAny = function (array $words) use ($has): bool {
            foreach ($words as $word) {
                if ($has($word)) {
                    return true;
                }
            }

            return false;
        };
        $mentionsCustomer = false;
        foreach ($refs as $ref) {
            if (in_array((string) ($ref['entity'] ?? ''), ['customer', 'customer_group'], true)) {
                $mentionsCustomer = true;
                break;
            }
        }
        $transferWord = $has('تحويل') || $has('حول');

        $drop = function (array $names) use (&$domains): void {
            $domains = array_values(array_diff($domains, $names));
        };
        $keep = function (string $name) use (&$domains): void {
            if (! in_array($name, $domains, true)) {
                $domains[] = $name;
            }
        };

        if ($has('محفظة')) {
            $walletFinance = $hasAny(['عميل', 'رصيد', 'شحن', 'استرداد', 'جنيه', 'مبلغ']) || $mentionsCustomer;
            if ($walletFinance) {
                $keep('finance');
                $otherCatalog = false;
                foreach (self::KEYWORDS['catalog'] ?? [] as $word) {
                    if (in_array($word, ['محفظة', 'محفظه'], true)) {
                        continue;
                    }
                    $normWord = EntityResolver::normalizeForSearch($word);
                    if ($normWord !== '' && str_contains($norm, $normWord)) {
                        $otherCatalog = true;
                        break;
                    }
                }
                if (! $otherCatalog) {
                    $drop(['catalog']);
                }
                $otherInventory = false;
                foreach (self::KEYWORDS['inventory'] ?? [] as $word) {
                    if (in_array($word, ['شحن', 'مشحون'], true)) {
                        continue;
                    }
                    $normWord = EntityResolver::normalizeForSearch($word);
                    if ($normWord !== '' && str_contains($norm, $normWord)) {
                        $otherInventory = true;
                        break;
                    }
                }
                if (! $otherInventory) {
                    $drop(['inventory']);
                }
            } else {
                $drop(['finance']);
            }
        }

        if ($transferWord) {
            $moneyCtx = $hasAny(['خزنة', 'خزينة', 'درج', 'فلوس', 'نقدية', 'كاش', 'بنك', 'مبلغ', 'اعتماد', 'اعتمد', 'يعتمد', 'معلقة', 'معلق']);
            $goodsCtx = $hasAny(['بضاعة', 'قطعة', 'صنف', 'كرتونة', 'شنطة', 'منتج', 'مخزن']);
            if ($moneyCtx && ! $goodsCtx) {
                $keep('finance');
                $drop(['inventory', 'catalog']);
            } elseif ($goodsCtx && ! $moneyCtx) {
                $drop(['finance', 'catalog']);
            }
        }

        if ($has('رصيد')) {
            $financeCtx = $hasAny(['خزنة', 'خزينة', 'درج', 'بنك', 'محفظة']);
            $inventoryCtx = $hasAny(['صنف', 'مخزن', 'قطعة']);
            if ($financeCtx && ! $inventoryCtx) {
                $keep('finance');
                $drop(['inventory']);
            } elseif ($inventoryCtx && ! $financeCtx) {
                $drop(['finance']);
            }
        }

        if ($hasAny(['وردية', 'ورديات']) && ! $hasAny(['مخزن', 'صنف', 'جرد', 'بضاعة'])) {
            $keep('finance');
            $drop(['inventory']);
        }

        if ($has('مصروف') && ! $hasAny(['مخزن', 'صنف', 'منتج', 'بضاعة', 'جرد'])) {
            $keep('finance');
            $drop(['inventory']);
        }

        if ($hasAny(['حركة', 'حركات']) && $hasAny(['خزنة', 'خزينة', 'درج', 'بنك', 'محفظة']) && ! $hasAny(['مخزن', 'صنف', 'بضاعة'])) {
            $drop(['inventory']);
        }

        if (($has('عجز') || $has('زيادة')) && ($has('درج') || $has('وردية'))) {
            $keep('finance');
            $drop(['inventory']);
        }

        $shippingCtx = $hasAny(['توصيل', 'تعريفة', 'شركة شحن', 'شركات الشحن', 'منطقة شحن', 'رسوم التحصيل', 'مدن الشحن']);
        if ($has('شحن المحفظة') || ($has('محفظة') && $has('شحن'))) {
            $keep('finance');
            $drop(['shipping']);
        }
        if (($has('مشحون') || $has('اتشحن')) && $hasAny(['تحويل', 'مخزن']) && ! $shippingCtx) {
            $drop(['shipping']);
        }
        if ($has('شحن مجاني') && $hasAny(['كوبون', 'عرض']) && ! $hasAny(['تعريفة', 'منطقة شحن', 'شركة شحن'])) {
            $keep('pricing');
            $drop(['shipping', 'inventory']);
        }
        if ($shippingCtx) {
            $keep('shipping');
            if (! $hasAny(['جرد', 'رصيد صنف', 'تحويل'])) {
                $drop(['inventory']);
            }
        }

        return array_values($domains);
    }

    private function lastToolInConversation(AiConversation $conversation): ?string
    {
        $lastModelWithCall = AiMessage::query()
            ->where('conversation_id', $conversation->id)
            ->where('role', 'model')
            ->whereNotNull('provider_parts')
            ->orderByDesc('id')
            ->limit(5)
            ->get(['provider_parts']);

        foreach ($lastModelWithCall as $msg) {
            foreach ((array) $msg->provider_parts as $part) {
                if (is_array($part) && isset($part['functionCall']['name']) && is_string($part['functionCall']['name'])) {
                    return $part['functionCall']['name'];
                }
            }
        }

        return null;
    }

    private function toolDomain(string $toolName): ?string
    {
        if (in_array($toolName, ['find_entities', 'ask_user_to_choose', 'bulk_actions'], true)) {
            return null;
        }
        $def = $this->registry->definitions()[$toolName] ?? null;
        if (! $def) {
            return null;
        }
        if (isset($def['provider']) && $def['provider'] instanceof ToolProvider) {
            return $def['provider']->domain();
        }
        if ($this->registry->isCustomerTool($toolName)) {
            return 'customers';
        }
        if (in_array($toolName, ['view_settings', 'view_document_numbering', 'update_settings', 'update_document_numbering'], true)) {
            return 'settings';
        }

        return 'admin';
    }
}<?php

declare(strict_types=1);

namespace App\Services\Ai;

final class ToolOutcome
{
    /** @param array<string,mixed> $data @param array<string,mixed>|null $uiBlock */
    private function __construct(public string $type, public array $data = [], public ?array $uiBlock = null, public ?string $message = null) {}

    public static function data(array $data, ?array $block = null): self
    {
        return new self('data', $data, $block);
    }

    /**
     * Sanitizes user-provided text for LLM prompts, stripping control characters.
     *
     * @return array{untrusted_text: string}
     */
    public static function untrusted(?string $value, int $max = 300): array
    {
        $clean = mb_substr((string) preg_replace('/[\x00-\x1F\x7F]/u', ' ', (string) $value), 0, $max);

        return ['untrusted_text' => $clean];
    }

    /** L11: denied audit flag — validation/not-found denials must not flood the audit log. */
    public bool $auditable = true;

    public static function denied(string $message, bool $auditable = true): self
    {
        $outcome = new self('denied', [], null, $message);
        $outcome->auditable = $auditable;

        return $outcome;
    }

    public static function picker(array $block): self
    {
        return new self('picker', [], $block);
    }

    public static function proposal(array $block, array $data = []): self
    {
        return new self('proposal', $data, $block);
    }

    public static function result(bool $ok, string $message, array $data = [], ?array $block = null): self
    {
        return new self($ok ? 'result' : 'failed', $data, $block, $message);
    }

    public static function wrap(string $type, array $data = [], ?array $block = null, ?string $message = null): self
    {
        return new self($type, $data, $block, $message);
    }

    public function haltsLoop(): bool
    {
        // L-3: رفض الصلاحيات (auditable) فقط يوقف الدورة — أخطاء التحقق
        // تُرد كنتيجة أداة فيُعطى النموذج فرصة للتصحيح بدل إنهاء الدورة.
        return in_array($this->type, ['picker', 'proposal'], true)
            || ($this->type === 'denied' && $this->auditable);
    }

    /** @param array{name:string,args:array<string,mixed>} $call @return array{role:string,parts:list<array<string,mixed>>} */
    public function asFunctionResponse(array $call): array
    {
        $payload = $this->type === 'denied' ? ['denied' => true, 'message' => $this->message] : $this->data;

        $response = ['name' => $call['name'], 'response' => $payload];
        if (isset($call['id'])) {
            $response['id'] = $call['id'];
        }

        return ['role' => 'user', 'parts' => [['functionResponse' => $response]]];
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
use RuntimeException;
use Throwable;

/**
 * Transactional file upload manager for private cloud storage (R2).
 *
 * Automatically tracks and deletes uploaded files if the database transaction fails.
 */
class PrivateAttachments
{
    private array $stored = [];

    private array $prepared = [];

    private array $claimed = [];

    /**
     * Executes a callback within a transactional scope, purging stored files on rollback.
     *
     * @param  callable(self): mixed  $callback  Business transaction callback.
     * @param  list<array{0: UploadedFile, 1: string}>  $uploads  Optional files pre-uploaded outside transaction locks.
     * @return mixed Value returned by the business callback.
     *
     * @throws Throwable Re-throws the original exception if transaction fails.
     */
    public static function transaction(callable $callback, array $uploads = []): mixed
    {
        $files = new self;
        try {
            foreach ($uploads as [$file, $directory]) {
                if ($file instanceof UploadedFile) {
                    if (isset($files->prepared[spl_object_id($file)])) {
                        continue;
                    }
                    $files->prepared[spl_object_id($file)] = $files->store($file, $directory.'/'.Str::uuid());
                }
            }
        } catch (Throwable $exception) {
            $files->deleteStoredQuietly();
            throw $exception;
        }

        // Attach rollback cleanup to outer transaction to ensure savepoint rollbacks still purge remote storage.
        if (DB::transactionLevel() > 0) {
            $pending = $files;
            DB::afterRollBack(static function () use ($pending): void {
                $pending->deleteStoredQuietly();
            });
        }

        try {
            $result = DB::transaction(fn () => $callback($files));
            $unused = array_diff(array_values($files->prepared), $files->claimed);
            $files->deletePathsQuietly($unused);
            $files->stored = array_values(array_diff($files->stored, $unused));

            return $result;
        } catch (Throwable $exception) {
            // Suppress cleanup failures so the original business or database exception surfaces to the caller.
            $files->deleteStoredQuietly();

            throw $exception;
        }
    }

    /**
     * Stores an uploaded file on private R2 storage and tracks it for transaction rollback cleanup.
     *
     * @param  UploadedFile  $file  Uploaded file instance.
     * @param  string  $directory  Target storage path.
     * @return string Stored file path on disk.
     *
     * @throws RuntimeException If the cloud storage upload fails.
     */
    public function store(UploadedFile $file, string $directory): string
    {
        if (isset($this->prepared[spl_object_id($file)])) {
            $path = $this->prepared[spl_object_id($file)];
            $this->claimed[] = $path;

            return $path;
        }
        $path = $file->store($directory, 'r2');
        if ($path === false) {
            throw new RuntimeException('تعذر حفظ المرفق؛ لم يتم تسجيل العملية.');
        }
        $this->stored[] = $path;

        return $path;
    }

    /**
     * Best-effort R2 cleanup that never throws: a failing delete must not
     * replace the original business exception (disk has throw => true).
     */
    public function deleteStoredQuietly(): void
    {
        if ($this->stored === []) {
            return;
        }

        $paths = $this->stored;
        $this->stored = [];

        $this->deletePathsQuietly($paths);
    }

    private function deletePathsQuietly(array $paths): void
    {
        if ($paths === []) {
            return;
        }
        try {
            Storage::disk('r2')->delete($paths);
        } catch (Throwable $exception) {
            report($exception);
        }
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\OrderStatus;
use App\Enums\TreasuryTransactionType;
use App\Enums\TreasuryType;
use App\Enums\WholesalePaymentNoticeStatus;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\Order;
use App\Models\ReturnRequest;
use App\Models\Treasury;
use App\Models\User;
use App\Models\WholesalePaymentAllocation;
use App\Models\WholesalePaymentNotice;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Carbon\Carbon;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;

/**
 * Manages wholesale customer payment notices, credit balance calculation, and order allocations.
 */
class WholesalePaymentNoticeService
{
    public function __construct(
        private readonly SettingService $settings,
        private readonly TreasuryService $treasury,
    ) {}

    /**
     * Submits a new payment notice with an uploaded proof receipt.
     *
     * @param  Customer  $customer  Submitting wholesale customer
     * @param  array<string, mixed>  $data  Notice metadata
     * @param  UploadedFile  $receipt  Proof of payment file
     * @return WholesalePaymentNotice Created pending notice
     *
     * @throws BusinessException If linked order is invalid or capacity exceeded
     */
    public function create(Customer $customer, array $data, UploadedFile $receipt): WholesalePaymentNotice
    {
        return PrivateAttachments::transaction(function (PrivateAttachments $files) use ($customer, $data, $receipt): WholesalePaymentNotice {
            // Serialize free and linked submissions for the same customer before
            // checking the bank reference, including requests with different files.
            Customer::query()->lockForUpdate()->findOrFail($customer->id);
            $reference = trim($data['reference_number']);
            if (WholesalePaymentNotice::query()->where('customer_id', $customer->id)
                ->whereRaw('lower(btrim(reference_number)) = ?', [mb_strtolower($reference)])->exists()) {
                throw new BusinessException('رقم مرجع السداد مسجل بالفعل لهذا التاجر.', [], 409);
            }

            $order = null;

            if (! empty($data['order_id'])) {
                // Pessimistic lock inside transaction serializes concurrent submissions against remaining balance.
                $order = $this->assertCreditableOrder($customer, (int) $data['order_id']);
                $this->assertOrderCapacity($order, (string) $data['amount']);
            }

            $path = $files->store($receipt, "wholesale_payment_notices/{$customer->id}");

            return WholesalePaymentNotice::create([
                'notice_number' => $this->settings->generateNextNumber('payment_notice'),
                'customer_id' => $customer->id,
                'order_id' => $order?->id,
                'amount' => $data['amount'],
                'payment_method' => $data['payment_method'],
                'bank_name' => $data['bank_name'],
                'reference_number' => $reference,
                'transfer_date' => $data['transfer_date'],
                'receipt_file_path' => $path,
                'status' => WholesalePaymentNoticeStatus::PendingReview,
            ]);
        }, [[$receipt, 'wholesale_payment_notices/'.$customer->id]]);
    }

    /**
     * Computes the current net debt for a wholesale customer (negative implies credit balance).
     *
     * @param  Customer  $customer  Wholesale customer
     * @return float Current outstanding debt or negative advance credit
     */
    public function outstandingBalance(Customer $customer): float
    {
        return (float) (string) $this->outstandingBalanceDecimal($customer);
    }

    private function outstandingBalanceDecimal(Customer $customer): BigDecimal
    {
        $debt = (string) Order::query()
            ->where('customer_id', $customer->id)
            ->where('payment_method', 'credit')
            ->where('payment_status', 'unpaid')
            ->where('status', '!=', OrderStatus::Cancelled->value)
            ->sum('grand_total');

        // Fully paid orders and their linked notices are excluded to avoid double deduction.
        $linkedOpen = (string) WholesalePaymentNotice::query()
            ->where('customer_id', $customer->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->whereNotNull('order_id')
            ->whereExists(function ($exists): void {
                $exists->selectRaw('1')->from('orders as o')
                    ->whereColumn('o.id', 'wholesale_payment_notices.order_id')
                    ->where('o.payment_status', 'unpaid')
                    ->where('o.status', '!=', OrderStatus::Cancelled->value);
            })
            ->sum('amount');

        // Unallocated free notices and notices linked to cancelled orders act as floating customer credit.
        $free = $this->freePoolTotal($customer);
        $allocated = $this->allocatedTotal($customer);
        $credits = BigDecimal::of($linkedOpen)
            ->plus($free->minus($allocated))
            ->toScale(2, RoundingMode::HalfUp);

        return BigDecimal::of($debt)->minus($credits)->toScale(2, RoundingMode::HalfUp);
    }

    private function freeNoticesQuery(Customer $customer)
    {
        return WholesalePaymentNotice::query()
            ->where('customer_id', $customer->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->where(function ($query): void {
                $query->whereNull('order_id')
                    ->orWhereExists(function ($exists): void {
                        $exists->selectRaw('1')->from('orders as o')
                            ->whereColumn('o.id', 'wholesale_payment_notices.order_id')
                            ->where('o.status', OrderStatus::Cancelled->value);
                    });
            });
    }

    private function freePoolTotal(Customer $customer): BigDecimal
    {
        return BigDecimal::of((string) $this->freeNoticesQuery($customer)->sum('amount'))
            ->toScale(2, RoundingMode::HalfUp);
    }

    private function allocatedTotal(Customer $customer): BigDecimal
    {
        return BigDecimal::of((string) WholesalePaymentAllocation::query()
            ->whereHas('notice', fn ($q) => $q->where('customer_id', $customer->id))
            ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
            ->sum('amount'))->toScale(2, RoundingMode::HalfUp);
    }

    /**
     * Generates a chronological statement of account including debits, credits, and opening balance.
     *
     * @param  Customer  $customer  Wholesale customer
     * @param  string|null  $from  Start date (inclusive, YYYY-MM-DD)
     * @param  string|null  $to  End date (inclusive, YYYY-MM-DD)
     * @return array{opening_balance: float, closing_balance: float, entries: list<array<string, mixed>>}
     */
    public function statement(Customer $customer, ?string $from = null, ?string $to = null): array
    {
        $entries = collect();

        Order::query()
            ->where('customer_id', $customer->id)
            ->where('payment_method', 'credit')
            ->where('status', '!=', OrderStatus::Cancelled->value)
            ->get(['id', 'order_number', 'grand_total', 'created_at'])
            ->each(fn (Order $order) => $entries->push([
                'date' => $order->created_at->copy(),
                'type' => 'debit',
                'description' => "طلب آجل {$order->order_number}",
                'reference' => $order->order_number,
                'amount' => (float) $order->grand_total,
            ]));

        WholesalePaymentNotice::query()
            ->where('customer_id', $customer->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->get(['id', 'notice_number', 'payment_method', 'amount', 'updated_at'])
            ->each(fn (WholesalePaymentNotice $notice) => $entries->push([
                'date' => $notice->updated_at->copy(),
                'type' => 'credit',
                'description' => "سداد {$notice->notice_number} ({$notice->payment_method->value})",
                'reference' => $notice->notice_number,
                'amount' => (float) $notice->amount,
            ]));

        ReturnRequest::query()
            ->where('customer_id', $customer->id)
            ->where('status', 'refunded')
            ->whereNotNull('refunded_at')
            ->get(['id', 'return_number', 'total_refund_amount', 'refunded_at'])
            ->each(fn (ReturnRequest $return) => $entries->push([
                'date' => $return->refunded_at->copy(),
                'type' => 'credit',
                'description' => "مرتجع مسترد {$return->return_number}",
                'reference' => $return->return_number,
                'amount' => (float) $return->total_refund_amount,
            ]));

        // Standard accounting convention: debits precede credits on identical dates.
        $sorted = $entries->sortBy([
            fn (array $a, array $b): int => $a['date']->startOfDay() <=> $b['date']->startOfDay(),
            fn (array $a, array $b): int => ($a['type'] === 'debit' ? 0 : 1) <=> ($b['type'] === 'debit' ? 0 : 1),
        ])->values();

        $fromDate = $from !== null ? Carbon::parse($from)->startOfDay() : null;
        $toDate = $to !== null ? Carbon::parse($to)->endOfDay() : null;

        $opening = 0.0;
        $running = 0.0;
        $result = [];
        foreach ($sorted as $entry) {
            $delta = $entry['type'] === 'debit' ? $entry['amount'] : -$entry['amount'];

            if ($fromDate !== null && $entry['date']->lt($fromDate)) {
                $opening += $delta;
                $running = $opening;

                continue;
            }
            if ($toDate !== null && $entry['date']->gt($toDate)) {
                continue;
            }

            $running += $delta;
            $result[] = [
                'date' => $entry['date']->toDateString(),
                'reference' => $entry['reference'],
                'description' => $entry['description'],
                'debit' => $entry['type'] === 'debit' ? number_format($entry['amount'], 2, '.', '') : number_format(0, 2, '.', ''),
                'credit' => $entry['type'] === 'credit' ? number_format($entry['amount'], 2, '.', '') : number_format(0, 2, '.', ''),
                'balance' => number_format($running, 2, '.', ''),
            ];
        }

        return [
            'opening_balance' => round($opening, 2),
            'closing_balance' => round($running, 2),
            'entries' => $result,
        ];
    }

    /**
     * Approves a payment notice, recording treasury receipt and allocating against open debt.
     *
     * @param  WholesalePaymentNotice  $notice  Target notice
     * @param  int  $adminId  Approving staff member ID
     * @param  int|null  $treasuryId  Destination treasury ID
     * @param  string|null  $adminNotes  Optional administrative review notes
     * @return WholesalePaymentNotice Updated notice instance
     *
     * @throws BusinessException If notice was reviewed, exceeds debt, or treasury is invalid
     */
    public function approve(WholesalePaymentNotice $notice, int $adminId, ?int $treasuryId = null, ?string $adminNotes = null): WholesalePaymentNotice
    {
        return DB::transaction(function () use ($notice, $adminId, $treasuryId, $adminNotes): WholesalePaymentNotice {
            $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
            $customer = Customer::query()->lockForUpdate()->findOrFail($notice->customer_id);

            if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
                throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
            }

            if ($notice->order_id !== null) {
                $order = Order::query()->lockForUpdate()->findOrFail($notice->order_id);
                if ($order->payment_status === 'paid') {
                    throw new BusinessException('الطلب المرتبط تم سداده بالفعل؛ لا يمكن اعتماد إشعار السداد.');
                }
            }

            // Decimal comparison avoids floating-point precision boundary errors.
            if (BigDecimal::of((string) $notice->amount)->compareTo($this->outstandingBalanceDecimal($customer)) > 0) {
                throw new BusinessException('مبلغ الإشعار أكبر من المديونية الآجلة الحالية للتاجر.');
            }

            $treasury = $this->resolveTreasury($treasuryId);
            app(BranchAccess::class)->assertTreasury($adminId, $treasury);

            $transaction = $this->treasury->record([
                'treasury_id' => $treasury->id,
                'type' => TreasuryTransactionType::CustomerReceipt,
                'amount' => (string) $notice->amount,
                'reference_type' => 'wholesale_payment_notice',
                'reference_id' => $notice->id,
                'created_by' => $adminId,
                'notes' => "اعتماد إشعار سداد جملة {$notice->notice_number}",
            ]);

            $notice->update([
                'status' => WholesalePaymentNoticeStatus::Approved,
                'reviewed_by' => $adminId,
                'admin_notes' => $adminNotes ?? $notice->admin_notes,
                'treasury_id' => $treasury->id,
                'treasury_transaction_id' => $transaction->id,
            ]);

            if ($notice->order_id !== null) {
                $this->settleOrderIfCovered((int) $notice->order_id, $adminId, $notice->notice_number);
            }
            $this->settleFreeNoticeFifo($customer, $adminId, $notice->notice_number);

            return $notice->load(['customer', 'order', 'treasury', 'treasuryTransaction']);
        });
    }

    /**
     * Rejects a pending wholesale payment notice.
     *
     * @param  WholesalePaymentNotice  $notice  Target notice
     * @param  int  $adminId  Reviewing staff member ID
     * @param  string|null  $adminNotes  Reason for rejection
     * @return WholesalePaymentNotice Updated notice instance
     *
     * @throws BusinessException If notice was already reviewed
     */
    public function reject(WholesalePaymentNotice $notice, int $adminId, ?string $adminNotes = null): WholesalePaymentNotice
    {
        return DB::transaction(function () use ($notice, $adminId, $adminNotes): WholesalePaymentNotice {
            $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);

            if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
                throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
            }

            $notice->update([
                'status' => WholesalePaymentNoticeStatus::Rejected,
                'reviewed_by' => $adminId,
                'admin_notes' => $adminNotes ?? $notice->admin_notes,
            ]);

            return $notice->load(['customer', 'order']);
        });
    }

    private function assertCreditableOrder(Customer $customer, int $orderId): Order
    {
        // Lock order row to prevent concurrent notices from exceeding total order value.
        $order = Order::query()->where('customer_id', $customer->id)->lockForUpdate()->find($orderId);

        if ($order === null) {
            throw new BusinessException('الطلب المرتبط غير موجود أو لا يخص هذا التاجر.', [], 404);
        }

        if ($order->payment_method !== 'credit' || $order->payment_status !== 'unpaid'
            || $order->status === OrderStatus::Cancelled) {
            throw new BusinessException('الطلب المرتبط ليس طلب آجل غير مسدد.');
        }

        return $order;
    }

    private function assertOrderCapacity(Order $order, string $newAmount): void
    {
        // Include pending reviews so concurrent submissions cannot collectively overcommit the order.
        $committed = (string) WholesalePaymentNotice::query()
            ->where('order_id', $order->id)
            ->whereIn('status', [
                WholesalePaymentNoticeStatus::PendingReview->value,
                WholesalePaymentNoticeStatus::Approved->value,
            ])
            ->sum('amount');

        $total = BigDecimal::of($committed)->plus(BigDecimal::of($newAmount))->toScale(2, RoundingMode::HalfUp);
        if ($total->compareTo(BigDecimal::of((string) $order->grand_total)) > 0) {
            throw new BusinessException('مبلغ الإشعار يتجاوز المتبقي غير المسدد من هذا الطلب.');
        }
    }

    private function settleOrderIfCovered(int $orderId, int $adminId, string $noticeNumber): void
    {
        $order = Order::query()->lockForUpdate()->find($orderId);

        if ($order === null || $order->payment_status !== 'unpaid') {
            return;
        }

        $approved = (string) WholesalePaymentNotice::query()
            ->where('order_id', $order->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->sum('amount');

        if (BigDecimal::of($approved)->compareTo(BigDecimal::of((string) $order->grand_total)) >= 0) {
            $this->markOrderPaid($order, $adminId, "تسوية آجل بالإشعار {$noticeNumber}");
        }
    }

    // FIFO allocation settles oldest unpaid orders first using available unallocated notices.
    private function settleFreeNoticeFifo(Customer $customer, int $adminId, string $noticeNumber): void
    {
        $available = $this->freePoolTotal($customer)->minus($this->allocatedTotal($customer))
            ->toScale(2, RoundingMode::HalfUp);
        if ($available->isLessThanOrEqualTo('0')) {
            return;
        }

        $branchId = app(BranchAccess::class)->restrictedBranch(User::findOrFail($adminId));
        $orders = Order::query()
            ->where('customer_id', $customer->id)
            ->where('payment_method', 'credit')
            ->where('payment_status', 'unpaid')
            ->where('status', '!=', OrderStatus::Cancelled->value)
            ->when($branchId !== null, fn ($q) => $q->where('allocated_branch_id', $branchId))
            ->orderBy('id')
            ->lockForUpdate()
            ->get();

        foreach ($orders as $order) {
            if ($available->isLessThanOrEqualTo('0')) {
                break;
            }
            $linked = BigDecimal::of((string) WholesalePaymentNotice::query()
                ->where('order_id', $order->id)
                ->where('status', WholesalePaymentNoticeStatus::Approved->value)
                ->sum('amount'))->toScale(2, RoundingMode::HalfUp);
            $alreadyAllocated = BigDecimal::of((string) WholesalePaymentAllocation::query()
                ->where('order_id', $order->id)
                ->sum('amount'))->toScale(2, RoundingMode::HalfUp);
            $need = BigDecimal::of((string) $order->grand_total)->minus($linked)->minus($alreadyAllocated)
                ->toScale(2, RoundingMode::HalfUp);
            if ($need->isLessThanOrEqualTo('0')) {
                $this->markOrderPaid($order, $adminId, "تسوية آجل بالإشعار الحر {$noticeNumber}");

                continue;
            }
            if ($available->compareTo($need) >= 0) {
                $this->consumeFreePool($customer, $need, (int) $order->id, $adminId);
                $this->markOrderPaid($order, $adminId, "تسوية آجل بالإشعار الحر {$noticeNumber}");
                $available = $available->minus($need)->toScale(2, RoundingMode::HalfUp);
            } else {
                break;
            }
        }
    }

    private function consumeFreePool(Customer $customer, BigDecimal $need, int $orderId, int $adminId): void
    {
        $notices = $this->freeNoticesQuery($customer)->orderBy('id')->lockForUpdate()->get();
        $remaining = $need->toScale(2, RoundingMode::HalfUp);

        foreach ($notices as $notice) {
            if ($remaining->isLessThanOrEqualTo('0')) {
                break;
            }
            $used = BigDecimal::of((string) WholesalePaymentAllocation::query()
                ->where('notice_id', $notice->id)
                ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
                ->sum('amount'))->toScale(2, RoundingMode::HalfUp);
            $free = BigDecimal::of((string) $notice->amount)->minus($used)->toScale(2, RoundingMode::HalfUp);
            if ($free->isLessThanOrEqualTo('0')) {
                continue;
            }
            $take = $free->compareTo($remaining) >= 0 ? $remaining : $free;
            WholesalePaymentAllocation::create([
                'notice_id' => $notice->id,
                'order_id' => $orderId,
                'amount' => (string) $take,
                'created_by' => $adminId,
            ]);
            $remaining = $remaining->minus($take)->toScale(2, RoundingMode::HalfUp);
        }
    }

    // Record status transition in audit history rather than performing a silent update.
    private function markOrderPaid(Order $order, int $adminId, string $notes): void
    {
        $order->update(['payment_status' => 'paid']);
        $order->statusHistories()->create([
            'from_status' => $order->status,
            'to_status' => $order->status,
            'changed_by_type' => (new User)->getMorphClass(),
            'changed_by_id' => $adminId,
            'notes' => mb_substr($notes, 0, 500),
        ]);
    }

    private function resolveTreasury(?int $treasuryId): Treasury
    {
        if ($treasuryId !== null) {
            // Receipts must go to bank accounts or main safes, not active POS drawers during open shifts.
            $treasury = Treasury::query()->findOrFail($treasuryId);
            if (! $treasury->is_active) {
                throw new BusinessException('الخزينة المحددة غير نشطة.');
            }
            if (! in_array($treasury->type, [TreasuryType::BankAccount, TreasuryType::MainSafe], true)) {
                throw new BusinessException('اعتماد إشعار السداد مسموح للخزينة البنكية أو الرئيسية فقط.');
            }

            return $treasury;
        }

        $treasury = Treasury::query()->where('is_active', true)
            ->where('type', TreasuryType::BankAccount->value)
            ->orderBy('id')
            ->first()
            ?? Treasury::query()->where('is_active', true)
                ->where('type', TreasuryType::MainSafe->value)
                ->orderBy('id')
                ->first();

        if ($treasury === null) {
            throw new BusinessException('لا توجد خزينة بنكية أو رئيسية نشطة لتسجيل القبض.');
        }

        return $treasury;
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\ProductStatus;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\Order;
use App\Models\ProductVariant;
use App\Models\StockLevel;
use Illuminate\Support\Collection;

/**
 * Quick-order service for wholesale customers.
 * Handles bulk code lookups (with tiered pricing and stock availability), cart imports, and order re-ordering.
 * All cart additions route through CartService to guarantee current real-time pricing.
 */
class WholesaleQuickOrderService
{
    public function __construct(
        private readonly PricingService $pricing,
        private readonly CartService $carts,
    ) {}

    /**
     * Batch lookup product variants by SKU or barcode with quantity-tier pricing and total available stock.
     *
     * @param  Customer  $customer  Wholesale customer performing the lookup.
     * @param  list<array{sku?: string|null, barcode?: string|null, qty: float}>  $lines  Requested order lines.
     * @return list<array<string, mixed>> Line details with live pricing and availability status.
     */
    public function lookup(Customer $customer, array $lines): array
    {
        $variants = $this->findVariants($lines);
        $availability = $this->availabilityFor($variants->pluck('id')->all());
        // Preload pricing context for all looked-up variants in a single query batch.
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->unique()->all());

        return collect($lines)->map(function (array $line) use ($customer, $variants, $availability, $ctx): array {
            $code = (string) ($line['sku'] ?? $line['barcode'] ?? '');
            $variant = $variants->get($code);
            $qty = (float) $line['qty'];

            if ($variant === null) {
                return [
                    'code' => $code, 'found' => false, 'qty' => $qty,
                    'available_qty' => 0.0, 'in_stock' => false,
                ];
            }

            $available = $availability[$variant->id] ?? 0.0;
            $unitPrice = $this->pricing->resolve($variant, $customer, $qty, null, $ctx)['unit_price'];

            return [
                'code' => $code,
                'found' => true,
                'product_variant_id' => $variant->id,
                'sku' => $variant->sku,
                'barcode' => $variant->barcode,
                'label' => $variant->displayLabel(),
                'image' => $this->imageFor($variant),
                'product_name' => $variant->product?->name_ar,
                'qty' => $qty,
                'unit_price' => $unitPrice,
                'line_total' => round($unitPrice * $qty, 2),
                'tier_prices' => $this->pricing->tiersFor($variant, $customer, $ctx),
                'available_qty' => $available,
                'in_stock' => $available >= $qty,
            ];
        })->all();
    }

    /**
     * Import multiple items from a parsed CSV/Excel file into the customer's active cart.
     * Skips invalid codes or lines exceeding available stock with explanatory status reports.
     *
     * @param  Customer  $customer  Target wholesale customer account.
     * @param  list<array{sku: string, qty: float}>  $rows  Parsed spreadsheet rows.
     * @return array{added: list<array<string, mixed>>, skipped: list<array<string, mixed>>, cart: array<string, mixed>}
     */
    public function importToCart(Customer $customer, array $rows): array
    {
        // Consolidate duplicate codes within the input before running stock availability checks.
        $merged = [];
        foreach ($rows as $row) {
            $sku = trim((string) $row['sku']);
            if ($sku === '') {
                continue;
            }
            $merged[$sku] = ($merged[$sku] ?? 0.0) + (float) $row['qty'];
        }

        $lines = collect($merged)->map(fn (float $qty, string $sku) => ['sku' => $sku, 'qty' => $qty])->values()->all();
        $variants = $this->findVariants($lines);
        $availability = $this->availabilityFor($variants->pluck('id')->all());

        $cart = $this->carts->resolveCart($customer, null);
        $inCart = $cart->items()->pluck('qty', 'product_variant_id')->map(fn ($q) => (float) $q)->all();

        // Preload pricing context for all candidate items in one batch to eliminate per-item overhead.
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->unique()->all());

        $added = [];
        $skipped = [];
        foreach ($lines as $line) {
            $variant = $variants->get($line['sku']);

            if ($variant === null) {
                $skipped[] = ['sku' => $line['sku'], 'qty' => $line['qty'], 'reason' => 'not_found_or_inactive'];

                continue;
            }

            $alreadyInCart = $inCart[$variant->id] ?? 0.0;
            if (($availability[$variant->id] ?? 0.0) < $alreadyInCart + $line['qty']) {
                $skipped[] = ['sku' => $line['sku'], 'qty' => $line['qty'], 'reason' => 'insufficient_stock'];

                continue;
            }

            $cart = $this->carts->addItem($cart, $customer, $variant->id, $line['qty']);
            $inCart[$variant->id] = $alreadyInCart + $line['qty'];
            $added[] = [
                'sku' => $variant->sku,
                'product_variant_id' => $variant->id,
                'qty' => $line['qty'],
                'unit_price' => $this->pricing->resolve($variant, $customer, $inCart[$variant->id], null, $ctx)['unit_price'],
            ];
        }

        return [
            'added' => $added,
            'skipped' => $skipped,
            'cart' => $this->carts->present($cart, $customer),
        ];
    }

    /**
     * Copy lines from a previous order into the customer's current cart at today's real-time prices.
     * Skips items that are discontinued, unpublished, or out of stock.
     *
     * @param  Customer  $customer  Target wholesale customer account.
     * @param  Order  $order  Historical order to duplicate into cart.
     * @return array{added: list<array<string, mixed>>, skipped: list<array<string, mixed>>, cart: array<string, mixed>}
     */
    public function reorderToCart(Customer $customer, Order $order): array
    {
        if ($order->customer_id !== $customer->id) {
            throw new BusinessException('الطلب غير موجود أو لا يخص هذا التاجر.', [], 404);
        }

        $rows = $order->items()
            ->get()
            ->groupBy('product_variant_id')
            ->map(fn (Collection $items, int $variantId) => [
                'sku' => (string) ($items->first()->sku_snapshot ?? ''),
                'qty' => (float) $items->sum('qty'),
                'variant_id' => $variantId,
            ])
            ->values()
            ->all();

        // Key by active variant ID rather than historical snapshot SKU to ensure integrity against catalog renames.
        $cart = $this->carts->resolveCart($customer, null);
        $inCart = $cart->items()->pluck('qty', 'product_variant_id')->map(fn ($q) => (float) $q)->all();
        $variants = ProductVariant::query()->with('product')
            ->whereIn('id', collect($rows)->pluck('variant_id')->all())
            ->get()->keyBy('id');
        $availability = $this->availabilityFor($variants->pluck('id')->all());
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->all());

        $added = [];
        $skipped = [];
        foreach ($rows as $row) {
            $variant = $variants->get($row['variant_id']);

            if ($variant === null || ! $variant->is_active || $variant->product?->status !== ProductStatus::Published) {
                $skipped[] = ['sku' => $row['sku'], 'qty' => $row['qty'], 'reason' => 'not_found_or_inactive'];

                continue;
            }

            $alreadyInCart = $inCart[$variant->id] ?? 0.0;
            if (($availability[$variant->id] ?? 0.0) < $alreadyInCart + $row['qty']) {
                $skipped[] = ['sku' => $row['sku'], 'qty' => $row['qty'], 'reason' => 'insufficient_stock'];

                continue;
            }

            $cart = $this->carts->addItem($cart, $customer, $variant->id, $row['qty']);
            $inCart[$variant->id] = $alreadyInCart + $row['qty'];
            $added[] = [
                'sku' => $variant->sku,
                'product_variant_id' => $variant->id,
                'qty' => $row['qty'],
                'unit_price' => $this->pricing->resolve($variant, $customer, $inCart[$variant->id], null, $ctx)['unit_price'],
            ];
        }

        return [
            'added' => $added,
            'skipped' => $skipped,
            'cart' => $this->carts->present($cart, $customer),
        ];
    }

    /**
     * Map active variants of published products by SKU and barcode.
     *
     * @param  list<array{sku?: string|null, barcode?: string|null}>  $lines
     * @return Collection<string, ProductVariant>
     */
    private function findVariants(array $lines): Collection
    {
        $skus = collect($lines)->pluck('sku')->filter()->unique()->all();
        $barcodes = collect($lines)->pluck('barcode')->filter()->unique()->all();

        $variants = ProductVariant::query()->with(['product.media', 'media'])
            ->where('is_active', true)
            ->whereHas('product', fn ($q) => $q->where('status', 'published'))
            ->where(function ($q) use ($skus, $barcodes): void {
                if ($skus !== []) {
                    $q->orWhereIn('sku', $skus);
                }
                if ($barcodes !== []) {
                    $q->orWhereIn('barcode', $barcodes);
                }
            })
            ->get();

        $map = collect();
        foreach ($variants as $variant) {
            $map->put($variant->sku, $variant);
            if ($variant->barcode !== null && $variant->barcode !== '') {
                $map->put($variant->barcode, $variant);
            }
        }

        return $map;
    }

    /**
     * Resolves primary thumbnail following catalog priority (product gallery first, then variant media).
     */
    private function imageFor(ProductVariant $variant): ?string
    {
        $media = $variant->product?->getMedia('images')->first()
            ?? $variant->getMedia('images')->first();

        if ($media === null) {
            return null;
        }

        return $media->hasGeneratedConversion('thumb') ? $media->getUrl('thumb') : $media->getUrl();
    }

    /**
     * Total available stock across all branches for a given list of variant IDs.
     *
     * @param  list<int>  $variantIds
     * @return array<int, float>
     */
    private function availabilityFor(array $variantIds): array
    {
        if ($variantIds === []) {
            return [];
        }

        return StockLevel::query()
            ->whereIn('product_variant_id', $variantIds)
            ->groupBy('product_variant_id')
            ->selectRaw('product_variant_id, SUM(available) AS total_available')
            ->pluck('total_available', 'product_variant_id')
            ->map(fn ($v) => (float) $v)
            ->all();
    }
}<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Wholesale;

use App\Enums\SalesChannel;
use App\Exceptions\BusinessException;
use App\Exports\WholesalePriceListExport;
use App\Http\Controllers\Controller;
use App\Models\Customer;
use App\Models\Product;
use App\Models\ProductVariant;
use App\Models\StockLevel;
use App\Services\PricingService;
use App\Services\SearchTerm;
use App\Services\SettingService;
use App\Services\WholesalePriceListService;
use Barryvdh\DomPDF\Facade\Pdf;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
use Maatwebsite\Excel\Facades\Excel;
use Symfony\Component\HttpFoundation\BinaryFileResponse;
use Symfony\Component\HttpFoundation\Response;

class ProductController extends Controller
{
    public function __construct(
        private readonly PricingService $pricing,
        private readonly WholesalePriceListService $priceList,
        private readonly SettingService $settings,
    ) {}

    /** كتالوج الجملة: لكل متغير سعر هذا التاجر وشرائح كمياته والمتاح. */
    public function index(Request $request): JsonResponse
    {
        $filters = $request->validate([
            'search' => ['nullable', 'string', 'max:255'],
            'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
        ]);

        /** @var Customer $customer */
        $customer = $request->user();

        $products = Product::query()
            // M6: wholesale sees wholesale-channel products only, on active
            // category paths (mirrors the storefront's publishedQuery guards).
            ->where('status', 'published')
            ->whereIn('sales_channel', [SalesChannel::Wholesale, SalesChannel::Both])
            ->whereHas('category', fn ($q) => $q->where('is_active', true)
                ->whereDoesntHave('parent', fn ($parent) => $parent->where('is_active', false)
                    ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', false))))
            ->with(['media', 'variants' => fn ($q) => $q->where('is_active', true)->with('media')])
            ->when($filters['search'] ?? null, function ($q, $v): void {
                $pattern = SearchTerm::pattern($v);
                $q->where(fn ($sub) => $sub
                    ->whereLike('name_ar', $pattern, caseSensitive: false)
                    ->orWhereLike('name_en', $pattern, caseSensitive: false)
                    ->orWhereHas('variants', fn ($qv) => $qv->whereLike('sku', $pattern, caseSensitive: false)));
            })
            ->latest('id')
            ->paginate($filters['per_page'] ?? 15);

        $variantIds = $products->getCollection()
            ->flatMap(fn (Product $product) => $product->variants->pluck('id'))
            ->all();

        // M6: availability counts active branches only, like the storefront.
        $availability = StockLevel::query()
            ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
            ->where('branches.is_active', true)
            ->whereIn('product_variant_id', $variantIds)
            ->groupBy('product_variant_id')
            ->selectRaw('product_variant_id, SUM(available) AS total_available')
            ->pluck('total_available', 'product_variant_id')
            ->map(fn ($v) => (float) $v)
            ->all();

        // F17: customer price-list context is identical for every variant on
        // this page — load it once instead of per variant.
        $pricingCtx = $this->pricing->contextFor($customer, $variantIds);

        $data = $products->getCollection()->map(function (Product $product) use ($customer, $availability, $pricingCtx): array {
            $images = $product->catalogImages();
            $first = $images->first();
            $image = $first !== null
                ? ($first->hasGeneratedConversion('thumb') ? $first->getUrl('thumb') : $first->getUrl())
                : null;

            return [
                'id' => $product->id,
                'name' => $product->name_ar,
                'name_en' => $product->name_en,
                'image' => $image,
                'variants' => $product->variants->map(function (ProductVariant $variant) use ($customer, $availability, $pricingCtx, $image): array {
                    try {
                        $resolved = $this->pricing->resolve($variant, $customer, 1, null, $pricingCtx);
                        $price = $resolved['unit_price'];
                        $base = $resolved['base_price'];
                        $tiers = $this->pricing->tiersFor($variant, $customer, $pricingCtx);
                    } catch (BusinessException) {
                        $price = null;
                        $base = $variant->retail_price !== null ? (float) $variant->retail_price : null;
                        $tiers = [];
                    }

                    return [
                        'id' => $variant->id,
                        'sku' => $variant->sku,
                        'barcode' => $variant->barcode,
                        'label' => $variant->displayLabel(),
                        'image' => $image,
                        'base_price' => $base,
                        'your_price' => $price,
                        'tier_prices' => $tiers,
                        'available_qty' => $availability[$variant->id] ?? 0.0,
                    ];
                })->values()->all(),
            ];
        })->values()->all();

        return response()->json([
            'data' => $data,
            'meta' => [
                'current_page' => $products->currentPage(),
                'last_page' => $products->lastPage(),
                'per_page' => $products->perPage(),
                'total' => $products->total(),
            ],
        ]);
    }

    /** تصدير قائمة أسعار التاجر: xlsx منسق أو PDF بترويسة الشركة وصلاحية. */
    public function exportPriceList(Request $request): BinaryFileResponse|Response
    {
        $validated = $request->validate([
            'format' => ['required', Rule::in(['pdf', 'xlsx'])],
        ]);

        /** @var Customer $customer */
        $customer = $request->user();
        $rows = $this->priceList->rows($customer);

        if ($validated['format'] === 'xlsx') {
            return Excel::download(new WholesalePriceListExport($rows), 'price-list.xlsx');
        }

        $validUntil = now()->addDays(30);

        return Pdf::loadView('pdfs.wholesale_price_list', [
            'company_name' => (string) $this->settings->get('company_name', 'Alfarid'),
            'customer' => $customer,
            'rows' => $rows,
            'valid_until' => $validUntil,
            'generated_at' => now(),
        ])->download('price-list.pdf');
    }
}<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1;

use App\Http\Controllers\Controller;
use App\Models\Customer;
use App\Models\ReturnRequestItem;
use App\Models\SupplierDelivery;
use App\Models\SupplierInvoice;
use App\Models\SupplierUser;
use App\Models\User;
use App\Models\WholesalePaymentNotice;
use App\Services\BranchAccess;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;
use Symfony\Component\HttpFoundation\HeaderUtils;
use Symfony\Component\HttpKernel\Exception\HttpException;
use Throwable;

/**
 * Securely streams private file attachments with strict role-based access control and nosniff headers.
 */
class AttachmentController extends Controller
{
    public function __construct(private readonly BranchAccess $branchAccess) {}

    /**
     * Streams inspection photos attached to a return request item.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $returnItem  Return item identifier
     * @param  int  $attachment  Attachment array index
     * @return RedirectResponse Short-lived signed R2 URL (H3)
     */
    public function returnFile(Request $request, int $returnItem, int $attachment): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = ReturnRequestItem::query();
        if ($actor instanceof Customer) {
            $query->whereHas('returnRequest', fn ($q) => $q->where('customer_id', $actor->id));
        } else {
            abort_unless($actor instanceof User && $actor->can('returns.view'), 403);
        }
        $item = $query->findOrFail($returnItem);
        if ($actor instanceof User) {
            $return = $item->returnRequest;
            $branchId = $return->branch_id ?? $return->order?->allocated_branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, ($item->attachments ?? [])[$attachment] ?? null);
    }

    /**
     * Streams supplier invoice PDF attachment.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $invoice  Supplier invoice identifier
     * @return RedirectResponse Short-lived signed R2 URL (H3)
     */
    public function invoice(Request $request, int $invoice): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = SupplierInvoice::query()->with('purchaseOrder');
        if ($actor instanceof SupplierUser) {
            $query->where('supplier_id', $actor->supplier_id)->where('status', '!=', 'draft');
        } else {
            abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
        }

        $model = $query->findOrFail($invoice);
        if ($actor instanceof User) {
            // M5: same branch rule as returnFile — a branch-confined staffer
            // must not fetch another branch's procurement documents by id.
            $branchId = $model->purchaseOrder?->branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, $model->attachment_path);
    }

    /**
     * Streams delivery receipt document attached to a procurement delivery.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $delivery  Delivery identifier
     * @return RedirectResponse Short-lived signed R2 URL (H3)
     */
    public function delivery(Request $request, int $delivery): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = SupplierDelivery::query()->with('purchaseOrder');
        if ($actor instanceof SupplierUser) {
            $query->where('supplier_id', $actor->supplier_id);
        } else {
            abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
        }

        $model = $query->findOrFail($delivery);
        if ($actor instanceof User) {
            // M5: same branch rule as returnFile.
            $branchId = $model->purchaseOrder?->branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, $model->invoice_file_path);
    }

    /**
     * Streams bank transfer receipt attached to a wholesale payment notice.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $notice  Payment notice identifier
     * @return RedirectResponse Short-lived signed R2 URL (H3)
     */
    public function paymentNotice(Request $request, int $notice): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = WholesalePaymentNotice::query();
        if ($actor instanceof Customer) {
            $query->where('customer_id', $actor->id);
        } else {
            abort_unless($actor instanceof User && $actor->can('payment_notices.view'), 403);
        }

        $model = $query->with('order')->findOrFail($notice);
        if ($actor instanceof User) {
            $branchId = $model->order?->allocated_branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, $model->receipt_file_path);
    }

    private function download(Request $request, ?string $path): RedirectResponse|JsonResponse
    {
        // H3: never proxy R2 bytes through PHP-FPM. The old exists()+download()
        // held one FPM worker for the whole transfer (a 20MB file on a 500KB/s
        // link exceeds the 30s Guzzle http.timeout and arrives truncated), and
        // let one client exhaust workers with slow downloads. Issue a 2-minute
        // signed URL instead; authorization stays here, bytes come from R2.
        abort_if($path === null, 404);

        try {
            if (! $request->boolean('signed') && ! Storage::disk('r2')->exists($path)) {
                abort(404);
            }

            $url = Storage::disk('r2')->temporaryUrl(
                $path,
                now()->addMinutes(2),
                [
                    'ResponseContentDisposition' => HeaderUtils::makeDisposition('attachment', basename($path), 'attachment'),
                    // L11: private documents must never sit in shared caches.
                    'ResponseCacheControl' => 'private, max-age=120',
                ]
            );
        } catch (Throwable $exception) {
            if ((int) ($exception->getCode() ?: 0) === 404 || $exception instanceof HttpException) {
                throw $exception;
            }

            // R2 outage (throw => true) is a dependency failure, not a bug.
            abort(503, 'Document storage is temporarily unavailable.');
        }

        if ($request->boolean('signed')) {
            return response()->json(['url' => $url])->header('Cache-Control', 'private, no-store');
        }

        return redirect()->to($url)->header('Cache-Control', 'private, no-store');
    }
}<?php

declare(strict_types=1);

namespace App\Http\Requests\Wholesale;

use App\Enums\CustomerDocumentType;
use App\Http\Requests\Concerns\NormalizesCustomerInput;
use App\Rules\EmailNotUsedByOtherAccountType;
use App\Rules\PasswordByteLimit;
use App\Rules\UniqueCustomerEmail;
use App\Services\CustomerPhoneVerificationService;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Support\Arr;
use Illuminate\Validation\Rule;

class WholesaleRegisterRequest extends FormRequest
{
    use NormalizesCustomerInput;

    public function authorize(): bool
    {
        app(CustomerPhoneVerificationService::class)->requireProof($this);

        return true;
    }

    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            'name' => ['required', 'string', 'max:255'],
            'email' => ['nullable', 'email', 'max:255', new EmailNotUsedByOtherAccountType('customers'), new UniqueCustomerEmail],
            'phone' => ['required', 'string', 'regex:/^01[0125][0-9]{8}$/', Rule::unique('customers', 'phone')],
            'password' => ['required', 'string', new PasswordByteLimit, 'min:12', 'max:72'],
            'phone_verification_token' => ['nullable', 'string', 'size:64'],
            'company_name' => ['required', 'string', 'max:255'],
            'tax_number' => ['required', 'string', 'max:50'],
            'commercial_register' => ['required', 'string', 'max:50'],
            'documents' => ['required', 'array', 'list', 'min:1', 'max:5'],
            'documents.*' => ['required', 'file', 'mimes:pdf,jpg,jpeg,png', 'mimetypes:application/pdf,image/jpeg,image/png', 'max:5120'],
            'document_types' => ['nullable', 'array', 'list', 'size:'.count(Arr::wrap($this->file('documents', [])))],
            'document_types.*' => ['nullable', Rule::enum(CustomerDocumentType::class)],
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\ProductStatus;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\ProductVariant;
use App\Models\StockLevel;

/**
 * Generates customer-specific wholesale price list export rows.
 *
 * Serves as the single source of truth for Excel and PDF price list exports.
 */
class WholesalePriceListService
{
    public function __construct(private readonly PricingService $pricing) {}

    /**
     * Build tabular pricing and availability rows for all active variants for the given customer.
     *
     * @param  Customer  $customer  Target wholesale customer account.
     * @return list<array{sku: string, barcode: string|null, product_name: string|null, base_price: float|null, wholesale_price: float|null, tier_prices: list<array{min_qty: float, unit_price: float}>, available_qty: float}>
     */
    public function rows(Customer $customer): array
    {
        return StatementBudget::run(150000, fn (): array => $this->calculateRows($customer));
    }

    private function calculateRows(Customer $customer): array
    {
        $variants = ProductVariant::query()->with('product')
            ->where('is_active', true)
            ->whereHas('product', fn ($q) => $q->where('status', ProductStatus::Published->value))
            ->orderBy('sku')
            ->get();

        $availability = StockLevel::query()
            ->whereIn('product_variant_id', $variants->pluck('id')->all())
            ->groupBy('product_variant_id')
            ->selectRaw('product_variant_id, SUM(available) AS total_available')
            ->pluck('total_available', 'product_variant_id')
            ->map(fn ($v) => (float) $v)
            ->all();

        // Preload customer pricing rules and tier overrides once to eliminate N+1 group queries.
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->all());

        return $variants->map(function (ProductVariant $variant) use ($customer, $availability, $ctx): array {
            try {
                $resolved = $this->pricing->resolve($variant, $customer, 1, null, $ctx);
                $price = $resolved['unit_price'];
                $base = $resolved['base_price'];
                $tiers = $this->pricing->tiersFor($variant, $customer, $ctx);
            } catch (BusinessException) {
                // Emit unpriced variants with null instead of aborting the bulk catalog export.
                $price = null;
                $base = $variant->retail_price !== null ? (float) $variant->retail_price : null;
                $tiers = [];
            }

            return [
                'sku' => $variant->sku,
                'barcode' => $variant->barcode,
                'product_name' => $variant->product?->name_ar,
                'base_price' => $base,
                'wholesale_price' => $price,
                'tier_prices' => $tiers,
                'available_qty' => $availability[$variant->id] ?? 0.0,
            ];
        })->all();
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerDocumentStatus;
use App\Enums\CustomerDocumentType;
use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Events\WholesaleApplicationSubmitted;
use App\Models\Customer;
use App\Models\CustomerAuditLog;
use App\Models\CustomerDocument;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;

/**
 * Wholesale customer self-registration service.
 * Registers customer in Pending status and stages uploaded verification documents into private storage.
 * Final approval is performed by administrators via CustomerManagementService.
 */
class WholesaleRegistrationService
{
    public function __construct(private readonly CustomerAuthService $auth) {}

    /**
     * Register a new wholesale customer and store supporting verification documents.
     * Staged files are moved into customer directory upon successful transaction.
     *
     * @param  list<UploadedFile>  $files
     * @param  list<string|null>  $documentTypes  Parallel document type tags (defaults to "other")
     * @return array{customer: Customer, token: string}
     */
    public function register(array $data, array $files, array $documentTypes = []): array
    {
        $files = array_values($files);
        $documentTypes = array_values($documentTypes);
        $storedPaths = [];
        $staged = [];
        $stagingDirectory = 'customer_documents/pending/'.Str::uuid();

        // L-10: الاستهلاك الفعلي لسه جوه الـ transaction.
        app(CustomerPhoneVerificationService::class)->assertProofPresent($data);

        try {
            foreach ($files as $i => $file) {
                $filename = Str::uuid().'.'.($file->extension() ?: 'bin');
                $path = Storage::disk('r2')->putFileAs($stagingDirectory, $file, $filename);
                if ($path === false) {
                    throw new \RuntimeException('تعذر حفظ مستند العميل.');
                }
                $storedPaths[] = $path;
                $staged[] = [
                    'filename' => $filename, 'path' => $path,
                    'document_type' => $documentTypes[$i] ?? CustomerDocumentType::Other->value,
                    'original_name' => CustomerDocument::safeName($file->getClientOriginalName()),
                    'mime_type' => $file->getMimeType() ?? 'application/octet-stream',
                ];
            }

            // Reserve the sequence value before storage I/O, without holding row locks.
            $customerId = (int) DB::selectOne("SELECT nextval(pg_get_serial_sequence('customers', 'id')) AS id")->id;
            foreach ($staged as &$document) {
                $path = "customer_documents/{$customerId}/".$document['filename'];
                $storedPaths[] = $path;
                if (! Storage::disk('r2')->move($document['path'], $path)) {
                    throw new \RuntimeException('تعذر حفظ مستند العميل.');
                }
                $document['path'] = $path;
            }
            unset($document);

            $registration = DB::transaction(function () use ($data, $staged, $customerId): array {
                $this->auth->lockRegistrationEmail($data['email'] ?? null);
                $verified = app(CustomerPhoneVerificationService::class)->consume($data);
                $customer = Customer::query()->make([
                    'name' => $data['name'],
                    'email' => $data['email'] ?? null,
                    'phone' => $data['phone'],
                    'password' => $data['password'],
                    'type' => CustomerType::Wholesale,
                    'phone_verified_at' => $verified ? now() : null,
                    'company_name' => $data['company_name'],
                    'tax_number' => $data['tax_number'],
                    'commercial_register' => $data['commercial_register'],
                ]);
                $customer->forceFill(['id' => $customerId, 'status' => CustomerStatus::Pending])->save();

                foreach ($staged as $document) {
                    $customer->documents()->create([
                        'document_type' => $document['document_type'],
                        'file_path' => $document['path'],
                        'original_name' => $document['original_name'],
                        'mime_type' => $document['mime_type'],
                        'status' => CustomerDocumentStatus::Pending,
                    ]);
                }

                CustomerAuditLog::record($customer, 'self_registered', null, ['channel' => 'wholesale']);
                DB::afterCommit(static function () use ($customer): void {
                    try {
                        WholesaleApplicationSubmitted::dispatch($customer);
                    } catch (\Throwable $exception) {
                        // The account is committed; a queue outage must not turn it into a failed registration.
                        report($exception);
                    }
                });

                return [
                    'customer' => $customer->load('documents'),
                    'token' => $this->auth->issueToken($customer, 'wholesale-token'),
                ];
            });
        } catch (\Throwable $e) {
            // Transaction failure: clean up uploaded files on cloud storage to prevent orphaned assets
            foreach ($storedPaths as $path) {
                try {
                    Storage::disk('r2')->delete($path);
                } catch (\Throwable $exception) {
                    report($exception);
                }
            }
            if ($storedPaths !== []) {
                try {
                    Storage::disk('r2')->deleteDirectory($stagingDirectory);
                } catch (\Throwable $exception) {
                    report($exception);
                }
            }

            throw $this->auth->translateRegistrationConflict($e); // M9 — الملفات اتمسحت فوق
        }

        try {
            Storage::disk('r2')->deleteDirectory($stagingDirectory);
        } catch (\Throwable $exception) {
            report($exception);
        }

        return $registration;
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Enums\PriceListType;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\PriceList;
use App\Models\PriceListItem;
use App\Models\ProductVariant;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Carbon\Carbon;
use Illuminate\Database\Eloquent\Builder;

/**
 * Central pricing engine across storefront, wholesale portal, POS, and admin backoffice.
 *
 * Evaluation hierarchy:
 * 1. Customer-specific price list (customer_specific)
 * 2. Customer group price list (customer_group)
 * 3. Channel price list (wholesale/distributor for approved accounts, otherwise retail).
 *    Wholesale/distributor channels without a matching item fall back to active retail lists.
 * 4. Channel base price (wholesale_price for wholesale/distributor, then retail_price).
 *
 * Customer group discount percentages apply on top of tier 3/4 channel outcomes without
 * overriding customer-specific or group-specific price lists.
 * Within each tier: branch-specific list first, highest qualifying min_qty, highest priority, lowest price.
 */
class PricingService
{
    private array $catalogContexts = [];

    /**
     * Resolves cache key and public visibility context for customer catalog listings.
     *
     * @return array{key: string, public_retail: bool}
     */
    public function catalogContext(?Customer $customer): array
    {
        if ($customer === null || $customer->status !== CustomerStatus::Approved) {
            return ['key' => 'retail', 'public_retail' => true];
        }

        return $this->catalogContexts[$customer->id] ??= $this->resolveCatalogContext($customer);
    }

    /**
     * Builds the unique catalog pricing context key for an approved customer.
     */
    private function resolveCatalogContext(Customer $customer): array
    {
        $customer->loadMissing('customerGroup');
        $group = $customer->customerGroup?->is_active ? $customer->customerGroup : null;
        $specific = PriceList::query()->where('type', PriceListType::CustomerSpecific)->where('customer_id', $customer->id)->exists();
        $channel = $this->channelFor($customer);
        $public = $channel === PriceListType::Retail && $group === null && ! $specific;

        return ['key' => $public ? 'retail' : $channel->value.':group:'.($group?->id ?? 'none').($specific ? ':customer:'.$customer->id : ''), 'public_retail' => $public];
    }

    /**
     * F17: preload the per-customer pricing context once per listing and pass
     * it down — resolve()/tiersFor() otherwise re-query the customer group on
     * every variant (15 products x variants x calls per page).
     *
     * @return array{channel: PriceListType, eligible: bool, group: object|null}
     */
    public function contextFor(?Customer $customer, ?array $variantIds = null): array
    {
        $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
        if ($eligible) {
            $customer->loadMissing('customerGroup');
        }
        $group = $eligible && $customer->customerGroup?->is_active ? $customer->customerGroup : null;

        $channel = $this->channelFor($customer);
        $context = ['channel' => $channel, 'eligible' => $eligible, 'group' => $group];
        if ($variantIds !== null) {
            $context['items'] = $this->eligibleItems(null, PHP_FLOAT_MAX, null, Carbon::now(), $variantIds)
                ->where(function ($q) use ($channel, $eligible, $customer, $group): void {
                    $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
                    if ($eligible) {
                        $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerSpecific)
                            ->where('price_lists.customer_id', $customer->id));
                    }
                    if ($group !== null) {
                        $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerGroup)
                            ->where('price_lists.customer_group_id', $group->id));
                    }
                })
                ->addSelect('price_lists.type as pricing_type', 'price_lists.branch_id as pricing_branch_id', 'price_lists.priority as pricing_priority')
                ->get()->groupBy('product_variant_id');
        }

        return $context;
    }

    /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
    public function withStorePrice(Builder $variants, ?Customer $customer): Builder
    {
        $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
        $channel = $this->channelFor($customer);
        $group = $eligible ? $customer->customerGroup : null;
        $group = $group?->is_active ? $group : null;
        $factor = $this->discountFactor($group?->discount_percentage ?? '0');
        $items = $this->eligibleItems(null, 1, null, Carbon::now())
            ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
                $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
                if ($eligible) {
                    $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
                        ->where('price_lists.customer_id', $customer->id));
                }
                if ($group !== null) {
                    $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
                        ->where('price_lists.customer_group_id', $group->id));
                }
            })
            ->select([])
            ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
            ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
        $items = $this->ordered($items)->limit(1);

        // M6: mirror basePrice() in SQL — the wholesale channel falls back to
        // wholesale_price first, then retail_price.
        $fallback = in_array($channel, [PriceListType::Wholesale, PriceListType::Distributor], true)
            ? 'COALESCE(product_variants.wholesale_price, product_variants.retail_price)'
            : 'product_variants.retail_price';

        // resolve() switches the basis to retail when a wholesale customer
        // falls back to a retail list. Preserve that effective channel in SQL.
        $baseItems = (clone $items)->select([])->selectRaw("COALESCE(CASE WHEN price_lists.type = 'retail' THEN product_variants.retail_price ELSE ".$fallback." END, price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END)", [$factor]);

        return $variants->select('product_variants.*')
            ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), '.$fallback.' * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor])
            ->selectRaw('ROUND(COALESCE(('.$baseItems->toSql().'), '.$fallback.')::numeric, 2) AS store_base_price', $baseItems->getBindings());
    }

    /**
     * Resolves the effective unit price, base reference price, and pricing source for a variant.
     *
     * @param  float  $qty  Purchasing quantity used for volume tier matching.
     * @param  int|null  $branchId  Optional branch restriction for branch-specific price lists.
     * @param  array{channel: PriceListType, eligible: bool, group: object|null, items?: \Illuminate\Support\Collection}|null  $ctx  Preloaded pricing context.
     * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
     * @throws BusinessException If quantity is non-positive or item has no valid price.
     */
    public function resolve(
        ProductVariant $variant,
        ?Customer $customer = null,
        float $qty = 1,
        ?int $branchId = null,
        ?array $ctx = null,
    ): array {
        if (! is_finite($qty) || $qty <= 0) {
            throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
        }
        $now = Carbon::now();

        // F17: reuse the preloaded per-customer context when the caller passes
        // it (wholesale listing); otherwise load it for this single call.
        $ctx ??= $this->contextFor($customer);
        $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
        $channel = $ctx['channel'];
        $eligibleCustomer = $ctx['eligible'];
        $pick = function (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null) use ($ctx, $variant, $qty, $baseQuery, $branchId): ?PriceListItem {
            if (isset($ctx['items']) && $branchId === null) {
                return ($ctx['items'][$variant->id] ?? collect())
                    ->filter(fn ($item) => $item->pricing_type === $type->value && (float) $item->min_qty <= $qty)
                    ->sort(function ($a, $b): int {
                        return (($a->pricing_branch_id === null) <=> ($b->pricing_branch_id === null))
                            ?: ((float) $b->min_qty <=> (float) $a->min_qty)
                            ?: ((int) $b->pricing_priority <=> (int) $a->pricing_priority)
                            ?: BigDecimal::of($a->price)->compareTo(BigDecimal::of($b->price))
                            ?: ((int) $a->id <=> (int) $b->id);
                    })->first();
            }

            return $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
                ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))->first();
        };

        // Priority 1: Customer-specific pricing.
        if ($eligibleCustomer) {
            $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);

            if ($item !== null) {
                return $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
            }
        }

        // Priority 2: Customer group pricing.
        $group = $ctx['group'];
        if ($group !== null) {
            $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);

            if ($item !== null) {
                return $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
            }
        }

        // Priority 3: Customer channel price list (wholesale, distributor, or retail).
        $item = $pick($channel);

        // Wholesale/distributor channels without matched items fall back to active retail price lists.
        if ($item === null && $channel !== PriceListType::Retail) {
            $item = $pick(PriceListType::Retail);

            if ($item !== null) {
                $channel = PriceListType::Retail;
            }
        }

        if ($item !== null) {
            $channelPrice = (string) $item->price;
            $channelListId = (int) $item->price_list_id;
            $channelSource = $channel->value;
        } elseif ($this->basePrice($variant, $channel) === null) {
            // Priority 4 is impossible: unpriced item without matching price list or base price.
            throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
        } else {
            // Priority 4: Channel base price when no price list matches.
            $channelPrice = $this->basePrice($variant, $channel);
            $channelListId = null;
            $channelSource = 'base_price';
        }

        // Apply customer group discount percentage on top of channel list/base price.
        if ($group !== null && (float) $group->discount_percentage > 0) {
            return $this->formatResponse(
                (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
                'customer_group_discount',
                $channelListId,
                $variant,
                $channel,
            );
        }

        return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
    }

    /**
     * Resolves the effective unit price with a per-layer explanation waterfall.
     *
     * @return array{final: array, layers: list<array>, notes: list<string>}
     */
    public function trace(ProductVariant $variant, ?Customer $customer = null, float $qty = 1, ?int $branchId = null, ?array $ctx = null): array
    {
        if (! is_finite($qty) || $qty <= 0) {
            throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
        }
        $now = Carbon::now();
        $ctx ??= $this->contextFor($customer);
        $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
        $channel = $ctx['channel'];
        $eligibleCustomer = $ctx['eligible'];
        $group = $ctx['group'];
        $layers = [];
        $notes = [];

        if ($customer !== null
            && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
            && $customer->status !== CustomerStatus::Approved) {
            $notes[] = 'العميل جملة لكنه مش معتمد، فاتسعّر قطاعي.';
        }

        $pick = function (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null) use ($ctx, $variant, $qty, $baseQuery, $branchId): ?PriceListItem {
            if (isset($ctx['items']) && $branchId === null) {
                return ($ctx['items'][$variant->id] ?? collect())
                    ->filter(fn ($item) => $item->pricing_type === $type->value && (float) $item->min_qty <= $qty)
                    ->sort(function ($a, $b): int {
                        return (($a->pricing_branch_id === null) <=> ($b->pricing_branch_id === null))
                            ?: ((float) $b->min_qty <=> (float) $a->min_qty)
                            ?: ((int) $b->pricing_priority <=> (int) $a->pricing_priority)
                            ?: BigDecimal::of($a->price)->compareTo(BigDecimal::of($b->price))
                            ?: ((int) $a->id <=> (int) $b->id);
                    })->first();
            }

            return $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
                ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))->first();
        };

        $tieNote = function (PriceListType $type, ?string $ownerField, ?int $ownerId, ?PriceListItem $winner) use ($ctx, $variant, $qty, $baseQuery, $branchId, &$notes): void {
            if ($winner === null || (isset($ctx['items']) && $branchId === null)) {
                return;
            }
            $top = $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
                ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))
                ->limit(2)->get(['price_list_items.id', 'price_list_items.min_qty', 'price_list_items.price', 'price_lists.priority', 'price_lists.branch_id']);
            if ($top->count() === 2
                && (int) $top[0]->priority === (int) $top[1]->priority
                && (float) $top[0]->min_qty === (float) $top[1]->min_qty
                && ($top[0]->branch_id === null) === ($top[1]->branch_id === null)
                && (float) $top[0]->price !== (float) $top[1]->price) {
                $notes[] = 'فيه قائمتين بنفس الأولوية، فكسبت الأرخص.';
            }
        };

        $skippedRest = function (array $names) use (&$layers): void {
            foreach ($names as $n) {
                $layers[] = ['layer' => $n, 'status' => 'skipped', 'reason' => 'طبقة أعلى كسبت.'];
            }
        };

        if (! $eligibleCustomer) {
            $layers[] = ['layer' => 'customer_specific', 'status' => 'not_eligible', 'reason' => 'العميل مش معتمد أو زائر، فقوائم العملاء الخاصة مش بتتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
            if ($customer !== null) {
                $specificId = PriceList::query()->where('type', PriceListType::CustomerSpecific)->where('customer_id', $customer->id)->orderByDesc('id')->value('id');
                if ($specificId !== null) {
                    $notes[] = "عنده قائمة خاصة رقم {$specificId}، بس العميل مش approved، فالقائمة دي مش بتتطبق.";
                }
            }
        } else {
            $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);
            if ($item !== null) {
                $tieNote(PriceListType::CustomerSpecific, 'customer_id', $customer->id, $item);
                $layers[] = ['layer' => 'customer_specific', 'status' => 'won', 'reason' => 'قائمة العميل الخاصة كسبت.', 'price_list_id' => (int) $item->price_list_id, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
                $skippedRest(['customer_group', 'channel', 'retail_fallback', 'base_price']);
                $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'خصم المجموعة 10% ماتطبقش لأن السعر جه من قائمة المجموعة نفسها.'];
                $final = $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);

                return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
            }
            $layers[] = ['layer' => 'customer_specific', 'status' => 'no_match', 'reason' => 'مفيش بند مطابق في قائمة العميل الخاصة.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if ($group === null) {
            $layers[] = ['layer' => 'customer_group', 'status' => 'not_eligible', 'reason' => 'العميل مش في مجموعة نشطة، فقوائم المجموعات مش بتتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        } else {
            $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);
            if ($item !== null) {
                $tieNote(PriceListType::CustomerGroup, 'customer_group_id', $group->id, $item);
                $layers[] = ['layer' => 'customer_group', 'status' => 'won', 'reason' => 'قائمة المجموعة كسبت.', 'price_list_id' => (int) $item->price_list_id, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
                $skippedRest(['channel', 'retail_fallback', 'base_price']);
                $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'خصم المجموعة 10% ماتطبقش لأن السعر جه من قائمة المجموعة نفسها.'];
                $final = $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);

                return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
            }
            $layers[] = ['layer' => 'customer_group', 'status' => 'no_match', 'reason' => 'مفيش بند مطابق في قائمة المجموعة.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        $item = $pick($channel);
        $channelWon = false;
        $channelPrice = null;
        $channelListId = null;
        $channelSource = $channel->value;
        if ($item !== null) {
            $tieNote($channel, null, null, $item);
            $channelWon = true;
            $channelPrice = (string) $item->price;
            $channelListId = (int) $item->price_list_id;
            $layers[] = ['layer' => 'channel', 'status' => 'won', 'reason' => "قائمة القناة ({$channel->value}) كسبت.", 'price_list_id' => $channelListId, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
        } else {
            $layers[] = ['layer' => 'channel', 'status' => 'no_match', 'reason' => "مفيش بند مطابق في قائمة القناة ({$channel->value}).", 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if (! $channelWon && $channel !== PriceListType::Retail) {
            $retailItem = $pick(PriceListType::Retail);
            if ($retailItem !== null) {
                $tieNote(PriceListType::Retail, null, null, $retailItem);
                $channel = PriceListType::Retail;
                $channelWon = true;
                $channelPrice = (string) $retailItem->price;
                $channelListId = (int) $retailItem->price_list_id;
                $channelSource = $channel->value;
                $layers[] = ['layer' => 'retail_fallback', 'status' => 'won', 'reason' => 'القناة وقعت على قائمة قطاعي بديلة.', 'price_list_id' => $channelListId, 'price' => (float) $retailItem->price, 'min_qty' => (float) $retailItem->min_qty];
            } else {
                $layers[] = ['layer' => 'retail_fallback', 'status' => 'no_match', 'reason' => 'مفيش بند قطاعي بديل.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
            }
        } else {
            $layers[] = ['layer' => 'retail_fallback', 'status' => 'skipped', 'reason' => $channelWon ? 'القناة كسبت، فمش محتاج بديل قطاعي.' : 'القناة قطاعي بالفعل.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if (! $channelWon) {
            $base = $this->basePrice($variant, $channel);
            if ($base === null) {
                throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
            }
            $channelPrice = $base;
            $channelListId = null;
            $channelSource = 'base_price';
            $layers[] = ['layer' => 'base_price', 'status' => 'won', 'reason' => 'مفيش قوائم مطابقة، فاتسعّر بالسعر الأساسي.', 'price_list_id' => null, 'price' => (float) $base, 'min_qty' => null];
        } else {
            $layers[] = ['layer' => 'base_price', 'status' => 'skipped', 'reason' => 'قائمة كسبت، فالسعر الأساسي مش مستخدم.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if ($group !== null && (float) $group->discount_percentage > 0) {
            $layers[] = ['layer' => 'group_discount', 'status' => 'won', 'reason' => "خصم المجموعة {$group->discount_percentage}% اتطبق على سعر القناة/الأساسي.", 'price_list_id' => $channelListId, 'price' => null, 'min_qty' => null];
            $final = $this->formatResponse(
                (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
                'customer_group_discount',
                $channelListId,
                $variant,
                $channel,
            );

            return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
        }

        $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'مفيش خصم مجموعة يتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        $final = $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);

        return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
    }

    /**
     * Returns the step-ladder volume pricing tiers applicable to a customer for a variant.
     *
     * @return list<array{min_qty: float, unit_price: float}>}
     *
     * @return list<array{min_qty: float, unit_price: float}>
     */
    public function tiersFor(ProductVariant $variant, ?Customer $customer, ?array $ctx = null, ?int $branchId = null): array
    {
        $now = Carbon::now();
        // F17: reuse the preloaded per-customer context when available.
        $ctx ??= $this->contextFor($customer);
        $channel = $ctx['channel'];
        $eligible = $ctx['eligible'];
        $groupId = $ctx['group']?->id;

        $breakpoints = isset($ctx['items']) && $branchId === null
            ? ($ctx['items'][$variant->id] ?? collect())->pluck('min_qty')->map(fn ($v) => (float) $v)
            : $this->eligibleItems($variant, PHP_FLOAT_MAX, $branchId, $now)
                ->where(function ($q) use ($eligible, $customer, $groupId, $channel): void {
                    $q->where('price_lists.type', $channel->value)
                        ->orWhere('price_lists.type', PriceListType::Retail->value);
                    if ($eligible) {
                        $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
                            ->where('price_lists.customer_id', $customer->id));
                    }
                    if ($groupId !== null) {
                        $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
                            ->where('price_lists.customer_group_id', $groupId));
                    }
                })
                ->pluck('price_list_items.min_qty')
                ->map(fn ($v) => (float) $v)
                ->unique()
                ->sort()
                ->values();

        $points = collect([1.0])->merge($breakpoints)->unique()->sort()->values();

        return $points
            ->map(fn (float $minQty) => [
                'min_qty' => $minQty,
                'unit_price' => $this->resolve($variant, $customer, max(1.0, $minQty), $branchId, $ctx)['unit_price'],
            ])
            ->values()
            ->all();
    }

    /**
     * Resolves the pricing channel enum: approved wholesale/distributor accounts use their channel; all others use Retail.
     */
    private function channelFor(?Customer $customer): PriceListType
    {
        if ($customer !== null
            && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
            && $customer->status === CustomerStatus::Approved) {
            return PriceListType::from($customer->type->value);
        }

        return PriceListType::Retail;
    }

    private function basePrice(ProductVariant $variant, PriceListType $channel): ?string
    {
        // M6: wholesale_price is the wholesale-channel fallback. Retail stays
        // on retail_price; wholesale/distributor prefer wholesale_price and
        // fall back to retail_price when it is missing.
        if (in_array($channel, [PriceListType::Wholesale, PriceListType::Distributor], true)
            && $variant->wholesale_price !== null) {
            return (string) $variant->wholesale_price;
        }

        return $variant->retail_price === null ? null : $variant->base_price;
    }

    /**
     * Returns the base catalog reference price for a variant under the customer's channel.
     */
    public function basePriceForCustomer(ProductVariant $variant, ?Customer $customer): ?string
    {
        return $this->basePrice($variant, $this->channelFor($customer));
    }

    /**
     * Converts a percentage discount string (e.g. "15.00") into a decimal multiplication factor (0.85).
     */
    private function discountFactor(string $percentage): string
    {
        return (string) BigDecimal::of('100')->minus($percentage)->dividedBy('100', 8);
    }

    /**
     * Query scope for active price list items matching variant, quantity threshold, branch, and current time.
     */
    private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now, ?array $variantIds = null): Builder
    {
        return PriceListItem::query()
            ->select('price_list_items.*')
            ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
            ->where('price_lists.is_active', true)
            ->when($variant !== null,
                fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
                fn ($q) => $variantIds !== null
                    ? $q->whereIn('price_list_items.product_variant_id', $variantIds)
                    : $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
            ->where('price_list_items.min_qty', '<=', $qty)
            ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
            ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
            ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
            ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
            ->where(function ($q) use ($branchId): void {
                $q->whereNull('price_lists.branch_id');
                if ($branchId !== null) {
                    $q->orWhere('price_lists.branch_id', $branchId);
                }
            });
    }

    /**
     * Sorts candidate price list items: branch-specific first, highest min_qty, highest priority, lowest price.
     */
    private function ordered(Builder $query): Builder
    {
        return $query
            ->orderByRaw('price_lists.branch_id IS NULL ASC')
            ->orderByDesc('price_list_items.min_qty')
            ->orderByDesc('price_lists.priority')
            ->orderBy('price_list_items.price')->orderBy('price_list_items.id');
    }

    /**
     * Formats rounded pricing amounts and metadata into standard pricing response payload.
     *
     * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
     */
    private function formatResponse(string|float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
    {
        return [
            'unit_price' => (float) (string) BigDecimal::of((string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
            'base_price' => (float) (string) BigDecimal::of($this->basePrice($variant, $channel) ?? (string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
            'source' => $source,
            'price_list_id' => $priceListId,
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\OrderStatus;
use App\Enums\QuotationStatus;
use App\Events\OrderCreated;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\Order;
use App\Models\OrderStatusHistory;
use App\Models\ProductVariant;
use App\Models\Quotation;
use App\Models\User;
use Illuminate\Support\Facades\DB;

/**
 * Manages the wholesale quotation lifecycle:
 * Draft creation with dynamic pricing -> customer submission -> administrator pricing and validation ->
 * customer acceptance with automated order generation and stock allocation, or rejection/expiry.
 *
 * Quotations hold no inventory reservations; stock allocation occurs only upon customer acceptance.
 */
class QuotationService
{
    public function __construct(
        private readonly SettingService $settings,
        private readonly PricingService $pricing,
        private readonly OrderService $orders,
        private readonly OrderAllocationService $allocation,
    ) {}

    /**
     * Create a new draft quotation for a wholesale customer.
     *
     * @param  Customer  $customer
     * @param  array{customer_notes?: string|null, items: list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>}  $data
     * @return Quotation
     */
    public function create(Customer $customer, array $data): Quotation
    {
        return DB::transaction(function () use ($customer, $data): Quotation {
            $quotation = Quotation::create([
                'quotation_number' => $this->settings->generateNextNumber('quotation'),
                'customer_id' => $customer->id,
                'status' => QuotationStatus::Draft,
                'customer_notes' => $data['customer_notes'] ?? null,
            ]);

            $this->syncItems($quotation, $customer, $data['items']);
            $this->recalculate($quotation);

            return $quotation->load('items.variant.product');
        });
    }

    /**
     * Update items and customer notes on an unsubmitted draft quotation.
     *
     * @param  Quotation  $quotation
     * @param  array{customer_notes?: string|null, items?: list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>}  $data
     * @return Quotation
     *
     * @throws BusinessException
     */
    public function update(Quotation $quotation, array $data): Quotation
    {
        if ($quotation->status !== QuotationStatus::Draft) {
            throw new BusinessException('لا يمكن تعديل عرض السعر إلا وهو مسودة.');
        }

        return DB::transaction(function () use ($quotation, $data): Quotation {
            $quotation->update([
                'customer_notes' => $data['customer_notes'] ?? $quotation->customer_notes,
            ]);

            if (isset($data['items'])) {
                $quotation->items()->delete();
                $this->syncItems($quotation, $quotation->customer, $data['items']);
            }

            $this->recalculate($quotation);

            return $quotation->load('items.variant.product');
        });
    }

    /**
     * Submit a draft quotation for administrator pricing and review.
     *
     * @param  Quotation  $quotation
     * @return Quotation
     *
     * @throws BusinessException
     */
    public function submit(Quotation $quotation): Quotation
    {
        if ($quotation->status !== QuotationStatus::Draft) {
            throw new BusinessException('لا يمكن إرسال عرض السعر إلا من حالة المسودة.');
        }

        if ($quotation->items()->count() === 0) {
            throw new BusinessException('لا يمكن إرسال عرض سعر بلا بنود.');
        }

        $quotation->update(['status' => QuotationStatus::Requested]);

        return $quotation->load('items.variant.product');
    }

    /**
     * Set negotiated prices, validity expiration, discounts, and taxes by an administrator.
     *
     * @param  Quotation  $quotation
     * @param  array{valid_until?: string|null, admin_notes?: string|null, discount_amount?: float|null, tax_amount?: float|null, items?: list<array{id: int, offered_unit_price: float}>}  $data
     * @return Quotation
     *
     * @throws BusinessException
     */
    public function price(Quotation $quotation, array $data): Quotation
    {
        if ($quotation->status !== QuotationStatus::Requested) {
            throw new BusinessException('لا يمكن تسعير عرض السعر إلا بعد إرساله من التاجر.');
        }

        return DB::transaction(function () use ($quotation, $data): Quotation {
            foreach ($data['items'] ?? [] as $row) {
                $item = $quotation->items()->whereKey($row['id'])->first();

                if ($item === null) {
                    throw new BusinessException('أحد بنود التسعير لا ينتمي لعرض السعر هذا.');
                }

                $item->update([
                    'offered_unit_price' => $row['offered_unit_price'],
                    'line_total' => round((float) $row['offered_unit_price'] * (float) $item->qty, 2),
                ]);
            }

            $quotation->update([
                'status' => QuotationStatus::PricedByAdmin,
                'valid_until' => $data['valid_until'] ?? $quotation->valid_until,
                'admin_notes' => $data['admin_notes'] ?? $quotation->admin_notes,
                'discount_amount' => $data['discount_amount'] ?? $quotation->discount_amount,
                'tax_amount' => $data['tax_amount'] ?? $quotation->tax_amount,
            ]);

            $this->recalculate($quotation);

            return $quotation->load('items.variant.product');
        });
    }

    /**
     * Accept an administrator-priced quotation and automatically convert it into a confirmed order.
     *
     * Preserves negotiated line prices, distributes header discounts/taxes using Hare-Niemeyer,
     * and allocates inventory. Fails the conversion entirely if any item lacks available stock.
     *
     * @param  Quotation  $quotation
     * @return Quotation
     *
     * @throws BusinessException
     */
    public function accept(Quotation $quotation): Quotation
    {
        if ($quotation->status !== QuotationStatus::PricedByAdmin) {
            throw new BusinessException('لا يمكن قبول عرض السعر إلا بعد تسعير الإدارة له.');
        }

        if ($quotation->valid_until !== null && $quotation->valid_until->lt(now()->startOfDay())) {
            $quotation->update(['status' => QuotationStatus::Expired]);

            throw new BusinessException('انتهت صلاحية عرض السعر هذا.');
        }

        return DB::transaction(function () use ($quotation): Quotation {
            $quotation->loadMissing(['customer', 'items.variant.product']);
            $customer = $quotation->customer;

            // Converted order is deferred credit; reject acceptance if customer credit limit would be breached.
            Customer::query()->whereKey($customer->id)->lockForUpdate()->first();
            $outstanding = app(WholesalePaymentNoticeService::class)->outstandingBalance($customer->fresh());
            if ($outstanding + (float) $quotation->grand_total > (float) $customer->credit_limit) {
                throw new BusinessException(
                    'إجمالي الطلب يتجاوز حد الائتمان المتاح.',
                    [],
                    422,
                    'credit_limit_exceeded',
                );
            }

            $order = Order::create([
                'order_number' => $this->settings->generateNextNumber('order'),
                'channel' => 'wholesale',
                'customer_id' => $customer->id,
                'guest_name' => $customer->name,
                'guest_phone' => $customer->phone,
                'guest_phone_normalized' => Customer::normalizePhone((string) $customer->phone),
                'guest_email' => $customer->email,
                'status' => OrderStatus::Pending,
                'payment_method' => 'credit',
                'payment_status' => 'unpaid',
                'subtotal' => $quotation->subtotal,
                'discount_amount' => $quotation->discount_amount,
                'shipping_cost' => 0,
                'cod_fee' => 0,
                'tax_amount' => $quotation->tax_amount,
                'grand_total' => $quotation->grand_total,
            ]);

            // Distribute header discount and tax to items using largest remainder for exact cent precision
            $weights = $quotation->items->map(fn ($item) => (float) $item->line_total)->all();
            $discountShares = $this->distributeLargestRemainder((float) $quotation->discount_amount, $weights);
            $taxShares = $this->distributeLargestRemainder((float) $quotation->tax_amount, $weights);

            foreach ($quotation->items->values() as $i => $item) {
                $order->items()->create([
                    'product_variant_id' => $item->product_variant_id,
                    'product_name_snapshot' => $item->variant->product?->name_ar ?? '',
                    'sku_snapshot' => $item->variant->sku,
                    'qty' => $item->qty,
                    'unit_price' => $item->offered_unit_price,
                    'discount_amount' => $discountShares[$i],
                    'tax_amount' => $taxShares[$i],
                    'line_total' => $item->line_total,
                ]);
            }

            OrderStatusHistory::create([
                'order_id' => $order->id,
                'from_status' => null,
                'to_status' => OrderStatus::Pending,
                'changed_by_type' => Customer::class,
                'changed_by_id' => $customer->id,
                'notes' => "أُنشئ من عرض السعر {$quotation->quotation_number}",
            ]);

            $order->load('items');
            $this->allocation->allocate($order, performedBy: $this->systemActorId());

            $this->orders->changeStatus($order, OrderStatus::Confirmed, $customer, "قبول عرض السعر {$quotation->quotation_number}");

            $quotation->update([
                'status' => QuotationStatus::ConvertedToOrder,
                'converted_order_id' => $order->id,
            ]);

            OrderCreated::dispatch($order->fresh());

            return $quotation->load(['items.variant.product', 'convertedOrder']);
        });
    }

    /**
     * Retrieve the designated system user ID for recording customer-initiated ledger movements.
     */
    private function systemActorId(): ?int
    {
        $id = User::query()
            ->where('is_system', true)
            ->value('id');

        return $id !== null ? (int) $id : null;
    }

    /**
     * Distribute an amount proportionally across weights using the Largest Remainder (Hare-Niemeyer) method.
     *
     * Ensures line item shares sum exactly to the header amount with zero rounding discrepancies.
     *
     * @param  float  $amount
     * @param  list<float>  $weights
     * @return list<float>
     */
    private function distributeLargestRemainder(float $amount, array $weights): array
    {
        return ProportionalDistribution::distribute($amount, $weights);
    }

    /**
     * Reject a submitted or priced quotation.
     *
     * @param  Quotation  $quotation
     * @return Quotation
     *
     * @throws BusinessException
     */
    public function reject(Quotation $quotation): Quotation
    {
        if (! in_array($quotation->status, [QuotationStatus::Requested, QuotationStatus::PricedByAdmin], true)) {
            throw new BusinessException('لا يمكن رفض عرض السعر في حالته الحالية.');
        }

        $quotation->update(['status' => QuotationStatus::Rejected]);

        return $quotation->load('items.variant.product');
    }

    /**
     * Expire a past-due quotation.
     *
     * @param  Quotation  $quotation
     * @return Quotation
     *
     * @throws BusinessException
     */
    public function expire(Quotation $quotation): Quotation
    {
        if (! in_array($quotation->status, [QuotationStatus::Requested, QuotationStatus::PricedByAdmin], true)) {
            throw new BusinessException('لا يمكن إنهاء صلاحية عرض السعر في حالته الحالية.');
        }

        $quotation->update(['status' => QuotationStatus::Expired]);

        return $quotation->load('items.variant.product');
    }

    /**
     * Delete an unsubmitted draft quotation.
     *
     * @param  Quotation  $quotation
     * @return void
     *
     * @throws BusinessException
     */
    public function deleteDraft(Quotation $quotation): void
    {
        if ($quotation->status !== QuotationStatus::Draft) {
            throw new BusinessException('لا يمكن حذف عرض السعر إلا وهو مسودة.');
        }

        $quotation->delete();
    }

    /**
     * @param  list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>  $items
     */
    private function syncItems(Quotation $quotation, Customer $customer, array $items): void
    {
        $variantIds = collect($items)->pluck('product_variant_id')->unique()->all();
        $variants = ProductVariant::query()->whereIn('id', $variantIds)->get()->keyBy('id');

        foreach ($items as $row) {
            $variant = $variants->get($row['product_variant_id']);

            if ($variant === null || ! $variant->is_active) {
                throw new BusinessException('أحد المتغيرات المطلوبة غير موجود أو غير نشط.');
            }

            $offered = $this->pricing->resolve($variant, $customer, (float) $row['qty'])['unit_price'];

            $quotation->items()->create([
                'product_variant_id' => $variant->id,
                'qty' => $row['qty'],
                'requested_target_price' => $row['requested_target_price'] ?? null,
                'offered_unit_price' => $offered,
                'line_total' => round($offered * (float) $row['qty'], 2),
            ]);
        }
    }

    private function recalculate(Quotation $quotation): void
    {
        $subtotal = (float) $quotation->items()->sum('line_total');
        $grandTotal = round($subtotal - (float) $quotation->discount_amount + (float) $quotation->tax_amount, 2);

        if ($grandTotal < 0) {
            throw new BusinessException('إجمالي عرض السعر لا يمكن أن يكون سالبًا — راجع الخصم.');
        }

        $quotation->update([
            'subtotal' => $subtotal,
            'grand_total' => $grandTotal,
        ]);
    }
}<?php

declare(strict_types=1);

use App\Http\Controllers\Api\V1\AttachmentController;
use App\Http\Controllers\Api\V1\Shared\NotificationController;
use App\Http\Controllers\Api\V1\Wholesale\DashboardController;
use App\Http\Controllers\Api\V1\Wholesale\InvoiceController;
use App\Http\Controllers\Api\V1\Wholesale\OrderController;
use App\Http\Controllers\Api\V1\Wholesale\PaymentNoticeController;
use App\Http\Controllers\Api\V1\Wholesale\ProductController;
use App\Http\Controllers\Api\V1\Wholesale\QuickOrderController;
use App\Http\Controllers\Api\V1\Wholesale\QuotationController;
use App\Http\Controllers\Api\V1\Wholesale\RegisterController;
use Illuminate\Support\Facades\Route;

Route::prefix('auth')->name('auth.')->group(function (): void {
    // التسجيل ورفع المستندات لتاجر الجملة
    Route::post('register', [RegisterController::class, 'register'])->middleware('throttle:customer-registration')->name('register');

    // متابعة حالة الطلب (يتطلب توكن عميل فقط، ولا يتطلب wholesale.approved)
    Route::middleware(['auth:sanctum', 'auth.customer'])->group(function (): void {
        Route::get('application-status', [RegisterController::class, 'applicationStatus'])->name('application-status');
        // H-1: إعادة رفع بديل للمستند المرفوض لتاجر pending.
        Route::post('documents', [RegisterController::class, 'uploadDocument'])
            ->middleware('throttle:customer-registration')->name('documents.store');
    });
});

// بوابة الجملة المتقدمة (المرحلتان 12 و13): الحماية الثلاثية إلزامية — لا يصل
// أي عميل قطاعي أو تاجر قيد المراجعة إلى أسعار الجملة وشرائح الكميات والسداد الآجل.
Route::middleware(['auth:sanctum', 'auth.customer', 'wholesale.approved'])->group(function (): void {
    Route::get('dashboard', [DashboardController::class, 'index'])->name('dashboard');

    // الكتالوج وتصدير قوائم الأسعار PDF / Excel
    Route::get('products', [ProductController::class, 'index'])->name('products.index');
    Route::get('price-list/export', [ProductController::class, 'exportPriceList'])->name('price-list.export');

    // الطلب السريع واستيراد Excel وإعادة الطلب
    Route::post('quick-order/lookup', [QuickOrderController::class, 'lookup'])->name('quick-order.lookup');
    Route::post('quick-order/import', [QuickOrderController::class, 'import'])->name('quick-order.import');
    Route::post('quick-order/add-to-cart', [QuickOrderController::class, 'addToCart'])->name('quick-order.add-to-cart');
    Route::get('orders', [OrderController::class, 'index'])->name('orders.index');
    Route::get('orders/{order}', [OrderController::class, 'show'])->whereNumber('order')->name('orders.show');
    Route::post('orders/{order}/reorder', [OrderController::class, 'reorder'])->whereNumber('order')->name('orders.reorder');

    // الفواتير، كشف الحساب، وإشعارات السداد البنكي
    Route::get('invoices', [InvoiceController::class, 'index'])->name('invoices.index');
    Route::get('invoices/{order}/pdf', [InvoiceController::class, 'pdf'])->whereNumber('order')->name('invoices.pdf');
    Route::get('statement', [InvoiceController::class, 'statement'])->name('statement');
    Route::post('payment-notices', [InvoiceController::class, 'storePaymentNotice'])->name('payment-notices.store');
    // قراءة الإشعارات والمديونية وتنزيل الإيصالات (تكملة من 12.1)
    Route::get('payment-notices', [PaymentNoticeController::class, 'index'])->name('payment-notices.index');
    Route::get('payment-notices/outstanding', [PaymentNoticeController::class, 'outstanding'])->name('payment-notices.outstanding');
    Route::get('payment-notices/{payment_notice}', [PaymentNoticeController::class, 'show'])->whereNumber('payment_notice')->name('payment-notices.show');
    Route::get('payment-notices/{notice}/receipt', [AttachmentController::class, 'paymentNotice'])->whereNumber('notice')->name('payment-notices.receipt');

    // عروض الأسعار (submit خطوة التاجر قبل تسعير الإدارة — من 12.1)
    Route::apiResource('quotations', QuotationController::class)->parameters(['quotations' => 'quotation']);
    Route::post('quotations/{quotation}/submit', [QuotationController::class, 'submit'])->whereNumber('quotation')->name('quotations.submit');
    Route::post('quotations/{quotation}/accept', [QuotationController::class, 'accept'])->whereNumber('quotation')->name('quotations.accept');
    Route::post('quotations/{quotation}/reject', [QuotationController::class, 'reject'])->whereNumber('quotation')->name('quotations.reject');

    // الإشعارات (المرحلة 13)
    Route::get('notifications', [NotificationController::class, 'index'])->name('notifications.index');
    Route::post('notifications/{id}/read', [NotificationController::class, 'markAsRead'])->name('notifications.read');
    Route::post('notifications/read-all', [NotificationController::class, 'readAll'])->name('notifications.read-all');
});<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Admin\Ai;

use App\Http\Controllers\Controller;
use App\Models\AiConversation;
use App\Services\Ai\AgentOrchestrator;
use App\Services\Ai\GeminiException;
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
use Symfony\Component\HttpFoundation\StreamedResponse;
use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface;

class AiMessageController extends Controller
{
    public function stream(Request $request, AiConversation $conversation, AgentOrchestrator $orchestrator): StreamedResponse
    {
        abort_unless($conversation->user_id === $request->user('staff')->id, 403);
        $data = $this->validated($request);
        $orchestrator->guard($request->user('staff'));

        return response()->stream(function () use ($request, $conversation, $orchestrator, $data): void {
            $emit = static function (string $event, array $payload): void {
                echo 'event: '.$event."\n".'data: '.json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)."\n\n";
                if (ob_get_level() > 0) {
                    ob_flush();
                }
                flush();
            };
            try {
                $reply = $orchestrator->handle($request->user('staff'), $conversation, $data, fn ($status) => $emit('status', ['message' => $status]));
                $emit('reply', ['text' => $reply->text, 'ui_blocks' => $reply->blocks, 'message_id' => $reply->messageId]);
            } catch (\Throwable $e) {
                // L-9: AuthorizationException وValidationException ليستا
                // HttpExceptionInterface، فكانتا تُعرضان كـ 502 مع report().
                // صنّفهما لرمزيهما الصحيحين بلا تقرير.
                $status = match (true) {
                    $e instanceof HttpExceptionInterface => $e->getStatusCode(),
                    $e instanceof AuthorizationException => 403,
                    $e instanceof ValidationException => 422,
                    default => 502,
                };
                if ($status >= 500) {
                    report($e);
                }
                $emit('error', ['message' => $status < 500 ? $e->getMessage() : 'تعذر إتمام طلب المساعد. حاول مرة تانية.', 'status' => $status]);
            }
        }, 200, ['Content-Type' => 'text/event-stream', 'Cache-Control' => 'no-cache, no-store', 'X-Accel-Buffering' => 'no']);
    }

    public function store(Request $request, AiConversation $conversation, AgentOrchestrator $orchestrator): JsonResponse
    {
        abort_unless($conversation->user_id === $request->user('staff')->id, 403);
        $data = $this->validated($request);
        try {
            $reply = $orchestrator->handle($request->user('staff'), $conversation, $data);
        } catch (GeminiException $e) {
            return response()->json(['message' => $e->getMessage()], 502);
        }

        return response()->json(['data' => ['text' => $reply->text, 'ui_blocks' => $reply->blocks, 'message_id' => $reply->messageId]]);
    }

    private function validated(Request $request): array
    {
        return $request->validate([
            'text' => ['nullable', 'string', 'max:8000'],
            'selection' => ['nullable', 'array:entity,id,label'], 'selection.entity' => ['required_with:selection', 'in:branch,user,role,permission,location,customer,customer_group,category,product,variant,transfer,stocktake,production_receipt'], 'selection.id' => ['required_with:selection', Rule::when($request->input('selection.entity') !== 'permission', ['integer', 'min:1'], ['string', 'max:255'])], 'selection.label' => ['nullable', 'string', 'max:255'],
            'mentions' => ['nullable', 'array', 'max:25'], 'mentions.*.entity' => ['required', 'in:branch,user,role,location,customer,category,product,variant,transfer,stocktake,production_receipt'], 'mentions.*.id' => ['required', 'integer', 'min:1'],
            'attachments' => ['nullable', 'array', 'max:4'], 'attachments.*' => ['required', 'string', 'ulid', 'distinct'],
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\OrderStatus;
use App\Models\PosShift;
use Database\Factories\OrderFactory;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * طلب. أي تغيير في status يجب أن يمر عبر OrderService::changeStatus()
 * حصرًا — هي التي تسجل التغيير في order_status_histories وتطلق الحجز
 * والتوزيع عند الانتقال إلى confirmed.
 */
class Order extends Model
{
    /** @use HasFactory<OrderFactory> */
    use HasFactory, SoftDeletes;

    protected $fillable = [
        'order_number',
        'channel',
        'customer_id',
        'guest_name',
        'guest_phone',
        'guest_phone_normalized',
        'guest_email',
        'city_id',
        'shipping_address_line',
        'shipping_notes',
        'allocated_branch_id',
        'pos_shift_id',
        'return_of_order_id',
        'status',
        'payment_method',
        'payment_status',
        'requires_refund',
        'needs_attention',
        'cod_fee',
        'idempotency_key',
        'idempotency_scope',
        'gateway_order_id',
        'subtotal',
        'discount_amount',
        'coupon_id',
        'coupon_code',
        'shipping_cost',
        'tax_amount',
        'grand_total',
        'cash_amount',
        'card_amount',
    ];

    protected function casts(): array
    {
        return [
            'status'          => OrderStatus::class,
            'subtotal'        => 'decimal:2',
            'discount_amount' => 'decimal:2',
            'shipping_cost'   => 'decimal:2',
            'cod_fee'         => 'decimal:2',
            'tax_amount'      => 'decimal:2',
            'grand_total'     => 'decimal:2',
            'cash_amount'     => 'decimal:2',
            'card_amount'     => 'decimal:2',
            'requires_refund' => 'boolean',
            'needs_attention' => 'boolean',
        ];
    }

    /** @return \Illuminate\Database\Eloquent\Relations\BelongsTo<\App\Models\PosShift, $this> */
    public function posShift(): \Illuminate\Database\Eloquent\Relations\BelongsTo
    {
        return $this->belongsTo(PosShift::class);
    }

    /** @return HasMany<OrderItem, $this> */
    public function items(): HasMany
    {
        return $this->hasMany(OrderItem::class);
    }

    /** @return HasMany<OrderStatusHistory, $this> */
    public function statusHistories(): HasMany
    {
        return $this->hasMany(OrderStatusHistory::class)->latest('id');
    }

    /** @return HasMany<Shipment, $this> */
    public function shipments(): HasMany
    {
        return $this->hasMany(Shipment::class);
    }

    /** @return HasMany<ReturnRequest, $this> */
    public function returnRequests(): HasMany
    {
        return $this->hasMany(ReturnRequest::class);
    }

    /** @return BelongsTo<Customer, $this> */
    public function customer(): BelongsTo
    {
        return $this->belongsTo(Customer::class);
    }

    /** @return BelongsTo<City, $this> */
    public function city(): BelongsTo
    {
        return $this->belongsTo(City::class);
    }

    /** @return BelongsTo<Branch, $this> */
    public function allocatedBranch(): BelongsTo
    {
        return $this->belongsTo(Branch::class, 'allocated_branch_id');
    }

    /**
     * Determine whether the given phone number matches this order (guest or customer).
     */
    public function matchesPhone(string $phone): bool
    {
        $normalized = Customer::normalizePhone($phone);

        if ($this->guest_phone_normalized !== null && $this->guest_phone_normalized === $normalized) {
            return true;
        }

        if ($this->guest_phone !== null && Customer::normalizePhone($this->guest_phone) === $normalized) {
            return true;
        }

        if ($this->customer?->phone !== null && Customer::normalizePhone((string) $this->customer->phone) === $normalized) {
            return true;
        }

        return false;
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerDocumentStatus;
use App\Enums\CustomerDocumentType;
use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Events\WholesaleApplicationReviewed;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\CustomerAuditLog;
use App\Models\CustomerDocument;
use App\Models\CustomerGroup;
use App\Rules\EmailNotUsedByOtherAccountType;
use App\Rules\UniqueCustomerEmail;
use Illuminate\Contracts\Pagination\LengthAwarePaginator;
use Illuminate\Database\UniqueConstraintViolationException;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Arr;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Validator;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;

/**
 * Customer administration and lifecycle management (CRUD, wholesale verification, approval, rejection, and suspension).
 * Immediate suspension invalidates all active sessions; rejection keeps tokens active to review rejection reasons.
 */
class CustomerManagementService
{
    private const MAX_ACTIVE_DOCUMENTS = 5;

    private const MAX_TOTAL_DOCUMENTS = 10;

    /**
     * Paginate customers with search, type, and status filtering.
     */
    public function paginate(array $filters): LengthAwarePaginator
    {
        return Customer::query()
            ->with('customerGroup')
            ->when(($filters['trashed'] ?? null) === 'only', fn ($q) => $q->onlyTrashed())
            ->when($filters['business_only'] ?? false, fn ($q) => $q->whereIn('type', ['wholesale', 'distributor']))
            ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
            ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
            ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
            ->when($filters['search'] ?? null, fn ($q, $v) => $q->whereLike('search_text', SearchTerm::pattern($v), caseSensitive: false))
            ->orderByDesc('id')
            ->paginate($filters['per_page'] ?? 15)->withQueryString();
    }

    /**
     * Retrieve customer with complete profile relations.
     */
    public function find(int $id): Customer
    {
        return Customer::query()
            ->with(['customerGroup', 'documents', 'addresses.city', 'approver'])
            ->findOrFail($id);
    }

    /**
     * Merge the execution channel marker (AI vs REST) into audit metadata.
     * REST calls pass an empty $via, so their recorded metadata stays
     * byte-identical to before; AI calls carry channel/conversation/action.
     */
    private function viaMeta(array $via, array $meta = []): array
    {
        return $via === [] ? $meta : [...$meta, 'via' => $via];
    }

    /**
     * Acquire a transactional advisory lock and re-validate customer email uniqueness under concurrency.
     *
     * @param  string|null  $email  Email address to claim.
     * @param  int|null  $ignoreId  Customer ID to exclude from unique checks during updates.
     */
    private function claimEmail(?string $email, ?int $ignoreId = null): void
    {
        if ($email === null || trim($email) === '') {
            return;
        }
        $email = mb_strtolower(trim($email));
        DB::select('SELECT pg_advisory_xact_lock(hashtextextended(?, 0))', [$email]);
        Validator::make(['email' => $email], [
            'email' => [new UniqueCustomerEmail($ignoreId), new EmailNotUsedByOtherAccountType('customers')],
        ])->validate();
    }

    /**
     * Map database unique index collisions to user-friendly validation exceptions.
     */
    private function translateUniqueViolation(UniqueConstraintViolationException $e): \Throwable
    {
        $message = $e->getMessage();

        return match (true) {
            str_contains($message, 'phone') => ValidationException::withMessages(['phone' => 'رقم الموبايل مسجل بالفعل.']),
            str_contains($message, 'email') => ValidationException::withMessages(['email' => 'البريد الإلكتروني مستخدم بالفعل.']),
            default => $e,
        };
    }

    /**
     * Assert that the specified customer group exists and is currently active.
     */
    private function assertActiveGroup(?int $groupId): void
    {
        if ($groupId !== null && ! CustomerGroup::query()->whereKey($groupId)->where('is_active', true)->exists()) {
            throw new BusinessException('مجموعة العملاء غير موجودة أو معطلة.', ['customer_group_id' => ['اختر مجموعة مفعّلة.']]);
        }
    }

    /**
     * Create customer record from admin console.
     * Enforces Approved status for retail and Pending for wholesale accounts.
     *
     * @throws BusinessException If attempting to directly create an approved wholesale account
     */
    public function create(array $data, ?int $actorId = null, array $via = []): Customer
    {
        $data['type'] ??= CustomerType::Retail->value;
        $data['credit_limit'] ??= 0;
        // Default status by type unless explicitly provided: retail is approved, wholesale requires review.
        $data['status'] ??= ($data['type'] ?? CustomerType::Retail->value) === CustomerType::Retail->value
            ? CustomerStatus::Approved
            : CustomerStatus::Pending;

        if ($data['status'] === CustomerStatus::Approved || $data['status'] === CustomerStatus::Approved->value) {
            if ($data['type'] !== CustomerType::Retail->value) {
                throw new BusinessException('أنشئ حساب الجملة قيد المراجعة ثم استخدم مسار الاعتماد.');
            }
        }

        try {
            return DB::transaction(function () use ($data, $actorId, $via): Customer {
                $this->claimEmail($data['email'] ?? null);
                $this->assertActiveGroup(isset($data['customer_group_id']) ? (int) $data['customer_group_id'] : null);
                if (in_array($data['status'], [CustomerStatus::Approved, CustomerStatus::Approved->value], true)) {
                    $data['approved_at'] = now();
                    $data['approved_by'] = $actorId;
                }
                $customer = (new Customer)->forceFill($data);
                $customer->save();
                CustomerAuditLog::record($customer, 'created', $actorId, $this->viaMeta($via));

                return $customer->load('customerGroup');
            });
        } catch (UniqueConstraintViolationException $e) {
            throw $this->translateUniqueViolation($e);
        }
    }

    /**
     * Update customer profile, credentials, and business identity.
     * Invalidates active sessions and reset tokens if credentials change.
     */
    public function update(Customer $customer, array $data, ?int $actorId = null, array $via = []): Customer
    {
        try {
            return DB::transaction(function () use ($customer, $data, $actorId, $via): Customer {
                $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
                if (isset($data['email']) && $data['email'] !== $customer->email) {
                    $this->claimEmail($data['email'], $customer->id);
                }
                if (array_key_exists('customer_group_id', $data) && $data['customer_group_id'] !== null
                    && (int) $data['customer_group_id'] !== (int) $customer->customer_group_id) {
                    $this->assertActiveGroup((int) $data['customer_group_id']);
                }
                if (isset($data['type']) && $data['type'] !== $customer->type->value) {
                    throw new BusinessException('تغيير نوع الحساب المعتمد يتطلب استخدام مسار الاعتماد.');
                }
                if ($customer->status === CustomerStatus::Approved && $customer->type !== CustomerType::Retail) {
                    foreach (['company_name', 'tax_number', 'commercial_register'] as $field) {
                        if (array_key_exists($field, $data) && blank($data[$field])) {
                            throw new BusinessException('لا يمكن مسح بيانات الجملة لحساب معتمد.', [$field => ['هذا الحقل مطلوب.']]);
                        }
                    }
                }
                $businessIdentityChanged = collect(['company_name', 'tax_number', 'commercial_register'])
                    ->contains(fn ($field) => array_key_exists($field, $data) && $data[$field] !== $customer->{$field});
                $credentialsChanged = array_key_exists('password', $data)
                    || (isset($data['email']) && $data['email'] !== $customer->email)
                    || (isset($data['phone']) && $data['phone'] !== $customer->phone)
                    || (array_key_exists('email', $data) && $data['email'] === null && $customer->email !== null);
                if (isset($data['phone']) && $data['phone'] !== $customer->phone) {
                    $customer->forceFill(['phone_verified_at' => null]);
                }

                // Track previous and new values for financial attributes in the audit payload.
                $financial = [];
                if (array_key_exists('credit_limit', $data) && (float) $data['credit_limit'] !== (float) $customer->credit_limit) {
                    $financial['credit_limit'] = ['before' => (string) $customer->credit_limit, 'after' => (string) $data['credit_limit']];
                }
                if (array_key_exists('customer_group_id', $data)) {
                    $old = $customer->customer_group_id === null ? null : (int) $customer->customer_group_id;
                    $new = $data['customer_group_id'] === null ? null : (int) $data['customer_group_id'];
                    if ($old !== $new) {
                        $financial['customer_group_id'] = ['before' => $old, 'after' => $new];
                    }
                }
                $customer->fill(Arr::except($data, ['credit_limit']));
                if (array_key_exists('credit_limit', $data)) {
                    $customer->forceFill(['credit_limit' => $data['credit_limit']]);
                }
                if ($credentialsChanged) {
                    $customer->forceFill(['remember_token' => Str::random(60)]);
                    $customer->tokens()->delete();
                    DB::table('password_reset_tokens')->where('email', $customer->getEmailForPasswordReset())->delete();
                }
                $customer->save();
                CustomerAuditLog::record($customer, $credentialsChanged ? 'credentials_changed' : 'updated', $actorId, $this->viaMeta($via, ['fields' => array_keys($data)] + ($financial !== [] ? ['changes' => $financial] : [])));
                if ($businessIdentityChanged) {
                    CustomerAuditLog::record($customer, 'business_identity_changed', $actorId, $this->viaMeta($via, ['fields' => array_keys(array_intersect_key($data, array_flip(['company_name', 'tax_number', 'commercial_register'])))]));
                }

                return $customer->load('customerGroup');
            });
        } catch (UniqueConstraintViolationException $e) {
            throw $this->translateUniqueViolation($e);
        }
    }

    /**
     * Soft-delete customer and revoke all active tokens/sessions.
     */
    public function delete(Customer $customer, ?int $actorId = null): void
    {
        DB::transaction(function () use ($customer, $actorId): void {
            $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
            $customer->tokens()->delete();
            DB::table('password_reset_tokens')->where('email', $customer->getEmailForPasswordReset())->delete();
            CustomerAuditLog::record($customer, 'deleted', $actorId);
            $customer->delete();
        });
    }

    /**
     * Approve customer application (wholesale/distributor).
     * Validates verified supporting documents and assigns group, credit limit, and approver timestamp.
     *
     * @throws BusinessException If documents unverified or required legal info missing
     */
    public function approve(Customer $customer, array $data, int $adminId, array $via = []): Customer
    {
        return DB::transaction(function () use ($customer, $data, $adminId, $via): Customer {
            $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
            if ($customer->status === CustomerStatus::Suspended) {
                throw new BusinessException('الحساب موقوف؛ استخدم إعادة التفعيل بدل الاعتماد.');
            }
            $this->assertActiveGroup(array_key_exists('customer_group_id', $data) && $data['customer_group_id'] !== null ? (int) $data['customer_group_id'] : null);
            if ($customer->status === CustomerStatus::Approved && ($data['type'] ?? $customer->type->value) === $customer->type->value) {
                throw new BusinessException('هذا الحساب معتمد بالفعل.');
            }
            $legal = [];

            // Exclude rejected documents from blocking approval; only pending documents require resolution.
            if ($customer->documents()->where('status', CustomerDocumentStatus::Pending->value)->exists()) {
                throw new BusinessException('راجع المستندات المعلقة (اعتمد السليم وارفض غير السليم) قبل اعتماد الحساب.');
            }
            if (($data['type'] ?? $customer->type->value) !== CustomerType::Retail->value) {
                if (! $customer->documents()->where('status', 'verified')->exists()) {
                    throw new BusinessException('يلزم مستند موثّق واحد على الأقل لاعتماد حساب الجملة أو الموزع.');
                }
                foreach (['company_name', 'tax_number', 'commercial_register'] as $field) {
                    $legal[$field] = $data[$field] ?? $customer->{$field};
                    if (blank($legal[$field])) {
