  const wasBusy = useRef(busy);
  useEffect(() => { if (wasBusy.current && !busy) input.current?.focus(); wasBusy.current = busy; }, [busy]);

  const addFiles = (incoming: FileList | File[]) => {
    const valid = Array.from(incoming).filter(f => /^image\/(jpeg|png|webp)$/.test(f.type)
      || (enablePricing && /\.(csv|txt)$/i.test(f.name)));
    if (!valid.length) return;
    setFiles(prev => [...prev, ...valid].slice(0, 4));
  };

  const submit = async () => {
    if (busy || (!text.trim() && files.length === 0)) return;
    const draft = text.trim() || (files.some(f => /\.(csv|txt)$/i.test(f.name)) ? 'عاين ملف استيراد أسعار المرفق' : 'حلّل الصور المرفقة');
    const refs = mentions;
    const attached = files;
    setText(''); setMentions([]); setFiles([]); setOptions([]);
    if (!await onSend(draft, undefined, refs, attached.length ? attached : undefined)) {
      setText(draft); setMentions(refs); setFiles(attached);
    }
    input.current?.focus();
  };

  const pickMention = (o: Option) => {
    setText(t => t.replace(/([@#!$&])([^\s@#!$&]*)$/, () => `${o.label} `));
    setMentions(items => [...items.filter(m => m.id !== o.id || m.entity !== o.entity), { entity: o.entity, id: o.id, label: o.label }]);
    input.current?.focus();
  };
  const pickCommand = (c: string) => {
    const expanded = COMMAND_PROMPTS[c] ?? `${c} `;
    setText(expanded);
    setDismissed(`//${expanded}`);
    input.current?.focus();
  };
  const insertMarker = (m: string) => {
    setDismissed('');
    setText(t => (t === '' || /\s$/.test(t) ? `${t}${m}` : `${t} ${m}`));
    input.current?.focus();
  };

  const count = slash ? commands.length : options.length;
  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey && marker === '@' && enableInventory && /^[0-9٠-٩۰-۹]{6,}$/.test(query ?? '')) {
      e.preventDefault();
      void assistantApi.mentions(query ?? '').then(result => {
        const variants: Option[] = (result.variants ?? []).map(o => ({ entity: 'variant', id: o.id, label: o.label, meta: o.meta }));
        if (variants.length === 1) pickMention(variants[0]);
        else { setOptions(variants); if (!variants.length) setSearchError('مفيش صنف بالباركود ده.'); }
      }).catch(() => setSearchError('تعذر البحث بالباركود؛ جرّب تاني.'));
      return;
    }
    if (popOpen && count > 0) {
      if (e.key === 'ArrowDown') { e.preventDefault(); setActive(a => (a + 1) % count); return; }
      if (e.key === 'ArrowUp') { e.preventDefault(); setActive(a => (a - 1 + count) % count); return; }
      if ((e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) || e.key === 'Tab') {
        e.preventDefault();
        if (slash) pickCommand(commands[active]); else pickMention(options[active]);
        return;
      }
    }
    if (e.key === 'Escape') { if (popOpen) { e.preventDefault(); setDismissed(popKey); setOptions([]); } return; }
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); void submit(); }
  };

  const meta = marker ? markerMeta[marker] : undefined;
  const near = text.length > MAX * 0.9;

  return (
    <form
      className="as-composer"
      data-disabled={busy}
      data-drag={dragOver}
      onDragOver={e => { if (canAttach) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={e => {
        if (!canAttach) return;
        e.preventDefault();
        setDragOver(false);
        if (e.dataTransfer.files?.length) addFiles(e.dataTransfer.files);
      }}
      onSubmit={e => { e.preventDefault(); void submit(); }}
    >
      {popOpen && (
        <div className="as-pop" role="dialog" aria-label={slash ? 'الأوامر السريعة' : 'اقتراحات المنشن'}>
          <div className="as-pop-head">
            <Icon name={slash ? 'command' : entityIcon[meta!.entity]} size={14} />
            <strong>{slash ? 'الأوامر السريعة' : meta!.title}</strong>
            {!slash && query ? <span>· «{query}»</span> : null}
            <span className="as-kbdrow as-only-desktop"><span className="as-kbd">↑</span><span className="as-kbd">↓</span> تنقّل <span className="as-kbd">↵</span> اختيار <span className="as-kbd">Esc</span></span>
          </div>
          {slash ? (
            commands.length ? (
              <ul className="as-pop-list" role="listbox" id={listId}>
                {commands.map((c, i) => (
                  <li key={c} role="option" aria-selected={i === active}>
                    <button type="button" className="as-opt" aria-selected={i === active} disabled={busy} onMouseEnter={() => setActive(i)} onClick={() => pickCommand(c)}>
                      <span className="as-opt-ic"><Icon name="bolt" size={15} /></span>
                      <span className="as-opt-txt"><span className="as-opt-label"><Highlight text={c} q={text.slice(1).trim()} /></span></span>
                      <span className="as-kbd as-opt-enter">↵</span>
                    </button>
                  </li>
                ))}
              </ul>
            ) : (
              <div className="as-pop-empty"><Icon name="command" size={22} /><strong>مفيش أمر بالاسم ده</strong><span>اكتب طلبك عادي والمساعد هيفهمه.</span></div>
            )
          ) : loading ? (
            <div className="as-pop-loading" aria-label="جارٍ التحميل"><i /><i /><i /></div>
          ) : searchError ? (
            <div className="as-pop-empty" role="alert"><Icon name="alert" size={22} /><strong>{searchError}</strong><span>تأكد من الاتصال وحاول تاني.</span></div>
          ) : options.length ? (
            <ul className="as-pop-list" role="listbox" id={listId}>
              {options.map((o, i) => (
                <li key={`${o.entity}-${o.id}`} role="option" aria-selected={i === active}>
                  <button type="button" className="as-opt" aria-selected={i === active} disabled={busy} onMouseEnter={() => setActive(i)} onClick={() => pickMention(o)}>
                    <span className="as-opt-ic"><Icon name={entityIcon[o.entity]} size={15} /></span>
                    <span className="as-opt-txt">
                      <span className="as-opt-label"><Highlight text={o.label} q={query ?? ''} /></span>
                      {o.meta && <span className="as-opt-meta">{o.meta}</span>}
                    </span>
                    <span className="as-kbd as-opt-enter">↵</span>
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <div className="as-pop-empty">
              <Icon name="search" size={22} />
              <strong>مفيش {entityLabel[meta!.entity]} مطابق{query ? ` لـ «${query}»` : ''}</strong>
              <span>جرّب جزء من الاسم أو الكود.</span>
            </div>
          )}
        </div>
      )}

      <div className="as-composer-box">
        {mentions.length > 0 && (
          <div className="as-tags" aria-label="العناصر المشار إليها">
            {mentions.map(m => (
              <span className="as-tag" data-entity={m.entity} key={`${m.entity}-${m.id}`}>
                <Icon name={entityIcon[m.entity] ?? 'layers'} size={13} />
                {m.label}
                <button type="button" disabled={busy} onClick={() => setMentions(items => items.filter(o => o !== m))} aria-label={`إزالة منشن ${m.label}`}><Icon name="x" size={12} /></button>
              </span>
            ))}
          </div>
        )}
        {files.length > 0 && (
          <div className="as-tags" aria-label="الصور المرفقة" style={{ gap: '.5rem', padding: '.4rem .6rem' }}>
            {files.map((f, idx) => (
              <span key={`${f.name}-${idx}`} className="as-tag" style={{ display: 'inline-flex', alignItems: 'center', gap: '.4rem' }}>
                <Icon name="image" size={13} />
                <span style={{ maxWidth: 140, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{f.name}</span>
                <button type="button" disabled={busy} onClick={() => setFiles(list => list.filter((_, i) => i !== idx))} aria-label={`إزالة ${f.name}`}><Icon name="x" size={12} /></button>
              </span>
            ))}
          </div>
        )}
        <textarea
          ref={input}
          aria-label="رسالة المساعد"
          aria-autocomplete="list"
          aria-controls={popOpen ? listId : undefined}
          aria-expanded={popOpen}
          value={text}
          maxLength={MAX}
          disabled={busy}
          rows={1}
          onChange={e => { setText(e.target.value); if (dismissed && !e.target.value) setDismissed(''); }}
          placeholder={busy ? 'المساعد بيجهّز الرد…' : `اكتب طلبك… استخدم @ للموظفين، # للفروع، ! للأدوار،${canDollar ? ' $ للمنتجات والعملاء،' : ''}${enableCatalog ? ' & للأقسام،' : ''} / للأوامر`}
          onKeyDown={onKeyDown}
        />
        <div className="as-composer-foot">
          <button type="button" className="as-trigger as-trigger--main" disabled={busy} onClick={() => insertMarker('@')} title="منشن موظف" aria-label="منشن موظف">@</button>
          <button type="button" className="as-trigger" disabled={busy} onClick={() => insertMarker('#')} title="منشن فرع" aria-label="منشن فرع">#</button>
          <button type="button" className="as-trigger" disabled={busy} onClick={() => insertMarker('!')} title="منشن دور" aria-label="منشن دور">!</button>
          {canDollar && <button type="button" className="as-trigger" disabled={busy} onClick={() => insertMarker('$')} title="منشن منتج أو عميل" aria-label="منشن منتج أو عميل">$</button>}
          {enableCatalog && <button type="button" className="as-trigger" disabled={busy} onClick={() => insertMarker('&')} title="منشن قسم" aria-label="منشن قسم">&amp;</button>}
          {canAttach && (
            <>
              <input
                ref={fileInputRef}
                type="file"
                accept={`image/jpeg,image/png,image/webp${enablePricing ? ',.csv,.txt' : ''}`}
                multiple
                 hidden
                onChange={e => { if (e.target.files?.length) addFiles(e.target.files); e.target.value = ''; }}
              />
              <button type="button" className="as-trigger" disabled={busy || files.length >= 4} onClick={() => fileInputRef.current?.click()} title="إرفاق ملفات (حتى 4)" aria-label="إرفاق ملفات">
                <Icon name="paperclip" size={14} />
              </button>
            </>
          )}
          {quickCommands.length > 0 && <button type="button" className="as-trigger" disabled={busy} onClick={() => { setDismissed(''); setText('/'); input.current?.focus(); }} title="الأوامر السريعة" aria-label="الأوامر السريعة">/</button>}
          <span className="as-counter as-num" data-near={near}>{text.length > 0 ? `${text.length.toLocaleString('ar-EG')} / ${MAX.toLocaleString('ar-EG')}` : ''}</span>
          <button className="as-send" type="submit" disabled={busy || (!text.trim() && files.length === 0)} data-busy={busy} aria-label={busy ? 'جارٍ الإرسال' : 'إرسال'}>
            {busy ? <span className="as-spin" /> : <Icon name="send" size={18} />}
          </button>
        </div>
      </div>
      <p className="as-composer-note">
        {hint ?? <><span className="as-kbd">↵</span> إرسال · <span className="as-kbd">Shift</span>+<span className="as-kbd">↵</span> سطر جديد · مفيش أي تعديل بيتنفذ قبل تأكيدك</>}
      </p>
    </form>
  );
}<?php

declare(strict_types=1);

namespace App\Services\Ai;

use Illuminate\Http\Client\ConnectionException;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Http;
use InvalidArgumentException;
use LogicException;

class GeminiClient
{
    /**
     * M9: Laravel throws ConnectionException for both connect failures and
     * read timeouts. Retrying a read timeout can double-bill tokens — the
     * provider may have processed the first attempt. Retry connect/DNS
     * failures only; a timeout fails fast instead.
     */
    private static function isConnectFailure(ConnectionException $e): bool
    {
        $message = strtolower($e->getMessage());

        return ! str_contains($message, 'timed out')
            && ! str_contains($message, 'timeout')
            && ! str_contains($message, 'cURL error 28');
    }

    /**
     * @param  list<UploadedFile>  $images
     * @return array{text: string, model: string, usage: array{input_tokens: int, output_tokens: int, total_tokens: int}}
     */
    public function generate(string $prompt, array $images = [], ?string $system = null, ?string $model = null): array
    {
        $key = (string) config('services.gemini.api_key');
        $model ??= config('services.gemini.model');
        if ($key === '' || ! is_string($model) || ! preg_match('/^[a-zA-Z0-9._-]+$/', $model) || str_contains($model, '..')) {
            throw new LogicException('إعدادات Gemini غير مكتملة.');
        }
        if (trim($prompt) === '') {
            throw new InvalidArgumentException('نص الطلب مطلوب.');
        }
        if (count($images) > config('services.gemini.max_images', 5)) {
            throw new InvalidArgumentException('الحد الأقصى 5 صور في الطلب.');
        }

        $parts = [['text' => $prompt]];
        foreach ($images as $image) {
            if (! $image instanceof UploadedFile || ! $image->isValid()
                || ! in_array($image->getMimeType(), ['image/jpeg', 'image/png', 'image/webp'], true)
                || $image->getSize() > config('services.gemini.max_image_bytes', 4 * 1024 * 1024)) {
                throw new InvalidArgumentException('الصورة يجب أن تكون JPG أو PNG أو WebP وبحد أقصى 4MB.');
            }
            $parts[] = ['inlineData' => ['mimeType' => $image->getMimeType(), 'data' => base64_encode($image->getContent())]];
        }

        $payload = [
            'contents' => [['role' => 'user', 'parts' => $parts]],
            'generationConfig' => [
                'temperature' => 0.4,
                'maxOutputTokens' => (int) config('services.gemini.max_output_tokens', 2048),
            ],
        ];
        if ($system !== null && trim($system) !== '') {
            $payload['systemInstruction'] = ['parts' => [['text' => $system]]];
        }

        for ($attempt = 0; $attempt < 2; $attempt++) {
            try {
                $response = Http::acceptJson()->asJson()->withHeaders(['x-goog-api-key' => $key])
                    ->withOptions(['verify' => config('services.integrations.ca_bundle') ?: true])
                    ->connectTimeout(5)->timeout(max(1, (int) config('services.gemini.timeout_seconds', 20)))
                    ->post('https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent', $payload);
            } catch (ConnectionException $e) {
                // M9: retry connect failures only — a read timeout may have
                // executed server-side, so retrying would double-bill tokens.
                if ($attempt === 0 && self::isConnectFailure($e)) {
                    logger()->warning('gemini.request_retry', ['method' => 'generate', 'reason' => 'connect_failure']);

                    continue;
                }
                throw new GeminiException('تعذّر الاتصال بخدمة Gemini.');
            }
            if (($response->status() === 429 || $response->serverError()) && $attempt === 0) {
                logger()->warning('gemini.request_retry', ['method' => 'generate', 'reason' => 'http_'.$response->status()]);
                // L7: نحترم Retry-After (من ثانية لـ 5 ثواني) بدل 250ms.
                usleep(min(5, max(1, (int) $response->header('Retry-After'))) * 1_000_000);

                continue;
            }
            if (! $response->successful()) {
                throw new GeminiException('تعذّر تنفيذ طلب Gemini.', $response->status());
            }

            $candidate = $response->json('candidates.0', []);
            if (! is_array($candidate)) {
                $candidate = [];
            }
            if (($candidate['finishReason'] ?? null) !== 'STOP') {
                throw new GeminiException('لم ترجع خدمة Gemini إجابة مكتملة.');
            }
            $text = collect($candidate['content']['parts'] ?? [])
                ->reject(fn ($part) => ! empty($part['thought']))
                ->pluck('text')->filter(fn ($part) => is_string($part))->implode('');
            if (trim($text) === '') {
                throw new GeminiException('لم ترجع خدمة Gemini إجابة نصية.');
            }

            $usage = $response->json('usageMetadata', []);
            $input = (int) ($usage['promptTokenCount'] ?? 0);
            $output = (int) ($usage['candidatesTokenCount'] ?? 0);

            return ['text' => trim($text), 'model' => $model, 'usage' => [
                'input_tokens' => $input, 'output_tokens' => $output,
                'total_tokens' => (int) ($usage['totalTokenCount'] ?? $input + $output),
            ]];
        }

        throw new GeminiException('تعذّر تنفيذ طلب Gemini.');
    }

    /**
     * Structured JSON output for document/shelf-photo parsing (phase 4 stocktake
     * sheets). Prompt must instruct the model to ignore injected instructions in
     * the image text. Never use for direct approvals — fills counts only.
     *
     * @param  array<string,mixed>  $schema  JSON Schema for responseSchema
     * @param  list<UploadedFile>  $images
     * @return array{data:array<string,mixed>|list<mixed>, model:string, usage:array{input_tokens:int,output_tokens:int,total_tokens:int}}
     */
    public function generateStructured(string $prompt, array $schema, array $images = [], ?string $model = null): array
    {
        $key = (string) config('services.gemini.api_key');
        $model ??= config('services.gemini.model');
        if ($key === '' || ! is_string($model) || ! preg_match('/^[a-zA-Z0-9._-]+$/', $model) || str_contains($model, '..')) {
            throw new LogicException('إعدادات Gemini غير مكتملة.');
        }
        if (trim($prompt) === '') {
            throw new InvalidArgumentException('نص الطلب مطلوب.');
        }
        if ($schema === []) {
            throw new InvalidArgumentException('مخطط الاستجابة مطلوب.');
        }
        if (count($images) > config('services.gemini.max_images', 5)) {
            throw new InvalidArgumentException('الحد الأقصى 5 صور في الطلب.');
        }

        $parts = [['text' => $prompt]];
        foreach ($images as $image) {
            if (! $image instanceof UploadedFile || ! $image->isValid()
                || ! in_array($image->getMimeType(), ['image/jpeg', 'image/png', 'image/webp'], true)
                || $image->getSize() > config('services.gemini.max_image_bytes', 4 * 1024 * 1024)) {
                throw new InvalidArgumentException('الصورة يجب أن تكون JPG أو PNG أو WebP وبحد أقصى 4MB.');
            }
            $parts[] = ['inlineData' => ['mimeType' => $image->getMimeType(), 'data' => base64_encode($image->getContent())]];
        }

        $payload = [
            'contents' => [['role' => 'user', 'parts' => $parts]],
            'generationConfig' => [
                'temperature' => 0.2,
                'maxOutputTokens' => (int) config('services.gemini.max_output_tokens', 2048),
                'responseMimeType' => 'application/json',
                'responseSchema' => $schema,
            ],
        ];

        for ($attempt = 0; $attempt < 2; $attempt++) {
            try {
                $response = Http::acceptJson()->asJson()->withHeaders(['x-goog-api-key' => $key])
                    ->withOptions(['verify' => config('services.integrations.ca_bundle') ?: true])
                    ->connectTimeout(5)->timeout(max(1, (int) config('services.gemini.timeout_seconds', 20)))
                    ->post('https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent', $payload);
            } catch (ConnectionException $e) {
                // M9: retry connect failures only (see generate()).
                if ($attempt === 0 && self::isConnectFailure($e)) {
                    logger()->warning('gemini.request_retry', ['method' => 'generateStructured', 'reason' => 'connect_failure']);

                    continue;
                }
                throw new GeminiException('تعذّر الاتصال بخدمة Gemini.');
            }
            if (($response->status() === 429 || $response->serverError()) && $attempt === 0) {
                logger()->warning('gemini.request_retry', ['method' => 'generateStructured', 'reason' => 'http_'.$response->status()]);
                usleep(min(5, max(1, (int) $response->header('Retry-After'))) * 1_000_000);

                continue;
            }
            if (! $response->successful()) {
                throw new GeminiException('تعذّر تنفيذ طلب Gemini.', $response->status());
            }

            $candidate = $response->json('candidates.0', []);
            if (! is_array($candidate)) {
                $candidate = [];
            }
            if (($candidate['finishReason'] ?? null) !== 'STOP') {
                throw new GeminiException('لم ترجع خدمة Gemini إجابة مكتملة.');
            }
            $text = collect($candidate['content']['parts'] ?? [])
                ->reject(fn ($part) => ! empty($part['thought']))
                ->pluck('text')->filter(fn ($part) => is_string($part))->implode('');
            if (trim($text) === '') {
                throw new GeminiException('لم ترجع خدمة Gemini إجابة نصية.');
            }
            try {
                $data = json_decode(trim($text), true, flags: JSON_THROW_ON_ERROR);
            } catch (\JsonException) {
                throw new GeminiException('لم ترجع خدمة Gemini بنية JSON صالحة.');
            }

            $usage = $response->json('usageMetadata', []);
            $input = (int) ($usage['promptTokenCount'] ?? 0);
            $output = (int) ($usage['candidatesTokenCount'] ?? 0);

            return ['data' => $data, 'model' => $model, 'usage' => [
                'input_tokens' => $input, 'output_tokens' => $output,
                'total_tokens' => (int) ($usage['totalTokenCount'] ?? $input + $output),
            ]];
        }

        throw new GeminiException('تعذّر تنفيذ طلب Gemini.');
    }

    /**
     * @param  list<array{role:string, parts:list<array<string,mixed>>}>  $contents
     * @param  list<array<string,mixed>>  $functionDeclarations
     * @return array{parts:list<array<string,mixed>>, text:string, calls:list<array{name:string,args:array<string,mixed>}>, usage:array{input_tokens:int,output_tokens:int,total_tokens:int}, finish:string, model:string}
     */
    public function converse(array $contents, array $functionDeclarations = [], ?string $system = null, ?string $model = null): array
    {
        $key = (string) config('services.gemini.api_key');
        $model ??= config('services.gemini.model');
        if ($key === '' || ! is_string($model) || ! preg_match('/^[a-zA-Z0-9._-]+$/', $model) || str_contains($model, '..')) {
            throw new LogicException('إعدادات Gemini غير مكتملة.');
        }
        if ($contents === []) {
            throw new InvalidArgumentException('محتوى المحادثة مطلوب.');
        }
        // Associative JSON decoding loses the distinction between {} and [].
        // Gemini requires these fields to remain maps, including after database replay.
        foreach ($contents as $turnIndex => $turn) {
            foreach ($turn['parts'] as $partIndex => $part) {
                foreach (['functionCall' => 'args', 'functionResponse' => 'response'] as $node => $field) {
                    if (isset($part[$node][$field]) && is_array($part[$node][$field])) {
                        $contents[$turnIndex]['parts'][$partIndex][$node][$field] = (object) $part[$node][$field];
                    }
                }
            }
        }
        // M-9: حد الإخراج من الإعدادات (كما في generate) لا مثبتًا — نماذج
        // التفكير (Gemini 2.5) تحسب توكنز التفكير ضمنه فتظهر MAX_TOKENS زورًا.
        $maxOutputTokens = max(1024, (int) config('services.gemini.max_output_tokens', 2048));
        $generationConfig = ['temperature' => 0.2, 'maxOutputTokens' => $maxOutputTokens];
        if (is_string($model) && preg_match('/^gemini-2\.5/i', $model) === 1) {
            $generationConfig['thinkingConfig'] = ['thinkingBudget' => min(1024, (int) ($maxOutputTokens / 4))];
        }
        $payload = [
            'contents' => $contents,
            'generationConfig' => $generationConfig,
        ];
        if ($functionDeclarations) {
            $payload['tools'] = [['functionDeclarations' => $functionDeclarations]];
            $payload['toolConfig'] = ['functionCallingConfig' => ['mode' => 'AUTO']];
        }
        if ($system !== null && trim($system) !== '') {
            $payload['systemInstruction'] = ['parts' => [['text' => $system]]];
        }
        for ($attempt = 0; $attempt < 2; $attempt++) {
            try {
                $response = Http::acceptJson()->asJson()->withHeaders(['x-goog-api-key' => $key])
                    ->withOptions(['verify' => config('services.integrations.ca_bundle') ?: true])
                    ->connectTimeout(5)->timeout(max(1, (int) config('services.gemini.timeout_seconds', 20)))
                    ->post('https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent', $payload);
            } catch (ConnectionException $e) {
                // M9: retry connect failures only (see generate()).
                if ($attempt === 0 && self::isConnectFailure($e)) {
                    logger()->warning('gemini.request_retry', ['method' => 'converse', 'reason' => 'connect_failure']);

                    continue;
                }
                throw new GeminiException('تعذّر الاتصال بخدمة Gemini.');
            }
            if (($response->status() === 429 || $response->serverError()) && $attempt === 0) {
                logger()->warning('gemini.request_retry', ['method' => 'converse', 'reason' => 'http_'.$response->status()]);
                // L7: نحترم Retry-After (من ثانية لـ 5 ثواني) بدل 250ms.
                usleep(min(5, max(1, (int) $response->header('Retry-After'))) * 1_000_000);

                continue;
            }
            if (! $response->successful()) {
                throw new GeminiException('تعذّر تنفيذ طلب Gemini.', $response->status());
            }
            $candidate = $response->json('candidates.0', []);
            if (! is_array($candidate)) {
                $candidate = []; // L7: يرمي GeminiException تحت (finishReason فاضي) بدل TypeError
            }
            $finish = (string) ($candidate['finishReason'] ?? '');
            $usage = $response->json('usageMetadata', []);
            // M7: حضّر قياس الاستخدام قبل أي باب خروج — الرد غير المكتمل
            // (MAX_TOKENS/SAFETY...) كمان بيكلف توكنز لازم تدخل الميزانية.
            $measured = [
                'input_tokens' => (int) ($usage['promptTokenCount'] ?? 0),
                'output_tokens' => (int) ($usage['candidatesTokenCount'] ?? 0),
                'total_tokens' => (int) ($usage['totalTokenCount'] ?? 0),
            ];
            if ($finish !== 'STOP') {
                throw GeminiException::withUsage('لم ترجع خدمة Gemini إجابة مكتملة.', $measured, $response->status());
            }
            $parts = $candidate['content']['parts'] ?? [];
            if (! is_array($parts)) {
                $parts = [];
            }
            $text = collect($parts)->reject(fn ($p) => ! empty($p['thought']))->pluck('text')->filter(fn ($p) => is_string($p))->implode('');
            $calls = [];
            foreach ($parts as $part) {
                if (is_array($part) && isset($part['functionCall']['name'])) {
                    $calls[] = ['name' => (string) $part['functionCall']['name'], 'args' => is_array($part['functionCall']['args'] ?? null) ? $part['functionCall']['args'] : []];
                    if (isset($part['functionCall']['id']) && is_string($part['functionCall']['id'])) {
                        $calls[array_key_last($calls)]['id'] = $part['functionCall']['id'];
                    }
                }
            }
            if (! $calls && trim($text) === '') {
                throw GeminiException::withUsage('لم ترجع خدمة Gemini إجابة مكتملة.', $measured);
            }
            $input = $measured['input_tokens'];
            $output = $measured['output_tokens'];
            $output = max($output, $measured['total_tokens'] - $input);

            return ['parts' => $parts, 'text' => trim($text), 'calls' => $calls, 'finish' => $finish, 'model' => $model,
                'usage' => ['input_tokens' => $input, 'output_tokens' => $output, 'total_tokens' => max($measured['total_tokens'], $input + $output)]];
        }
        throw new GeminiException('تعذّر تنفيذ طلب Gemini.');
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Exceptions\BusinessException;
use App\Models\Cart;
use App\Models\CartItem;
use App\Models\Customer;
use App\Models\ProductVariant;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

/**
 * Manages customer and guest shopping carts and real-time line item pricing.
 *
 * Guests are identified by cart_token (transmitted via X-Cart-Session header).
 * Authenticated users link carts by customer_id, merging any guest carts on login.
 * Prices and availability are resolved in real-time without caching stale amounts.
 */
class CartService
{
    public const MAX_REQUEST_QTY = 10000;

    public function __construct(
        protected PricingService $pricing,
        protected StoreCatalogService $catalog,
        protected CouponService $coupons,
    ) {}

    /**
     * Resolves the active cart for an authenticated customer or guest session token.
     *
     * In read-only mode ($create=false), returns an unpersisted Cart instance to prevent database bloat from web crawlers.
     */
    public function resolveCart(?Customer $customer, ?string $guestToken, bool $create = true): Cart
    {
        $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;

        if ($customer !== null) {
            $cart = $create
                ? $this->accountCart($customer)
                : (Cart::query()->where('customer_id', $customer->id)->first() ?? new Cart(['customer_id' => $customer->id]));
            if ($create && $guestToken !== null && $guestToken !== $cart->cart_token) {
                $this->mergeGuestCart($customer, $guestToken);
                $cart = $cart->fresh();
            }

            return $cart->loadMissing('items');
        }

        $cart = $guestToken !== null
            ? Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')->first()
            : null;
        if ($cart !== null) {
            return $cart->loadMissing('items');
        }

        return ($create ? Cart::create([]) : new Cart)->loadMissing('items');
    }

    /**
     * Retrieves or creates the unique persistent cart instance for an authenticated customer.
     */
    private function accountCart(Customer $customer): Cart
    {
        // createOrFirst wraps insertion inside a transaction savepoint to prevent 25P02 transaction aborts.
        return Cart::query()->where('customer_id', $customer->id)->first()
            ?? Cart::query()->createOrFirst(['customer_id' => $customer->id]);
    }

    /**
     * Merges items and coupon from a guest cart into an authenticated customer cart on login.
     */
    public function mergeGuestCart(Customer $customer, ?string $guestToken): void
    {
        $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
        if ($guestToken === null) {
            return;
        }

        // Lock guest cart under transaction to serialize concurrent post-login requests.
        DB::transaction(function () use ($customer, $guestToken): void {
            $guest = Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')
                ->lockForUpdate()->first();
            if ($guest === null) {
                return;
            }
            if (! $guest->items()->exists()) {
                $guest->delete();

                return;
            }

            $account = Cart::query()->lockForUpdate()->findOrFail($this->accountCart($customer)->id);
            // Enforce cart line and item quantity caps during guest cart merger.
            $maxLines = (int) config('store.max_cart_lines', 50);
            $lineCap = $this->lineQtyCap($customer);
            $accountQty = $account->items()->pluck('qty', 'product_variant_id')
                ->map(fn ($qty): float => (float) $qty)->all();
            $accountLines = count($accountQty);

            foreach ($guest->items as $item) {
                $variantId = (int) $item->product_variant_id;
                $existingQty = $accountQty[$variantId] ?? null;
                $isNew = $existingQty === null;

                // Skip new items exceeding max cart lines to avoid blocking user login.
                if ($isNew && $maxLines > 0 && $accountLines >= $maxLines) {
                    continue;
                }

                $qty = (float) $item->qty;
                if ($lineCap > 0) {
                    $allowed = $lineCap - (float) ($existingQty ?? 0);
                    if ($allowed <= 0) {
                        continue;
                    }
                    $qty = min($qty, $allowed);
                }

                // Upsert combines quantities atomically to avoid unique constraint collisions.
                CartItem::query()->upsert(
                    [[
                        'cart_id' => $account->id,
                        'product_variant_id' => $variantId,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]],
                    ['cart_id', 'product_variant_id'],
                    ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
                );

                $accountQty[$variantId] = (float) ($existingQty ?? 0) + $qty;
                if ($isNew) {
                    $accountLines++;
                }
            }
            if ($account->coupon_id === null && $guest->coupon_id !== null) {
                $account->update(['coupon_id' => $guest->coupon_id]);
            }
            $guest->items()->delete();
            $guest->delete();
        });
    }

    /**
     * Adds an item quantity to the cart under a pessimistic row lock.
     */
    public function addItem(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
    {
        $this->assertWholeQuantity($qty);

        return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
            // Lock cart row to serialize concurrent item additions and enforce line limits.
            if (! $cart->exists) {
                $cart = $customer !== null ? $this->accountCart($customer) : Cart::create([]);
            }
            $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);

            $variant = $this->purchasableVariant($variantId);
            $existing = $cart->items()->where('product_variant_id', $variantId)->first();

            // Reject adding new lines when the maximum allowed cart line limit is reached.
            if ($existing === null) {
                $maxLines = (int) config('store.max_cart_lines', 50);
                if ($maxLines > 0 && $cart->items()->count() >= $maxLines) {
                    throw new BusinessException("بلغت سلة التسوق سقف الأصناف ({$maxLines})؛ احذف صنفًا قبل الإضافة.");
                }
            }

            $targetQty = ($existing !== null ? (float) $existing->qty : 0) + $qty;
            $this->assertLineQty($customer, $targetQty);
            $this->assertAvailable($variantId, $targetQty);
            $this->assertPriced($variant, $customer, $targetQty);

            // Upsert increments item quantity atomically to prevent unique key race conditions.
            CartItem::query()->upsert(
                [[
                    'cart_id' => $cart->id,
                    'product_variant_id' => $variantId,
                    'qty' => $qty,
                    'created_at' => now(),
                    'updated_at' => now(),
                ]],
                ['cart_id', 'product_variant_id'],
                ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
            );
            $cart->touch();

            return $cart->fresh('items');
        });
    }

    /**
     * Updates the quantity of a specific item in the cart.
     */
    public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty, ?int $itemId = null): Cart
    {
        $this->assertWholeQuantity($qty, allowZero: true);
        if ($qty <= 0) {
            return $this->removeItem($cart, $variantId);
        }

        return DB::transaction(function () use ($cart, $customer, $variantId, $qty, $itemId): Cart {
            $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
            $variant = $this->purchasableVariant($variantId);
            $this->assertLineQty($customer, $qty);
            $this->assertAvailable($variantId, $qty);
            $this->assertPriced($variant, $customer, $qty);

            $item = $cart->items()->where('product_variant_id', $variantId)
                ->when($itemId !== null, fn ($query) => $query->whereKey($itemId))->firstOrFail();
            $item->update(['qty' => $qty]);
            $cart->touch();

            return $cart->fresh('items');
        });
    }

    /**
     * Removes all quantities of a product variant from the cart.
     */
    public function removeItem(Cart $cart, int $variantId): Cart
    {
        return DB::transaction(function () use ($cart, $variantId): Cart {
            $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
            $cart->items()->where('product_variant_id', $variantId)->delete();
            $cart->touch();

            return $cart->fresh('items');
        });
    }

    /**
     * Removes all items from the cart.
     */
    public function clearItems(Cart $cart): Cart
    {
        return DB::transaction(function () use ($cart): Cart {
            $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
            $cart->items()->delete();
            $cart->touch();

            return $cart->fresh('items');
        });
    }

    /**
     * Calculates real-time prices, discounts, and line totals for all cart items.
     *
     * @return array<int, array{item_id: int, variant: ProductVariant, qty: float, unit_price: float|null, base_price: float|null, line_discount: float, line_total: float}>
     */
    public function pricedLines(Cart $cart, ?Customer $customer): array
    {
        $cart->loadMissing('items.variant.product');
        $purchasableIds = $this->retailVariants()->whereIn('id', $cart->items->pluck('product_variant_id'))->pluck('id')->all();
        $context = $this->pricing->contextFor($customer, $cart->items->pluck('product_variant_id')->all());
        $lines = [];
        foreach ($cart->items as $item) {
            $variant = $item->variant;
            if ($variant === null) {
                continue;
            }
            // Retain inactive variants in response with null prices so shoppers can view and remove them from cart.
            if (! in_array($variant->id, $purchasableIds, true)) {
                $lines[] = [
                    'item_id' => $item->id,
                    'variant' => $variant,
                    'qty' => (float) $item->qty,
                    'unit_price' => null,
                    'base_price' => null,
                    'line_discount' => 0.0,
                    'line_total' => 0.0,
                ];

                continue;
            }
            $qty = (float) $item->qty;
            try {
                $resolved = $this->pricing->resolve($variant, $customer, $qty, ctx: $context);
                $unit = (float) $resolved['unit_price'];
                $base = (float) $resolved['base_price'];
                $lines[] = [
                    'item_id' => $item->id,
                    'variant' => $variant,
                    'qty' => $qty,
                    'unit_price' => $unit,
                    'base_price' => $base,
                    // Customer-specific pricing higher than base price does not produce negative discounts.
                    'line_discount' => max(0.0, BigDecimal::of((string) $base)->minus((string) $unit)->multipliedBy((string) $qty)->toScale(2, RoundingMode::HalfUp)->toFloat()),
                    'line_total' => BigDecimal::of((string) $unit)->multipliedBy((string) $qty)->toScale(2, RoundingMode::HalfUp)->toFloat(),
                ];
            } catch (BusinessException) {
                $lines[] = [
                    'item_id' => $item->id,
                    'variant' => $variant,
                    'qty' => $qty,
                    'unit_price' => null,
                    'base_price' => null,
                    'line_discount' => 0.0,
                    'line_total' => 0.0,
                ];
            }
        }

        return $lines;
    }

    /**
     * Calculates financial summary totals for the cart with real-time pricing and applied coupons.
     *
     * @param  array<int, array<string, mixed>>|null  $lines  Pre-computed priced lines to avoid redundant pricing calls.
     * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
     */
    public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
    {
        $lines ??= $this->pricedLines($cart, $customer);
        $subtotalDecimal = BigDecimal::zero();
        $itemsDecimal = BigDecimal::zero();
        foreach ($lines as $line) {
            if ($line['unit_price'] === null) {
                continue;
            }
            // Each line subtotal is rounded first, then aggregated to preserve exact currency arithmetic.
            $lineSubtotal = BigDecimal::of((string) $line['base_price'])->multipliedBy((string) $line['qty'])->toScale(2, RoundingMode::HalfUp);
            $subtotalDecimal = $subtotalDecimal->plus($lineSubtotal->isLessThan((string) $line['line_total']) ? (string) $line['line_total'] : $lineSubtotal);
            $itemsDecimal = $itemsDecimal->plus((string) $line['line_total']);
        }
        $subtotal = $subtotalDecimal->toFloat();
        $itemsTotal = $itemsDecimal->toFloat();

        // Pricing discount is the difference between rounded totals to prevent fractional cent rounding discrepancies.
        // Higher custom prices raise the base threshold to avoid negative discounts inflating the bill.
        if ($subtotal < $itemsTotal) {
            $subtotal = $itemsTotal;
            $pricingDiscount = 0.0;
        } else {
            $pricingDiscount = $subtotalDecimal->minus($itemsDecimal)->toScale(2, RoundingMode::HalfUp)->toFloat();
        }

        $couponDiscount = 0.0;
        $couponCode = null;
        if ($cart->coupon_id !== null && $itemsTotal > 0) {
            try {
                $coupon = $this->coupons->redeemableById((int) $cart->coupon_id, $itemsTotal, $customer);
                $couponDiscount = $this->coupons->discountFor($coupon, $itemsTotal);
                $couponCode = $coupon->code;
            } catch (BusinessException) {
                // Silently omit invalidated coupons from cart totals; checkout will re-verify strictly.
            }
        }

        return [
            'subtotal' => round($subtotal, 2),
            'pricing_discount' => round($pricingDiscount, 2),
            'items_total' => round($itemsTotal, 2),
            'coupon_discount' => $couponDiscount,
            'total' => $itemsDecimal->minus((string) $couponDiscount)->toScale(2, RoundingMode::HalfUp)->toFloat(),
            'coupon_code' => $couponCode,
        ];
    }

    /**
     * Verifies that all cart line variants remain published and active for purchase.
     *
     * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
     */
    public function assertLinesPurchasable(array $lines): void
    {
        foreach ($lines as $line) {
            $this->assertWholeQuantity((float) $line['qty']);
        }
        $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
        // Verify variants against published storefront channel and category hierarchy in one query batch.
        $variants = $this->retailVariants()->whereIn('id', $ids)->pluck('id')->all();
        foreach ($lines as $line) {
            $variant = $line['variant'];
            if (! in_array($variant->id, $variants, true)) {
                throw new BusinessException("الصنف ({$variant->sku}) لم يعد متاحًا للبيع؛ أزله من السلة وأعد المحاولة.");
            }
        }
    }

    /**
     * Verifies that requested quantities for all lines are available in branch stock.
     *
     * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
     */
    public function assertLinesAvailable(array $lines): void
    {
        $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
        $map = $this->catalog->fulfillableQuantityMap($ids);
        foreach ($lines as $line) {
            if (($map[$line['variant']->id] ?? 0) < $line['qty']) {
                throw new BusinessException("الكمية المتاحة من الصنف ({$line['variant']->sku}) لم تعد كافية لإتمام الطلب.");
            }
        }
    }

    /**
     * Formats cart data, media urls, real-time availability, and totals for storefront presentation.
     *
     * @return array<string, mixed>
     */
    public function present(Cart $cart, ?Customer $customer): array
    {
        // Eager-load display relations up front: product + variant media for the
        // card image (same `images` collection as StoreProductCardResource via
        // Product::catalogImages — there is no `catalog` collection). Constant
        // cost regardless of line count (no N+1).
        $cart->loadMissing([
            'items.variant.product.media',
            'items.variant.product.variants.media',
        ]);
        $lines = $this->pricedLines($cart, $customer);
        $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
        $availability = $this->catalog->fulfillableQuantityMap($ids);

        $items = [];
        foreach ($lines as $line) {
            $variant = $line['variant'];
            $exact = (float) ($availability[$variant->id] ?? 0);
            // Cap exposed balance to purchasable limits to prevent leaking exact warehouse stock levels.
            $maxQty = $line['unit_price'] === null ? 0.0 : $this->maxPurchasableQty($exact, $customer);
            // Same image rule as StoreProductCardResource::toArray: first of
            // Product::catalogImages() (product `images`, then active variants'
            // `images`), thumb conversion when generated, original as fallback.
            $images = $variant->product !== null ? $variant->product->catalogImages() : collect();
            $first = $images->first();
            $items[] = [
                'id' => $line['item_id'],
                'product_variant_id' => $variant->id,
                'product_id' => $variant->product_id,
                'product_name' => $variant->product?->name_ar,
                'product_slug' => $variant->product?->slug,
                'product_name_en' => $variant->product?->name_en,
                'image' => $first && $first->hasGeneratedConversion('thumb') ? $first->getUrl('thumb') : ($first?->getUrl() ?: null),
                'color' => $variant->color_name_en ?? $variant->color_name_ar,
                'size' => $variant->size ?? $variant->capacity,
                'sku' => $variant->sku,
                'qty' => $line['qty'],
                'unit_price' => $line['unit_price'],
                'base_price' => $line['base_price'],
                'line_discount' => $line['line_discount'],
                'line_total' => $line['line_total'],
                'available' => $maxQty,
                'max_qty' => $maxQty,
                'priced' => $line['unit_price'] !== null,
            ];
        }

        return [
            'id' => $cart->id,
            'cart_token' => $cart->cart_token,
            'customer_id' => $cart->customer_id,
            'items' => $items,
            'totals' => $this->totals($cart, $customer, $lines),
        ];
    }

    /**
     * Retrieves an active variant published on the retail channel.
     */
    private function purchasableVariant(int $variantId): ProductVariant
    {
        // Apply storefront catalog publishing rules to ensure discontinued products cannot be added to cart.
        $variant = $this->retailVariants()->with('product')->find($variantId);
        if ($variant === null) {
            throw new BusinessException('الصنف غير متاح للشراء.');
        }

        return $variant;
    }

    /**
     * Scopes query to active variants published on storefront retail channels.
     */
    private function retailVariants(): Builder
    {
        return ProductVariant::query()->where('is_active', true)
            ->whereIn('product_id', $this->catalog->publishedQuery()->withoutEagerLoads()->select('products.id'));
    }

    /**
     * Enforces maximum allowed purchase quantity per cart line for guests and retail users.
     */
    private function assertLineQty(?Customer $customer, float $qty): void
    {
        $cap = $this->lineQtyCap($customer);
        if ($cap > 0 && $qty > $cap) {
            throw new BusinessException($customer === null
                ? "سقف كمية البند الواحد للزوار ({$cap}) — سجّل الدخول للكميات الأكبر."
                : "سقف كمية البند الواحد ({$cap}) — للكميات الأكبر تواصل مع مسار الجملة.");
        }
    }

    /**
     * Returns the effective quantity cap per cart line based on customer type (0 = uncapped for wholesale).
     */
    public function lineQtyCap(?Customer $customer): float
    {
        if ($customer === null) {
            return (float) config('store.guest_max_line_qty', 10);
        }
        if ($customer->status === CustomerStatus::Approved
            && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
            return 0.0;
        }

        return (float) config('store.retail_max_line_qty', 50);
    }

    /**
     * Computes the maximum purchasable quantity considering branch availability and request caps.
     */
    public function maxPurchasableQty(float $available, ?Customer $customer): float
    {
        $cap = $this->lineQtyCap($customer);

        return max(0.0, min($available, self::MAX_REQUEST_QTY, $cap > 0 ? $cap : self::MAX_REQUEST_QTY));
    }

    /**
     * Asserts that the quantity is a positive whole integer.
     */
    public function assertWholeQuantity(float $qty, bool $allowZero = false): void
    {
        DiscreteQuantity::assertWhole($qty, $allowZero);
    }

    /**
     * Verifies that one branch can fulfill the requested variant quantity.
     */
    private function assertAvailable(int $variantId, float $qty): void
    {
        $available = $this->catalog->fulfillableQuantityMap([$variantId])[$variantId] ?? 0;
        if ($available < $qty) {
            throw new BusinessException('الكمية المطلوبة غير متاحة حاليًا لهذا الصنف. يمكن تجهيز حتى '.max(0, floor($available)).' قطعة من فرع واحد.');
        }
    }

    /**
     * Ensures the variant has a valid pricing rule before adding to cart.
     */
    private function assertPriced(ProductVariant $variant, ?Customer $customer, float $qty): void
    {
        $this->pricing->resolve($variant, $customer, $qty);
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\StockBucket;
use App\Enums\StockMovementType;
use App\Exceptions\BusinessException;
use App\Models\Branch;
use App\Models\Order;
use App\Models\OrderItem;
use App\Models\StockLevel;
use App\Models\StockMovement;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;

/**
 * Allocates and reserves order inventory across branches based on proximity, stock availability, and split policies.
 */
class OrderAllocationService
{
    public function __construct(protected InventoryService $inventoryService) {}

    /**
     * Allocates order items to branch inventory and reserves stock atomically.
     *
     * @param Order $order Placed order to allocate
     * @param int|null $forcedBranchId Manually selected branch by administrator, if any
     * @param int|null $performedBy User ID performing the allocation
     * @return Order Updated order with allocated branches
     * @throws BusinessException If order is in invalid status, already allocated, or insufficient stock
     */
    public function allocate(Order $order, ?int $forcedBranchId = null, ?int $performedBy = null): Order
    {
        return DB::transaction(function () use ($order, $forcedBranchId, $performedBy): Order {
            // Re-read order under row lock to prevent concurrent allocation attempts.
            $order = Order::query()->lockForUpdate()->findOrFail($order->id);
            $order->load('items');
            // Consistent lock order by product_variant_id prevents deadlocks between concurrent allocations.
            $order->setRelation('items', $order->items
                ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
                ->values());
            $performedBy ??= auth()->id();

            if (in_array($order->status, [\App\Enums\OrderStatus::Cancelled, \App\Enums\OrderStatus::Shipped, \App\Enums\OrderStatus::Delivered, \App\Enums\OrderStatus::Returned], true)) {
                throw new BusinessException('التوزيع غير متاح على هذه الحالة.');
            }

            if ($order->allocated_branch_id !== null
                || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null)) {
                throw new BusinessException('الطلب مُوزّع على الفروع من قبل؛ ألغِ التوزيع الحالي أولًا قبل إعادة التوزيع.');
            }

            if ($forcedBranchId !== null) {
                $branch = Branch::query()->where('is_active', true)->find($forcedBranchId);
                if ($branch === null) {
                    throw new BusinessException('الفرع المحدد غير موجود أو غير نشط.');
                }
                $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
                $order->update(['allocated_branch_id' => $branch->id]);

                return $order->fresh(['items']);
            }

            // Pre-calculate aggregate branch availability to evaluate allocation rules in memory.
            $coverage = $this->branchAvailabilityMap($order);

            $cityName = $order->city?->name_ar;
            $branches = Branch::query()
                ->where('is_active', true)
                ->when($order->city_id !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city_id = ? THEN 0 ELSE 1 END', [$order->city_id]))
                // Use CASE ordering instead of DESC because Postgres places NULLs first in DESC sorting.
                ->when($cityName !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city = ? THEN 0 ELSE 1 END', [$cityName]))
                ->orderBy('id')
                ->get();

            $candidateAttempts = 0;
            foreach ($branches as $branch) {
                if ($this->canBranchFulfillFullOrder($order, $branch->id, $coverage)) {
                    if (++$candidateAttempts > 3) {
                        break;
                    }
                    try {
                        return DB::transaction(function () use ($order, $branch, $performedBy): Order {
                            $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
                            $order->update(['allocated_branch_id' => $branch->id]);

                            return $order->fresh(['items']);
                        });
                    } catch (BusinessException $e) {
                        if ($e->errorCode !== 'insufficient_stock') {
                            throw $e;
                        }
                        $order->load('items');
                    }
                }
            }

            // A bounded retry recalculates coverage after a competing checkout.
            for ($attempt = 0; $attempt < 3; $attempt++) {
                $coverage = $this->branchAvailabilityMap($order);
                // Aggregate required quantity per variant so duplicate items do not choose an insufficient branch.
                $required = $this->requiredPerVariant($order);
                $plan = [];
                foreach ($order->items as $item) {
                    $variantId = (int) $item->product_variant_id;
                    if (array_key_exists($variantId, $plan)) {
                        continue;
                    }
                    $branchId = $this->bestBranchForItem($item, $coverage, $required[$variantId]);
                    if ($branchId === null) {
                        throw new BusinessException("الرصيد المتاح للصنف [{$item->sku_snapshot}] غير كافٍ لإتمام الطلب.");
                    }
                    $plan[$variantId] = $branchId;
                }
                try {
                    return DB::transaction(function () use ($order, $plan, $performedBy): Order {
                        $levels = $this->lockPlannedLevels($plan);
                        foreach ($order->items as $item) {
                            $branchId = $plan[(int) $item->product_variant_id];
                            $this->reserveItemFromBranch($order, $item, $branchId, $performedBy, $levels);
                            $item->update(['allocated_branch_id' => $branchId]);
                        }

                        return $order->fresh(['items']);
                    });
                } catch (BusinessException $e) {
                    if ($e->errorCode !== 'insufficient_stock' || $attempt === 2) {
                        throw $e;
                    }
                    $order->load('items');
                }
            }
            throw new BusinessException('تغير المخزون أثناء الحجز؛ أعد المحاولة.', [], 409);
        });
    }

    /**
     * Releases all inventory reservations tied to an allocated order and clears allocation state.
     *
     * @param Order $order Order to deallocate
     * @param int|null $performedBy User ID performing the action
     * @return Order Deallocated order instance
     * @throws BusinessException If order cannot be deallocated
     */
    public function deallocate(Order $order, ?int $performedBy = null): Order
    {
        return DB::transaction(function () use ($order, $performedBy): Order {
            $order = Order::query()->lockForUpdate()->findOrFail($order->id);
            $order->load('items');
            // Consistent lock order by product_variant_id prevents deadlocks between concurrent allocations.
            $order->setRelation('items', $order->items
                ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
                ->values());
            $performedBy ??= auth()->id();

            if (in_array($order->status, [\App\Enums\OrderStatus::Cancelled, \App\Enums\OrderStatus::Shipped, \App\Enums\OrderStatus::Delivered, \App\Enums\OrderStatus::Returned], true)) {
                throw new BusinessException('فك التوزيع غير متاح على هذه الحالة.');
            }

            if (! $this->isAllocated($order)) {
                throw new BusinessException('الطلب غير موزّع على أي فرع؛ لا شيء لفكه.');
            }

            // Calculate net reservations from ledger movements so deallocations remain idempotent.
            $net = StockMovement::query()
                ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
                ->where('reference_id', $order->id)
                ->whereIn('type', [StockMovementType::Reserve->value, StockMovementType::ReleaseReserve->value])
                ->groupBy('product_variant_id', 'branch_id', 'location_id')
                ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty')
                ->get()
                ->map(fn ($row): array => [
                    'product_variant_id' => (int) $row->product_variant_id,
                    'branch_id' => (int) $row->branch_id,
                    'location_id' => $row->location_id === null ? null : (int) $row->location_id,
                    'net_qty' => (float) $row->net_qty,
                ])
                ->filter(fn (array $row): bool => $row['net_qty'] > 1e-9)
                ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
                ->values();

            $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
                'product_variant_id' => $row['product_variant_id'],
                'branch_id' => $row['branch_id'],
                'location_id' => $row['location_id'],
            ])->all());

            foreach ($net as $row) {
                $this->inventoryService->recordMovement([
                    'product_variant_id' => (int) $row['product_variant_id'],
                    'branch_id' => (int) $row['branch_id'],
                    'location_id' => $row['location_id'],
                    'type' => StockMovementType::ReleaseReserve,
                    'affected_bucket' => StockBucket::Reserved,
                    'quantity' => -1 * (float) $row['net_qty'],
                    'reference_type' => Order::class,
                    'reference_id' => $order->id,
                    'created_by' => $performedBy,
                    'notes' => "فك يدوي لتوزيع الطلب رقم {$order->order_number}",
                ], $levels->get($this->inventoryService->levelKey($row)));
            }

            $order->items()->update(['allocated_branch_id' => null]);
            $order->update(['allocated_branch_id' => null]);

            return $order->fresh(['items']);
        });
    }

    /**
     * Checks whether an order or any of its items has an allocated branch.
     *
     * @param Order $order Order to check
     * @return bool True if allocated at order level or item level
     */
    public function isAllocated(Order $order): bool
    {
        return $order->allocated_branch_id !== null
            || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null);
    }

    /** Lock only the branch/variant pairs selected by the coverage plan. */
    private function lockPlannedLevels(array $plan): Collection
    {
        if ($plan === []) {
            return collect();
        }
        $rows = StockLevel::query()->where(function ($query) use ($plan): void {
            foreach ($plan as $variantId => $branchId) {
                $query->orWhere(fn ($q) => $q->where('product_variant_id', $variantId)->where('branch_id', $branchId));
            }
        })->where(fn ($q) => $q->whereNull('location_id')->orWhereHas('location', fn ($q) => $q->where('is_active', true)->whereNotIn('type', ['receiving', 'damaged'])))->get();

        return $this->inventoryService->lockLevels($rows->map->getAttributes()->all());
    }

    private function branchAvailabilityMap(Order $order): array
    {
        $variantIds = $order->items
            ->map(fn (OrderItem $item): int => (int) $item->product_variant_id)
            ->unique()->values()->all();

        $rows = StockLevel::query()
            ->whereIn('product_variant_id', $variantIds)
            ->whereHas('branch', fn (Builder $q): Builder => $q->where('is_active', true))
            ->where(fn (Builder $q): Builder => $q
                ->whereNull('location_id')
                ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)->whereNotIn('type', ['receiving', 'damaged'])))
            ->groupBy('branch_id', 'product_variant_id')
            ->selectRaw('branch_id, product_variant_id, SUM(available) as total_available')
            ->get();

        $map = [];
        foreach ($rows as $row) {
            $map[(int) $row->branch_id][(int) $row->product_variant_id] = (float) $row->total_available;
        }

        return $map;
    }

    private function requiredPerVariant(Order $order): array
    {
        $required = [];
        foreach ($order->items as $item) {
            $vid = (int) $item->product_variant_id;
            $required[$vid] = ($required[$vid] ?? 0) + (int) round((float) $item->qty * 10000);
        }

        return $required;
    }

    private function canBranchFulfillFullOrder(Order $order, int $branchId, array $coverage): bool
    {
        foreach ($this->requiredPerVariant($order) as $variantId => $qty) {
            if ((int) round(($coverage[$branchId][$variantId] ?? 0) * 10000) < $qty) {
                return false;
            }
        }

        return true;
    }

    private function bestBranchForItem(OrderItem $item, array $coverage, ?int $requiredQty = null): ?int
    {
        $need = $requiredQty ?? (int) round((float) $item->qty * 10000);
        $best = null;
        $bestAvailable = 0.0;
        foreach ($coverage as $branchId => $variants) {
            $available = $variants[(int) $item->product_variant_id] ?? 0;
            if ((int) round($available * 10000) >= $need && $available > $bestAvailable) {
                $best = $branchId;
                $bestAvailable = $available;
            }
        }

        return $best;
    }

    private function reserveItemsFromBranch(Order $order, int $branchId, ?int $performedBy): void
    {
        $levels = $this->lockPlannedLevels($order->items->mapWithKeys(fn ($item) => [(int) $item->product_variant_id => $branchId])->all());
        foreach ($order->items as $item) {
            $this->reserveItemFromBranch($order, $item, $branchId, $performedBy, $levels);
            $item->update(['allocated_branch_id' => $branchId]);
        }
    }

    private function reserveItemFromBranch(Order $order, OrderItem $item, int $branchId, ?int $performedBy, Collection $levels): void
    {
        $remaining = (int) round((float) $item->qty * 10000);
        foreach ($levels->where('product_variant_id', $item->product_variant_id)->where('branch_id', $branchId)->sortByDesc('available') as $level) {
            $take = min((int) round($level->available * 10000), $remaining);
            if ($take <= 0) {
                continue;
            }
            $this->inventoryService->recordMovement([
                'product_variant_id' => (int) $item->product_variant_id, 'branch_id' => $branchId,
                'location_id' => $level->location_id, 'type' => StockMovementType::Reserve,
                'affected_bucket' => StockBucket::Reserved, 'quantity' => $take / 10000,
                'reference_type' => Order::class, 'reference_id' => $order->id,
                'created_by' => $performedBy, 'notes' => 'حجز للطلب '.$order->order_number,
            ], $level);
            $remaining -= $take;
            if ($remaining === 0) {
                break;
            }
        }
        if ($remaining > 0) {
            throw new BusinessException('الرصيد المتاح تغير أثناء الحجز.', errorCode: 'insufficient_stock');
        }
    }

    private function usableLevels(int $variantId, ?int $branchId = null): Builder
    {
        return StockLevel::query()
            ->where('product_variant_id', $variantId)
            ->when($branchId !== null, fn (Builder $q): Builder => $q->where('branch_id', $branchId))
            ->where(fn (Builder $q): Builder => $q
                ->whereNull('location_id')
                ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)));
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\TreasuryTransactionType;
use App\Enums\TreasuryTransferStatus;
use App\Exceptions\BusinessException;
use App\Models\Branch;
use App\Models\PosShift;
use App\Models\Treasury;
use App\Models\TreasuryTransaction;
use App\Models\TreasuryTransfer;
use App\Models\User;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;

/**
 * Single entry point for treasury mutations, enforcing balance integrity and audit logging.
 */
class TreasuryService
{
    public function __construct(private readonly SettingService $settings) {}

    public function createAccount(array $data, User $actor, string $opening = '0.00'): Treasury
    {
        $this->assertAccountBranch($actor, isset($data['branch_id']) ? (int) $data['branch_id'] : null);

        return DB::transaction(function () use ($data, $actor, $opening): Treasury {
            $treasury = Treasury::create($data + ['current_balance' => '0.00']);
            if (bccomp($opening, '0', 2) !== 0) {
                $this->record([
                    'treasury_id' => $treasury->id,
                    'type' => TreasuryTransactionType::OpeningBalance,
                    'amount' => $opening,
                    'created_by' => $actor->id,
                    'notes' => "رصيد افتتاحي #{$treasury->code}",
                ]);
            }

            return $treasury->refresh();
        });
    }

    public function updateAccount(Treasury $treasury, array $data, User $actor): Treasury
    {
        if (array_key_exists('branch_id', $data)) {
            $this->assertAccountBranch($actor, isset($data['branch_id']) ? (int) $data['branch_id'] : null);
        }

        return DB::transaction(function () use ($treasury, $data, $actor): Treasury {
            $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
            app(BranchAccess::class)->assertTreasury($actor->id, $locked);
            if (isset($data['type']) && $data['type'] !== $locked->type->value) {
                throw new BusinessException('نوع الخزينة غير قابل للتغيير.');
            }
            $unsettled = $locked->shifts()->whereIn('status', ['open', 'closed_pending_approval'])->exists();
            if (array_key_exists('branch_id', $data) && $data['branch_id'] != $locked->branch_id
                && ($unsettled || bccomp($locked->current_balance, '0', 2) !== 0 || $locked->transactions()->exists())) {
                throw new BusinessException('لا يمكن نقل خزينة لها رصيد أو سجل حركات إلى فرع آخر.');
            }
            if ($unsettled && array_key_exists('is_active', $data) && ! $data['is_active']) {
                throw new BusinessException('لا يمكن تعطيل درج له وردية لم تُسوَّ.');
            }
            $locked->update($data);

            return $locked;
        });
    }

    public function deleteAccount(Treasury $treasury, User $actor): void
    {
        DB::transaction(function () use ($treasury, $actor): void {
            $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
            app(BranchAccess::class)->assertTreasury($actor->id, $locked);
            if (bccomp($locked->current_balance, '0', 2) !== 0 || $locked->transactions()->exists() || $locked->shifts()->exists()) {
                throw new BusinessException('لا يمكن حذف خزينة لها رصيد أو سجل حركات أو ورديات.');
            }
            $locked->delete();
        });
    }

    private function assertAccountBranch(User $actor, ?int $branchId): void
    {
        $branches = app(BranchAccess::class);
        if ($branchId === null) {
            $branches->assertCentralAccess($actor);
        } else {
            $branches->assertBranch($actor->id, $branchId);
        }
    }

    /**
     * Records a financial transaction and updates treasury balance under a row lock.
     *
     * @param array{
     *     treasury_id: int,
     *     shift_id?: int|null,
     *     type: TreasuryTransactionType,
     *     amount: float|string,
     *     reference_type?: string|null,
     *     reference_id?: int|null,
     *     created_by: int,
     *     notes?: string|null,
     * } $data Transaction payload
     * @return TreasuryTransaction Created transaction record
     *
     * @throws BusinessException If treasury is inactive or insufficient funds
     */
    public function record(array $data): TreasuryTransaction
    {
        return DB::transaction(function () use ($data): TreasuryTransaction {
            /** @var Treasury $treasury */
            $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
            if ($treasury->branch_id !== null) {
                app(BranchAccess::class)->lockActiveBranch((int) $treasury->branch_id);
            }

            if (! $treasury->is_active && $data['type'] !== TreasuryTransactionType::ExpenseReversal) {
                throw new BusinessException('الخزينة غير نشطة.');
            }

            $amount = BigDecimal::of((string) $data['amount'])->toScale(2, RoundingMode::HalfUp);
            $balanceAfter = BigDecimal::of((string) $treasury->current_balance)->plus($amount)->toScale(2);

            // Bank accounts support overdrafts; physical safes and POS drawers cannot go negative.
            if ($balanceAfter->isNegative() && $treasury->type->value !== 'bank_account') {
                throw new BusinessException('رصيد الخزينة غير كافٍ لإتمام العملية.');
            }

            $transaction = TreasuryTransaction::create([
                'treasury_id' => $treasury->id,
                'shift_id' => $data['shift_id'] ?? null,
                'type' => $data['type'],
                'amount' => (string) $amount,
                'balance_after' => (string) $balanceAfter,
                'reference_type' => $data['reference_type'] ?? null,
                'reference_id' => $data['reference_id'] ?? null,
                'created_by' => $data['created_by'],
                'notes' => $data['notes'] ?? null,
                'created_at' => now(),
            ]);

            $treasury->current_balance = (string) $balanceAfter;
            $treasury->save();

            return $transaction;
        });
    }

    /**
     * Approves and executes a pending treasury transfer between two accounts.
     *
     * @param  TreasuryTransfer  $transfer  Transfer to approve
     * @param  int  $approverId  User approving the transfer
     * @return TreasuryTransfer Updated transfer record
     *
     * @throws BusinessException If transfer is not pending, self-approved, or unauthorized
     */
    public function approveTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
    {
        return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
            $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
            if ($transfer->status !== TreasuryTransferStatus::Pending) {
                throw new BusinessException('يمكن اعتماد التحويلات المعلقة فقط.');
            }
            // Segregation of duties: creator cannot approve their own transfer.
            if ((int) $transfer->created_by === $approverId) {
                throw new BusinessException('يجب أن يعتمد تحويل الخزينة موظف آخر غير منشئه.');
            }
            $treasuries = $this->lockTreasuries([$transfer->from_treasury_id, $transfer->to_treasury_id], $approverId);
            app(BranchAccess::class)->lockActiveBranches($treasuries->pluck('branch_id')->filter());
            $absAmount = (string) BigDecimal::of((string) $transfer->amount)->abs()->toScale(2, RoundingMode::HalfUp);

            $this->record([
                'treasury_id' => $transfer->from_treasury_id,
                'type' => TreasuryTransactionType::TransferOut,
                'amount' => '-'.$absAmount,
                'reference_type' => TreasuryTransfer::class,
                'reference_id' => $transfer->id,
                'created_by' => $approverId,
                'notes' => "تحويل #{$transfer->transfer_number} صادر",
            ]);

            $this->record([
                'treasury_id' => $transfer->to_treasury_id,
                'type' => TreasuryTransactionType::TransferIn,
                'amount' => $absAmount,
                'reference_type' => TreasuryTransfer::class,
                'reference_id' => $transfer->id,
                'created_by' => $approverId,
                'notes' => "تحويل #{$transfer->transfer_number} وارد",
            ]);

            $transfer->update([
                'status' => TreasuryTransferStatus::Approved,
                'approved_by' => $approverId,
            ]);

            return $transfer->fresh();
        }, 3);
    }

    /**
     * Reconciles POS cash drawer variance and transfers closing cash to the branch main safe.
     *
     * @param  PosShift  $shift  Completed POS shift
     * @param  int  $approverId  Manager approving the shift settlement
     *
     * @throws BusinessException If main safe is missing or unauthorized
     */
    public function settleShiftToMainSafe(PosShift $shift, int $approverId): void
    {
        DB::transaction(function () use ($shift, $approverId): void {
            // Deterministic selection picks the oldest active safe when multiple exist.
            $mainSafe = Treasury::query()
                ->where('branch_id', $shift->branch_id)
                ->where('type', 'main_safe')
                ->where('is_active', true)
                ->orderBy('id')
                ->first();

            if ($mainSafe === null) {
                throw new BusinessException('يلزم وجود خزنة رئيسية نشطة لاعتماد الوردية وتسوية رصيد الدرج.');
            }

            $locked = $this->lockTreasuries([$shift->treasury_id, $mainSafe->id]);
            app(BranchAccess::class)->lockActiveBranches($locked->pluck('branch_id')->filter());
            $drawer = $locked->get($shift->treasury_id);
            $amount = (string) BigDecimal::of((string) $shift->actual_closing_cash)->toScale(2, RoundingMode::HalfUp);
            $difference = BigDecimal::of((string) $shift->actual_closing_cash)
                ->minus((string) $drawer->current_balance)->toScale(2);
            if (! $difference->isZero()) {
                $this->record([
                    'treasury_id' => $drawer->id, 'shift_id' => $shift->id,
                    'type' => $difference->isNegative() ? TreasuryTransactionType::CashShortage : TreasuryTransactionType::CashOverage,
                    'amount' => (string) $difference, 'reference_type' => PosShift::class,
                    'reference_id' => $shift->id, 'created_by' => $approverId,
                    'notes' => 'تسوية فرق النقدية للوردية '.$shift->shift_number,
                ]);
            }

            if (BigDecimal::of($amount)->isLessThanOrEqualTo('0')) {
                return;
            }

            $this->record([
                'treasury_id' => $shift->treasury_id,
                'type' => TreasuryTransactionType::TransferOut,
                'amount' => '-'.$amount,
                'reference_type' => PosShift::class,
                'reference_id' => $shift->id,
                'created_by' => $approverId,
                'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
            ]);

            $this->record([
                'treasury_id' => $mainSafe->id,
                'type' => TreasuryTransactionType::TransferIn,
                'amount' => $amount,
                'reference_type' => PosShift::class,
                'reference_id' => $shift->id,
                'created_by' => $approverId,
                'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
            ]);
        });
    }

    /**
     * Creates a pending transfer request between two treasuries.
     *
     * @param  array<string, mixed>  $data  Transfer parameters
     * @param  int  $userId  Creator identifier
     * @return TreasuryTransfer Created pending transfer
     *
     * @throws BusinessException If source equals destination or unauthorized
     */
    public function createTransfer(array $data, int $userId): TreasuryTransfer
    {
        return DB::transaction(function () use ($data, $userId): TreasuryTransfer {
            $treasuries = Treasury::query()->whereIn('id', [$data['from_treasury_id'], $data['to_treasury_id']])->get();
            foreach ($treasuries as $treasury) {
                app(BranchAccess::class)->assertTreasury($userId, $treasury);
            }
            app(BranchAccess::class)->lockActiveBranches($treasuries->pluck('branch_id')->filter());
            if ($data['from_treasury_id'] === $data['to_treasury_id']) {
                throw new BusinessException('لا يمكن التحويل من خزينة إلى نفسها.');
            }

            $number = $this->settings->generateNextNumber('treasury_transfer');

            return TreasuryTransfer::create([
                'transfer_number' => $number,
                'from_treasury_id' => $data['from_treasury_id'],
                'to_treasury_id' => $data['to_treasury_id'],
                'amount' => $data['amount'],
                'status' => TreasuryTransferStatus::Pending,
                'created_by' => $userId,
                'notes' => $data['notes'] ?? null,
            ]);
        }, 3);
    }

    /**
     * Rejects a pending treasury transfer without altering account balances.
     *
     * @param  TreasuryTransfer  $transfer  Transfer to reject
     * @param  int  $approverId  User rejecting the transfer
     * @param  string|null  $reason  Optional audit reason (kept for the AI finance tools)
     * @return TreasuryTransfer Updated transfer record
     *
     * @throws BusinessException If transfer is not pending
     */
    public function rejectTransfer(TreasuryTransfer $transfer, int $approverId, ?string $reason = null): TreasuryTransfer
    {
        return DB::transaction(function () use ($transfer, $approverId, $reason): TreasuryTransfer {
            $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
            if ($transfer->status !== TreasuryTransferStatus::Pending) {
                throw new BusinessException('يمكن رفض التحويلات المعلقة فقط.');
            }
            // Rejections carry no financial movement, avoiding unnecessary row locking contention.
            $transfer->update(['status' => TreasuryTransferStatus::Rejected, 'approved_by' => $approverId, 'rejection_reason' => $reason]);

            return $transfer->fresh();
        }, 3);
    }

    /**
     * Acquires pessimistic locks on specified treasuries in consistent primary key order to prevent deadlocks.
     *
     * @param  list<int>  $ids  Treasury identifiers
     * @param  int|null  $userId  User to verify branch access against
     * @return Collection<int, Treasury> Locked treasuries keyed by ID
     */
    public function lockTreasuries(array $ids, ?int $userId = null): Collection
    {
        $treasuries = Treasury::query()->whereIn('id', $ids)->orderBy('id')->lockForUpdate()->get()->keyBy('id');
        if ($userId !== null) {
            foreach ($treasuries as $treasury) {
                app(BranchAccess::class)->assertTreasury($userId, $treasury);
            }
        }

        return $treasuries;
    }
}<?php

