export const productMediaApi = {
  list: (productId: number) => apiClient.get<{ data: AdminMedia[] }>(`${PR}/${productId}/media`).then(r => r.data.data),
  uploadImages: (productId: number, files: File[], variantId?: number | null, onProgress?: (n: number) => void, clientUploadIds?: string[]) => {
    const fd = new FormData();
    fd.append('collection', 'images');
    if (variantId) fd.append('variant_id', String(variantId));
    files.forEach((f, index) => {
      fd.append('files[]', f); // max 4 per request
      fd.append('client_upload_ids[]', clientUploadIds?.[index] ?? crypto.randomUUID());
    });
    return apiClient.post<{ data: AdminMedia[] }>(`${PR}/${productId}/media`, fd, { ...MULTIPART, timeout: 180000, onUploadProgress: progress(onProgress) }).then(r => r.data.data);
  },
  uploadVideo: (productId: number, file: File, onProgress?: (n: number) => void) => {
    const fd = new FormData();
    fd.append('collection', 'video');
    fd.append('file', file);
    return apiClient.post<{ data: AdminMedia[] }>(`${PR}/${productId}/media`, fd, { ...MULTIPART, onUploadProgress: progress(onProgress), timeout: 0 }).then(r => r.data.data);
  },
  reorder: (productId: number, ids: number[]) => apiClient.put(`${PR}/${productId}/media/reorder`, { ids }).then(r => r.data),
  remove: (productId: number, mediaId: number) => apiClient.delete(`${PR}/${productId}/media/${mediaId}`).then(r => r.data),
};<?php

declare(strict_types=1);

namespace App\Services\Ai;

use App\Exceptions\BusinessException;
use App\Exceptions\RetryableConflict;
use App\Models\AiMessage;
use App\Models\AiPendingAction;
use App\Models\User;
use App\Services\Ai\Contracts\ExecutesOutsideTransaction;
use App\Services\Ai\Contracts\ToolProvider;
use App\Services\Ai\WhatsApp\WhatsAppActorContext;
use App\Services\SettingService;
use App\Services\StaffAdministration;
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Database\Eloquent\ModelNotFoundException;
use Illuminate\Database\QueryException;
use Illuminate\Database\UniqueConstraintViolationException;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
use Spatie\Permission\Exceptions\RoleAlreadyExists;
use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface;

final class PendingActionService
{
    public function __construct(private ToolRegistry $registry, private SettingService $settings) {}

    public function confirm(User $actor, AiPendingAction $action, ?string $typed = null, ?array $selectedItems = null): ToolOutcome
    {
        if ($action->tool === 'bulk_actions') {
            return $this->confirmBulk($actor, $action, $typed, $selectedItems);
        }
        $toolInstance = $this->registry->toolInstance($action->tool);
        if ($toolInstance instanceof ExecutesOutsideTransaction && $toolInstance->executesOutsideTransaction($action)) {
            return $this->confirmOutsideTransaction($actor, $action, $typed, $toolInstance);
        }
        try {
            $result = DB::transaction(function () use ($actor, $action, $typed, $selectedItems) {
                $this->lockForAction($action->tool);
                $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
                try {
                    return $this->confirmLocked($actor, $locked, $typed, $selectedItems);
                } catch (HttpExceptionInterface $e) {
                    return $e;
                }
            });
        } catch (\Throwable $e) {
            // M-3: unexpected errors must not leave the proposal stuck in
            // pending — record the failure outside the rolled-back transaction.
            if (! $e instanceof HttpExceptionInterface) {
                AiPendingAction::whereKey($action->id)->where('status', 'pending')
                    ->update(['status' => 'failed', 'result' => ['message' => 'تعذّر التنفيذ بسبب خطأ غير متوقع؛ اطلب اقتراحًا جديدًا.']]);
            }
            throw $e;
        }
        if ($result instanceof \Throwable) {
            throw $result;
        }

        return $result;
    }

    private function confirmOutsideTransaction(User $actor, AiPendingAction $action, ?string $typed, WriteTool $tool): ToolOutcome
    {
        $claim = DB::transaction(function () use ($actor, $action, $typed) {
            $this->lockForAction($action->tool);
            $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
            try {
                return $this->confirmLocked($actor, $locked, $typed);
            } catch (HttpExceptionInterface $e) {
                return $e;
            }
        });
        if ($claim instanceof \Throwable) {
            throw $claim;
        }
        if ($claim instanceof ToolOutcome && $claim->type !== 'claimed') {
            return $claim;
        }

        try {
            $outcome = $tool->execute($actor, $action->fresh() ?? $action);
        } catch (\Throwable $e) {
            DB::transaction(function () use ($action, $e): void {
                $locked = AiPendingAction::query()->lockForUpdate()->find($action->id);
                if ($locked && $locked->status === 'confirmed') {
                    $message = ($e instanceof BusinessException || $e instanceof ValidationException)
                        ? ($e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage())
                        : 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.';
                    $this->markFailed($locked, $message ?: 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.');
                }
            });
            if ($e instanceof BusinessException && $e->status === 409) {
                abort(409, $e->getMessage());
            }
            if ($e instanceof HttpExceptionInterface) {
                throw $e;
            }
            if ($e instanceof BusinessException || $e instanceof ValidationException) {
                $msg = $e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage();

                return ToolOutcome::result(false, $msg ?: 'تعذّر التنفيذ.');
            }
            throw $e;
        }

        return DB::transaction(function () use ($action, $outcome): ToolOutcome {
            $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
            if ($locked->status === 'confirmed') {
                return $this->finalizeAction($locked, $outcome);
            }

            return ToolOutcome::wrap($outcome->type, $outcome->data, $outcome->uiBlock, $outcome->message);
        });
    }

    private function confirmBulk(User $actor, AiPendingAction $action, ?string $typed, ?array $selectedItems): ToolOutcome
    {
        $claim = DB::transaction(function () use ($actor, $action, $typed, $selectedItems) {
            StaffAdministration::lock();
            $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
            abort_unless($locked->user_id === $actor->id, 403);
            $this->authorizeTool($actor, $locked);
            if ($locked->status === 'executed') {
                return ToolOutcome::result((bool) ($locked->result['ok'] ?? false), $locked->result['message'], $locked->result);
            }
            abort_unless($locked->status === 'pending' && $locked->expires_at->isFuture(), 409, 'العملية الجماعية مش متاحة للتنفيذ.');
            abort_unless(trim((string) $typed) === 'تنفيذ', 422, 'اكتب تنفيذ لتأكيد المجموعة.');
            $ids = $locked->args['action_ids'];
            $selected = $selectedItems ?? $ids;
            abort_if(! $selected || array_diff($selected, $ids) !== [] || count(array_unique($selected)) !== count($selected), 422);
            $locked->forceFill(['status' => 'confirmed'])->save();
            // M-4: المختارون فقط يتحولون لـ pending، والباقون يُلغون في نفس
            // الـ transaction — فلا نافذة سباق لتأكيد مستبعد من تبويب آخر،
            // ولا أيتام pending لو انهارت العملية بعد الـ claim.
            AiPendingAction::query()->whereIn('id', $selected)->where('status', 'bulk_child')->update(['status' => 'pending']);
            AiPendingAction::query()->whereIn('id', array_diff($ids, $selected))->whereIn('status', ['bulk_child', 'pending'])->update(['status' => 'cancelled']);

            return ['selected' => $selected, 'all' => $ids];
        });
        if ($claim instanceof ToolOutcome) {
            return $claim;
        }
        $results = [];
        foreach ($claim['selected'] as $id) {
            $child = AiPendingAction::query()->where('conversation_id', $action->conversation_id)->where('user_id', $actor->id)->findOrFail($id);
            try {
                // M-5: set_branch_status خرج من الـ bulk نهائيًا (كان نص
                // "تنفيذ" واحد يؤكد تعطيل فروع، والحماية بالكود المكتوب
                // تُلغى من السيرفر بتعبئة تلقائية — residual risk M10).
                // لا تعبئة تلقائية لأي نص تأكيد هنا: أي عنصر عالي الخطورة
                // في مجموعة قديمة بلا نص مدخل من المستخدم يفشل برسالة
                // واضحة بدل تنفيذه بتعبئة من السيرفر.
                $outcome = $this->confirm($actor, $child, null);
                $results[] = ['action_id' => $id, 'ok' => $outcome->type === 'result', 'message' => $outcome->message];
            } catch (QueryException $e) {
                if (! $this->isRetryableLockFailure($e)) {
                    report($e);
                    AiPendingAction::whereKey($id)->where('status', 'pending')->update(['status' => 'failed']);
                    $results[] = ['action_id' => $id, 'ok' => false, 'message' => 'تعذّر تنفيذ العنصر ده ضمن الدفعة؛ راجع التفاصيل أو جرّبه لوحده.'];

                    continue;
                }
                $this->retryBulkConflict($action, $claim, $results);
            } catch (RetryableConflict $e) {
                // H2: قفل/تايم-أوت من confirmLocked أو StaffAdministration::lock
                // يصل هنا كاستثناء مخصص — نفس مسار إعادة المحاولة، لا failed.
                $this->retryBulkConflict($action, $claim, $results);
            } catch (\Throwable $e) {
                if (! $e instanceof HttpExceptionInterface && ! $e instanceof ValidationException) {
                    report($e);
                }
                AiPendingAction::whereKey($id)->where('status', 'pending')->update(['status' => 'failed']);
                $results[] = ['action_id' => $id, 'ok' => false, 'message' => 'تعذّر تنفيذ العنصر ده ضمن الدفعة؛ راجع التفاصيل أو جرّبه لوحده.'];
            }
        }
        $successes = count(array_filter($results, fn ($item) => $item['ok']));
        $ok = $successes === count($results);
        $message = 'تم تنفيذ '.$successes.' من '.count($results).' عمليات.';
        // L4: الأب الفاشل كليًا يُوسم failed لا executed — وإلا usage()
        // والتقارير تحسبه نجاحًا.
        $parentStatus = $successes === 0 ? 'failed' : 'executed';
        $action->refresh()->forceFill(['status' => $parentStatus, 'executed_at' => now(), 'result' => ['ok' => $ok, 'message' => $message, 'items' => $results]])->save();
        $block = ['type' => 'result', 'ok' => $ok, 'message' => $message, 'items' => $results];
        $this->event($action, 'result', $message, [$block]);

        return ToolOutcome::result($ok, $message, ['items' => $results], $block);
    }

    /**
     * H2: تعارض مؤقت أثناء تأكيد عنصر جماعي — الأب يرجع pending
     * (قابل للتأكيد من جديد)، والعنصر الحالي يبقى pending، ولا شيء يوسم
     * failed. تُرمى 409 دائمًا بعد تسجيل حدث النتيجة.
     *
     * @param  array{selected:list<string>,all:list<string>}  $claim
     * @param  list<array{action_id:string,ok:bool,message:string}>  $results
     */
    private function retryBulkConflict(AiPendingAction $action, array $claim, array $results): never
    {
        AiPendingAction::whereKey($action->id)->where('status', 'confirmed')->update(['status' => 'pending']);
        $done = count(array_filter($results, fn ($item) => $item['ok']));
        $message = $done === 0
            ? 'السجل مشغول بتعديل تاني؛ مفيش حاجة اتنفذت. جرّب تأكيد الدفعة تاني بعد لحظة.'
            : 'السجل مشغول بتعديل تاني؛ العناصر المنفذة: '.$done.' من '.count($claim['selected']).'. الباقي ما اتنفذش — جرّب تأكيد الدفعة تاني بعد لحظة.';
        $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
        abort(409, $message);
    }

    /**
     * M7: القفل الاستشاري العام لأدوات إدارة الموظفين فقط. أدوات
     * الكتالوج والمخزون تعتمد على أقفالها الخاصة (CatalogLock::tree +
     * أقفال الصفوف، أو InventoryService::lockLevels بترتيب ثابت)، فأخذ
     * القفل العام عند تأكيدها كان يسلسل كل شيء خلف أثقل عملية.
     */
    private function lockForAction(string $tool): void
    {
        $def = $this->registry->definitions()[$tool] ?? null;
        $provider = $def['provider'] ?? null;
        if ($provider instanceof ToolProvider && ! $provider->usesGlobalAdminLock()) {
            return;
        }
        StaffAdministration::lock();
    }

    private function authorizeTool(User $actor, AiPendingAction $action): void
    {
        $actor->refresh();
        abort_unless($this->settings->getBool('ai_enabled', false), 403, 'المساعد مقفول.');
        $disabled = $this->settings->get('ai_disabled_tools', []);
        abort_if(is_array($disabled) && in_array($action->tool, $disabled, true), 403, 'الأداة مقفولة من الإعدادات.');
        abort_if($this->registry->isCustomerTool($action->tool) && ! $this->registry->customerToolsEnabled(), 403, 'أدوات العملاء مقفولة من الإعدادات.');
        abort_if($this->registry->toolHiddenByFlags($action->tool), 403, 'الأداة مقفولة من الإعدادات.');
        $def = $this->registry->definitions()[$action->tool] ?? null;
        abort_unless($def && $actor->is_active && $actor->can('ai_agent.use') && $actor->can('ai_agent.execute') && $this->registry->actorHasToolPermissions($actor, $action->tool, $def), 403);
        abort_unless($action->conversation()->exists(), 409, 'المحادثة اتحذفت.');
        abort_unless(hash_equals($action->args_hash, $this->registry->hashArgs($action->args)), 409, 'بيانات الإجراء اتغيرت.');
        $mode = app(WhatsAppActorContext::class)->mode();
        if (in_array($mode, ['confirm', 'undo'], true) && $def) {
            $risk = (string) ($action->risk ?: $def['risk']);
            abort_if($this->registry->blockedOnWhatsapp($action->tool, $def['kind'], $risk), 403, 'الأداة دي مش متاحة من واتساب.');
        }
    }

    private function confirmLocked(User $actor, AiPendingAction $action, ?string $typed, ?array $selectedItems = null): ToolOutcome
    {
        abort_unless($action->user_id === $actor->id, 403);
        $this->authorizeTool($actor, $action);
        if ($action->status === 'executed') {
            return ToolOutcome::result(true, 'اتنفذ قبل كده.', $action->result ?? []);
        }
        abort_unless($action->status === 'pending', 409, 'الإجراء مش في حالة انتظار.');
        if ($action->expires_at->isPast()) {
            $action->forceFill(['status' => 'expired'])->save();
            abort(409, 'انتهت صلاحية كارت التأكيد.');
        }
        if (! hash_equals($action->args_hash, $this->registry->hashArgs($action->args))) {
            abort(409, 'بيانات الإجراء اتغيرت.');
        }
        abort_unless($this->settings->getBool('ai_enabled', false), 403, 'المساعد مقفول.');
        // re-check execute + original permission
        $defs = $this->registry->definitions();
        $def = $defs[$action->tool] ?? null;
        abort_unless($def && $actor->can('ai_agent.execute') && $this->registry->actorHasToolPermissions($actor, $action->tool, $def), 403);
        if ($action->risk === 'high') {
            $preview = $action->preview ?? [];
            [$expectedTyped, $typedHint] = ProposalBuilder::resolveTypedConfirmation($action->tool, $action->args ?? [], $preview);
            $typedInstruction = null;
            if (in_array($action->tool, ['approve_dealer_application', 'reject_dealer_application', 'suspend_customer', 'set_credit_limit'], true)) {
                $typedInstruction = 'اكتب آخر 4 أرقام من موبايل التاجر.';
            } elseif ($action->tool === 'adjust_customer_wallet') {
                $typedInstruction = 'اكتب آخر 4 أرقام من موبايل العميل.';
            } elseif ($typedHint !== null && $typedHint !== '') {
                $typedInstruction = 'اكتب '.$typedHint.': '.$expectedTyped;
            }
            // L-9: مطابقة متسامحة (trim + توحيد حالة) بدل الحرفية الصارمة.
            $norm = fn (?string $v): ?string => $v === null ? null : mb_strtolower(trim($v));
            if ($expectedTyped !== null && $typed !== null && $norm($typed) !== $norm($expectedTyped)) {
                abort(422, 'نص التأكيد مش مطابق.');
            }
            if ($expectedTyped !== null && ($typed === null || trim($typed) === '')) {
                abort(422, $typedInstruction ?? 'اكتب نص التأكيد المطلوب: '.$expectedTyped);
            }
        }
        $tool = $this->registry->toolInstance($action->tool);
        if ($tool instanceof ExecutesOutsideTransaction && $tool->executesOutsideTransaction($action)) {
            $action->forceFill(['status' => 'confirmed'])->save();

            return ToolOutcome::wrap('claimed');
        }
        $via = $this->via($action);
        try {
            $outcome = DB::transaction(function () use ($actor, $action, $via, $selectedItems) {
                $this->registry->lockTargets($action);

                return $this->registry->executeWrite($actor, $action, $via, $selectedItems);
            });
        } catch (UniqueConstraintViolationException) {
            // M14: 23505 بتصل برا الـ savepoint — الإجراء يتاخد failed برسالة
            // مفهومة بدل 500 والإجراء يتعلق pending للأبد.
            $message = 'قيمة مشتركة (كود فرع أو موقع/بريد) اتحجزت لحظة الحفظ. اطلب اقتراح جديد.';
            $action->forceFill(['status' => 'failed', 'result' => ['message' => $message, 'conflict_409' => true]])->save();
            $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
            abort(409, $message);
        } catch (BusinessException|ValidationException $e) {
            if ($e instanceof BusinessException && $e->status === 409) {
                $message = $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح. تحب أجهّز اقتراح جديد؟';
                $action->forceFill(['status' => 'failed', 'result' => ['message' => $message, 'conflict_409' => true]])->save();
                $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
                abort(409, $message);
            }
            if ($e instanceof BusinessException && $e->status === 403) {
                $message = $e->getMessage() ?: 'صلاحيتك على السجل ده اتغيرت بعد الاقتراح؛ اطلب اقتراحًا جديدًا.';
                $this->markFailed($action, $message);

                return ToolOutcome::result(false, $message);
            }
            // M-5: خطأ عمل مفهوم (تعطيل مرفوض/تحقق) يُحوَّل لفشل مسجَّل بدل
            // إلغاء الـ transaction الخارجية وبقاء الإجراء pending للأبد.
            $message = $e instanceof ValidationException
                ? collect($e->errors())->flatten()->implode(' ')
                : $e->getMessage();
            $message = trim((string) $message) !== '' ? $message : 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.';
            $action->forceFill(['status' => 'failed', 'result' => ['message' => $message]])->save();
            $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);

            return ToolOutcome::result(false, $message);
        } catch (AuthorizationException|ModelNotFoundException|RoleAlreadyExists $e) {
            $message = match (true) {
                $e instanceof AuthorizationException => 'صلاحيتك على السجل ده اتغيرت بعد الاقتراح؛ اطلب اقتراحًا جديدًا.',
                $e instanceof ModelNotFoundException => 'السجل المطلوب لم يعد موجودًا؛ اطلب اقتراحًا جديدًا.',
                default => trim((string) $e->getMessage()) !== '' ? $e->getMessage() : 'القيمة المطلوبة موجودة بالفعل؛ اطلب اقتراحًا جديدًا.',
            };
            $this->markFailed($action, $message);

            return ToolOutcome::result(false, $message);
        } catch (QueryException $e) {
            // M1: كتلة QueryException واحدة. قفل/deadlock → RetryableConflict
            // (409 قابل لإعادة المحاولة) من غير وسم failed (الـ savepoint
            // اتراجع ومفيش حالة اتغيرت). غير كده → failed برسالة مفهومة.
            if (in_array($e->errorInfo[0] ?? null, ['55P03', '40P01', '40001'], true) || $this->isRetryableLockFailure($e)) {
                throw new RetryableConflict('السجل مشغول بتعديل تاني؛ مفيش حاجة اتنفذت. جرّب التأكيد تاني بعد لحظة.', $e);
            }
            report($e);
            $message = match ($e->errorInfo[0] ?? null) {
                '23514' => 'البيانات مش مستوفية لشروط الحفظ (مثلاً بيانات قانونية ناقصة)؛ كمّلها واطلب اقتراح جديد.',
                '23503' => 'سجل مرتبط بالإجراء اتغير أو اتحذف؛ اطلب اقتراح جديد.',
                default => 'تعذّر التنفيذ بسبب خطأ في قاعدة البيانات؛ اطلب اقتراح جديد.',
            };
            $this->markFailed($action, $message);

            return ToolOutcome::result(false, $message);
        } catch (HttpExceptionInterface $e) {
            if ($e->getStatusCode() === 409) {
                // H2: التعارض القابل لإعادة المحاولة لا يوسم failed — مفيش
                // حالة اتغيرت، وإعادة التأكيد بعد لحظة كافية.
                if (! $e instanceof RetryableConflict) {
                    $action->forceFill(['status' => 'failed', 'result' => ['message' => $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح. تحب أجهّز اقتراح جديد؟', 'conflict_409' => true]])->save();
                    $this->event($action, 'result', $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح.', [['type' => 'result', 'ok' => false, 'message' => $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح.']]);
                }
            }
            throw $e;
        }

        return $this->finalizeAction($action, $outcome);
    }

    private function finalizeAction(AiPendingAction $action, ToolOutcome $outcome): ToolOutcome
    {
        $ok = $outcome->type === 'result';
        $storedResult = $outcome->data;
        unset($storedResult['generated_password']);
        // الأدوات قد تحفظ مراجع أنشأتها أثناء التنفيذ (مثل مسودة تحويل)
        // في expected_versions — حدّث النسخة قبل حساب حالة التراجع.
        $action->refresh();
        if ($ok && $this->registry->canUndo($action)) {
            $storedResult['undo_state'] = $this->registry->targetState($action);
        }
        $action->forceFill(['status' => $ok ? 'executed' : 'failed', 'result' => array_merge($storedResult, ['message' => $outcome->message]), 'executed_at' => $ok ? now() : null])->save();
        // Strip generated password from stored result? Keep only in response block, remove from result json
        $block = $outcome->uiBlock;
        if ($block) {
            $blocks = [$block];
            if ($ok && $this->registry->canUndo($action)) {
                $blocks[0]['undo_available_until'] = now()->addMinutes(15)->toIso8601String();
                $blocks[0]['undo_action_id'] = $action->id;
            }
        } else {
            $blocks = [['type' => 'result', 'ok' => $ok, 'message' => $outcome->message ?? '']];
            if ($ok && $this->registry->canUndo($action)) {
                $blocks[0]['undo_available_until'] = now()->addMinutes(15)->toIso8601String();
                $blocks[0]['undo_action_id'] = $action->id;
            }
        }
        $this->event($action, 'result', $outcome->message ?? '', $blocks, stripPassword: in_array($action->tool, ['create_staff_user', 'create_customer'], true));

        return ToolOutcome::wrap($outcome->type, $outcome->data, $blocks[0] ?? null, $outcome->message);
    }

    public function cancel(User $actor, AiPendingAction $action): AiPendingAction
    {
        abort_unless($action->user_id === $actor->id, 403);

        return DB::transaction(function () use ($actor, $action): AiPendingAction {
            $this->lockForAction($action->tool);
            $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
            if ($locked->status === 'pending') {
                $locked->forceFill(['status' => 'cancelled'])->save();
                if ($locked->tool === 'bulk_actions') {
                    // M10: الإجراءات الفرعية بتنقفل مع الخبّة الجماعية.
                    AiPendingAction::query()->where('user_id', $actor->id)->where('conversation_id', $locked->conversation_id)->whereIn('id', $locked->args['action_ids'])->whereIn('status', ['pending', 'bulk_child'])->update(['status' => 'cancelled']);
                }
                $this->event($locked, 'result', 'تم إلغاء الإجراء '.$locked->id, [['type' => 'result', 'ok' => true, 'message' => 'تم إلغاء الإجراء.']]);
            }

            return $locked;
        });
    }

    public function undo(User $actor, AiPendingAction $action): ToolOutcome
    {
        // L-6: فحص الملكية قبل قفل الصفوف — لا قفل لصفوف إجراء لا يملكه المستخدم.
        abort_unless($action->user_id === $actor->id, 403);

        return DB::transaction(function () use ($actor, $action) {
            $this->lockForAction($action->tool);
            $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
            abort_unless($locked->user_id === $actor->id, 403);
            $this->registry->lockTargets($locked);

            return $this->undoLocked($actor, $locked);
        });
    }

    private function undoLocked(User $actor, AiPendingAction $action): ToolOutcome
    {
        abort_unless($action->user_id === $actor->id, 403);
        $this->authorizeTool($actor, $action);
        abort_unless($this->registry->canUndo($action), 409);
        abort_unless(isset($action->result['undo_state']) && hash_equals($action->result['undo_state'], $this->registry->targetState($action)), 409, 'السجل اتعدل بعد التنفيذ؛ التراجع مش آمن.');
        abort_unless($action->status === 'executed' && $action->executed_at && $action->executed_at->copy()->addMinutes(15)->isFuture(), 409, 'التراجع مش متاح.');
        abort_unless($actor->can('ai_agent.execute'), 403);
        $via = $this->via($action);
        try {
            $outcome = DB::transaction(fn () => $this->registry->executeUndo($actor, $action, $via));
        } catch (BusinessException $e) {
            if ($e->status === 409) {
                $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
                abort(409, $e->getMessage());
            }

            return ToolOutcome::result(false, $e->getMessage() ?: 'فشل التراجع.');
        } catch (HttpExceptionInterface $e) {
            if ($e->getStatusCode() === 409) {
                $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
                throw $e;
            } throw $e;
        }
        if ($outcome->type === 'result') {
            $action->forceFill(['status' => 'undone'])->save();
            $this->event($action, 'result', 'تم التراجع.', [['type' => 'result', 'ok' => true, 'message' => 'تم التراجع.']]);
        }

        return $outcome;
    }

    private function isRetryableLockFailure(QueryException $e): bool
    {
        return in_array((string) $e->getCode(), ['55P03', '40P01'], true);
    }

    /**
     * M-3: وسم الإجراء failed برسالة واضحة + حدث نتيجة — بدل بقائه
     * pending للأبد بعد استثناء غير مصنّف.
     */
    private function markFailed(AiPendingAction $action, string $message): void
    {
        $action->forceFill(['status' => 'failed', 'result' => ['message' => $message]])->save();
        $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
    }

    /** @return array{channel:string,conversation_id:mixed,action_id:mixed,source:string} */
    private function via(AiPendingAction $action): array
    {
        return [
            'channel' => 'ai',
            'conversation_id' => $action->conversation_id,
            'action_id' => $action->id,
            'source' => (string) ($action->conversation()->value('channel') ?: 'web'),
        ];
    }

    private function event(AiPendingAction $action, string $kind, string $text, array $blocks, bool $stripPassword = false): void
    {
        if ($stripPassword) {
            // L8: لا تعتمد على regex فوق صياغة عربية قد تتغير — المؤقتة
            // تُعرض مرة واحدة في رد التأكيد فقط، والمخزّن نص ثابت.
            $created = $action->tool === 'create_customer' ? 'العميل' : 'الموظف';
            $text = "تم إنشاء {$created} (الباسورد ظهر للأدمن مرة واحدة).";
            $blocks = array_map(function ($b) use ($created) {
                if (isset($b['message'])) {
                    $b['message'] = "تم إنشاء {$created}.";
                }
                if (isset($b['generated_password'])) {
                    unset($b['generated_password']);
                }

                return $b;
            }, $blocks);
        }
        AiMessage::create(['conversation_id' => $action->conversation_id, 'role' => 'event', 'content' => $text, 'ui_blocks' => $blocks]);
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Enums\OrderStatus;
use App\Enums\ReturnStatus;
use App\Enums\StockBucket;
use App\Enums\StockMovementType;
use App\Enums\WholesalePaymentNoticeStatus;
use App\Events\OrderCreated;
use App\Exceptions\BusinessException;
use App\Models\Cart;
use App\Models\City;
use App\Models\Coupon;
use App\Models\CouponUsage;
use App\Models\Customer;
use App\Models\CustomerWalletTransaction;
use App\Models\Order;
use App\Models\Product;
use App\Models\ProductVariant;
use App\Models\ReturnRequest;
use App\Models\StockMovement;
use App\Models\User;
use App\Models\WholesalePaymentNotice;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\RateLimiter;

/**
 * Handles order placement, status transition lifecycle, and associated inventory effects.
 *
 * Coordinates cart checkout, atomic stock reservation, coupon redemption,
 * and ledger updates across order state transitions (confirmed, shipped, cancelled, returned).
 */
class OrderService
{
    /** Permitted state machine transitions for order statuses. */
    private const TRANSITIONS = [
        'pending' => ['confirmed', 'cancelled'],
        'confirmed' => ['processing', 'shipped', 'cancelled'],
        'processing' => ['shipped', 'cancelled'],
        'shipped' => ['delivered', 'returned'],
        'delivered' => ['returned'],
        'cancelled' => [],
        'returned' => [],
    ];

    public function __construct(
        protected OrderAllocationService $allocationService,
        protected CartService $cartService,
        protected CouponService $couponService,
        protected SettingService $settings,
        protected InventoryService $inventoryService,
        protected ShippingQuoteService $shippingQuote,
    ) {}

    /**
     * Converts a customer or guest cart into a pending order with reserved inventory.
     *
     * @param  array{recipient_name?: string|null, recipient_phone?: string|null, recipient_email?: string|null, city_id?: int|null, shipping_address_line?: string|null, shipping_notes?: string|null, payment_method?: string|null, channel?: string, idempotency_key?: string|null, expected_total?: float|int|string|null}  $data
     */
    public function createFromCart(Cart $cart, array $data, ?Customer $customer = null): Order
    {
        // Idempotency key scoped to authenticated customer or normalized guest phone to prevent replay attacks.
        $idempotencyKey = isset($data['idempotency_key']) && is_string($data['idempotency_key']) && $data['idempotency_key'] !== ''
            ? mb_substr($data['idempotency_key'], 0, 191)
            : null;

        $guestPhone = $data['recipient_phone'] ?? $customer?->phone;
        $guestPhoneNormalized = is_string($guestPhone) && trim($guestPhone) !== ''
            ? Customer::normalizePhone($guestPhone)
            : null;
        // Require at least one digit in guest phone to prevent empty string collisions in guest scope.
        if ($customer === null && $guestPhoneNormalized !== null
            && preg_match('/\d/', $guestPhoneNormalized) !== 1) {
            throw new BusinessException('رقم هاتف صالح مطلوب لإتمام الشراء كزائر.');
        }
        $idempotencyScope = $customer !== null
            ? 'customer:'.$customer->id
            : ($guestPhoneNormalized !== null ? 'guest:'.$guestPhoneNormalized : null);

        if ($idempotencyKey !== null && $idempotencyScope !== null) {
            $existing = Order::query()
                ->where('idempotency_key', $idempotencyKey)
                ->where('idempotency_scope', $idempotencyScope)
                ->first();
            if ($existing !== null) {
                return $this->assertMatchingIdempotentReplay($existing, $data, $cart);
            }
        }

        // Enforce daily checkout quota per phone number without deducting budget on validation errors.
        $phoneDayKey = $customer === null && $guestPhoneNormalized !== null && preg_match('/\d/', $guestPhoneNormalized) === 1
            ? 'checkout-phone-day:'.hash('sha256', $guestPhoneNormalized)
            : null;
        if ($phoneDayKey !== null && RateLimiter::tooManyAttempts($phoneDayKey, (int) config('auth.customer_limits.checkout_phone_day', 20))) {
            throw new BusinessException('تجاوزت عدد الطلبات اليومية المسموحة لهذا الرقم؛ حاول غدًا.', [], 429);
        }

        $created = DB::transaction(function () use ($cart, $data, $customer, $idempotencyKey, $idempotencyScope, $guestPhoneNormalized, $phoneDayKey): Order {
            // Transaction-level advisory lock serializes concurrent checkouts with the same idempotency key.
            if ($idempotencyKey !== null && $idempotencyScope !== null) {
                DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', ['order-idem:'.$idempotencyScope.':'.$idempotencyKey]);
                $existing = Order::query()
                    ->where('idempotency_key', $idempotencyKey)
                    ->where('idempotency_scope', $idempotencyScope)
                    ->first();
                if ($existing !== null) {
                    return $this->assertMatchingIdempotentReplay($existing, $data, $cart);
                }
            }

            // Lock cart row and fetch fresh items so concurrent checkouts cannot double-process the same cart.
            $cart = Cart::query()->whereKey($cart->id)->lockForUpdate()->firstOrFail();
            $cart->load('items');
            if ($cart->items->isEmpty()) {
                throw new BusinessException('السلة فارغة؛ لا يمكن إنشاء طلب.');
            }

            foreach ($cart->items as $item) {
                $this->cartService->assertWholeQuantity((float) $item->qty);
            }
            $lines = $this->cartService->pricedLines($cart, $customer);
            foreach ($lines as $line) {
                if ($line['unit_price'] === null) {
                    throw new BusinessException("الصنف ({$line['variant']->sku}) غير مُسعَّر؛ لا يمكن إتمام الطلب.");
                }
                // Reject zero-value lines resulting from extreme rounding or micro-pricing anomalies.
                if ($line['line_total'] <= 0) {
                    throw new BusinessException("قيمة الصنف ({$line['variant']->sku}) صفر؛ راجع الكمية أو السعر.");
                }
            }

            // Enforce maximum quantity caps per line and pending orders cap to prevent inventory hoarding.
            $isWholesale = $this->isWholesaleApproved($customer);
            if (! $isWholesale) {
                $lineCap = $customer === null
                    ? (float) config('store.guest_max_line_qty', 10)
                    : (float) config('store.retail_max_line_qty', 50);
                if ($lineCap > 0) {
                    foreach ($lines as $line) {
                        if ((float) $line['qty'] > $lineCap) {
                            throw new BusinessException($customer === null
                                ? "سقف كمية البند الواحد للزوار ({$lineCap}) — سجّل الدخول للكميات الأكبر."
                                : "سقف كمية البند الواحد ({$lineCap}) — للكميات الأكبر تواصل مع مسار الجملة.");
                        }
                    }
                }
            }

            if ($customer === null) {
                $pendingCap = (int) config('store.guest_pending_orders_cap', 3);
                if ($pendingCap > 0 && $guestPhoneNormalized !== null) {
                    DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', ['pending-guest:'.$guestPhoneNormalized]);
                    $pendingForPhone = Order::query()
                        ->whereNull('customer_id')
                        ->where('status', OrderStatus::Pending)
                        ->where('guest_phone_normalized', $guestPhoneNormalized)
                        ->count();
                    if ($pendingForPhone >= $pendingCap) {
                        throw new BusinessException('لديك طلبات معلّقة كثيرة على هذا الرقم؛ أكملها أو ألغِها قبل طلب جديد.');
                    }
                }
            } elseif (! $isWholesale) {
                $pendingCap = (int) config('store.customer_pending_orders_cap', 5);
                if ($pendingCap > 0) {
                    DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', ['pending-customer:'.$customer->id]);
                    $pendingForCustomer = Order::query()
                        ->where('customer_id', $customer->id)
                        ->where('status', OrderStatus::Pending)
                        ->count();
                    if ($pendingForCustomer >= $pendingCap) {
                        throw new BusinessException('لديك طلبات معلّقة كثيرة؛ أكملها أو ألغِها قبل طلب جديد.');
                    }
                }
            }

            // Re-verify product availability and purchasability at checkout time.
            $this->cartService->assertLinesAvailable($lines);
            $this->cartService->assertLinesPurchasable($lines);
            $totals = $this->cartService->totals($cart, $customer, $lines);
            $subtotal = $totals['subtotal'];
            $pricingDiscount = $totals['pricing_discount'];

            // Strict coupon validation and rate-limiting at redemption time.
            $couponDiscount = 0.0;
            $couponId = null;
            $couponCode = null;
            $coupon = null;
            if ($cart->coupon_id !== null) {
                try {
                    $coupon = $this->couponService->redeemableById(
                        (int) $cart->coupon_id,
                        $totals['items_total'],
                        $customer,
                        $customer === null ? ($data['recipient_phone'] ?? null) : null,
                    );
                } catch (BusinessException $e) {
                    // Tag coupon invalidation so the front-end can prompt coupon removal.
                    throw new BusinessException($e->getMessage(), $e->errors, $e->status, 'coupon_invalid');
                }
                $this->couponService->enforceRateLimit($coupon, 'redeem');
                $couponDiscount = $this->couponService->discountFor($coupon, $totals['items_total']);
                $couponId = $coupon->id;
                $couponCode = $coupon->code;
            }
            $discountAmount = round($pricingDiscount + $couponDiscount, 2);

            // Calculate shipping quote and COD surcharge based on destination city and active rates.
            $city = null;
            $shippingCost = 0.0;
            $codFee = 0.0;
            if (! empty($data['city_id'])) {
                $city = City::query()->where('is_active', true)->find((int) $data['city_id']);
                if ($city === null) {
                    throw new BusinessException('مدينة التوصيل غير متاحة.');
                }
                $quote = $this->shippingQuote->quoteForCity(
                    $city->id,
                    $totals['items_total'] - $couponDiscount,
                    ($data['payment_method'] ?? 'cod') === 'cod',
                );
                $shippingCost = $quote['cost'];
                $codFee = $quote['cod_fee'];
            }
            $waivedShipping = 0.0;
            if ($coupon !== null && $coupon->type === 'free_shipping' && $shippingCost > 0) {
                $waivedShipping = $shippingCost;
                $shippingCost = 0.0;
            }

            // Apply sales tax from settings when enabled and not already included in catalog prices.
            $taxAmount = 0.0;
            $taxRate = 0.0;
            if ($this->settings->getBool('tax_enabled') && ! $this->settings->getBool('prices_include_tax')) {
                $taxRate = (float) $this->settings->get('default_tax_rate', 0);
                $taxAmount = round(($subtotal - $discountAmount) * $taxRate / 100, 2);
            }

            $grandTotal = round(($subtotal - $discountAmount) + $shippingCost + $codFee + $taxAmount, 2);

            // Reject credit orders upfront if projected outstanding balance exceeds the approved credit limit.
            if (($data['payment_method'] ?? null) === 'credit' && $customer !== null) {
                Customer::query()->whereKey($customer->id)->lockForUpdate()->first();
                $outstanding = app(WholesalePaymentNoticeService::class)->outstandingBalance($customer->fresh());
                if ($outstanding + $grandTotal > (float) $customer->credit_limit) {
                    throw new BusinessException(
                        'إجمالي الطلب يتجاوز حد الائتمان المتاح.',
                        [],
                        422,
                        'credit_limit_exceeded',
                    );
                }
            }

            // Reject checkout if grand total drifted since cart preview (e.g. price update or expired promo).
            if ($this->expectedTotalChanged($data, $grandTotal)) {
                throw new BusinessException(
                    'تغيّر إجمالي الطلب منذ عرضه. راجع السلة ثم أعد المحاولة.',
                    [], 422, 'price_changed',
                );
            }

            $order = Order::create([
                'order_number' => $this->settings->generateNextNumber('order'),
                'idempotency_key' => $idempotencyKey,
                'idempotency_scope' => $idempotencyScope,
                'channel' => $data['channel'] ?? 'store',
                'customer_id' => $customer?->id,
                'guest_name' => $data['recipient_name'] ?? $customer?->name,
                'guest_phone' => $data['recipient_phone'] ?? $customer?->phone,
                'guest_phone_normalized' => $guestPhoneNormalized,
                'guest_email' => $data['recipient_email'] ?? $customer?->email,
                'city_id' => $city?->id,
                'shipping_address_line' => $data['shipping_address_line'] ?? null,
                'shipping_notes' => $data['shipping_notes'] ?? null,
                'status' => OrderStatus::Pending,
                'payment_method' => $data['payment_method'] ?? 'cod',
                'payment_status' => 'unpaid',
                'subtotal' => $subtotal,
                'discount_amount' => $discountAmount,
                'coupon_id' => $couponId,
                'coupon_code' => $couponCode,
                'shipping_cost' => $shippingCost,
                'cod_fee' => $codFee,
                'tax_amount' => $taxAmount,
                'grand_total' => $grandTotal,
            ]);

            // Distribute tax and coupon discounts across line items using the largest remainder method.
            $weights = array_map(fn (array $line): float => (float) $line['line_total'], $lines);
            $taxShares = $this->distributeLargestRemainder($taxAmount, $weights);
            $couponShares = $this->distributeLargestRemainder($couponDiscount, $weights);
            foreach ($lines as $i => $line) {
                $order->items()->create([
                    'product_variant_id' => $line['variant']->id,
                    'product_name_snapshot' => $line['variant']->product?->name_ar ?? '',
                    'sku_snapshot' => $line['variant']->sku,
                    'qty' => $line['qty'],
                    'unit_price' => $line['unit_price'],
                    'discount_amount' => round($line['line_discount'] + $couponShares[$i], 2),
                    'tax_amount' => $taxShares[$i],
                    'line_total' => $line['line_total'],
                ]);
            }

            // Reserve stock immediately under pessimistic locks so the last unit cannot be oversold.
            $order->load('items');
            $this->allocationService->allocate($order, performedBy: $this->inventoryActorId($customer));
            $order->refresh();

            // Free shipping coupon without actual shipping cost does not consume user redemption limit.
            if ($coupon !== null
                && ! ($coupon->type === 'free_shipping' && $waivedShipping <= 0)) {
                try {
                    $this->couponService->recordUsage(
                        $coupon,
                        $order,
                        $customer,
                        $coupon->type === 'free_shipping' ? $waivedShipping : $couponDiscount,
                    );
                } catch (BusinessException $e) {
                    throw new BusinessException($e->getMessage(), $e->errors, $e->status, 'coupon_invalid');
                }
            }

            if (($data['payment_method'] ?? 'cod') === 'wallet') {
                if ($customer === null || $customer->fresh()->status !== CustomerStatus::Approved) {
                    throw new BusinessException('الدفع بالمحفظة يتطلب حساب عميل نشطًا.');
                }
                app(WalletService::class)->record($customer->id, -$grandTotal, 'checkout_payment', 'order', $order->id);
                $order->update(['payment_status' => 'paid']);
            }

            // Automatically persist customer shipping address for streamlined future checkouts.
            if ($customer !== null && $city !== null && ! empty($data['shipping_address_line'])) {
                $line = mb_substr(trim((string) $data['shipping_address_line']), 0, 500);
                $addressQuery = $customer->addresses();
                if ($line !== '' && ! (clone $addressQuery)->where('city_id', $city->id)->where('address_line', $line)->exists()) {
                    $addressQuery->create([
                        'city_id' => $city->id,
                        'address_line' => $line,
                        'is_default' => ! (clone $addressQuery)->where('is_default', true)->exists(),
                    ]);
                }
            }

            // Record initial pending status transition in history log.
            $order->statusHistories()->create([
                'from_status' => null,
                'to_status' => OrderStatus::Pending,
                'changed_by_type' => $customer?->getMorphClass(),
                'changed_by_id' => $customer?->getKey(),
                'notes' => 'تم إنشاء الطلب من السلة',
            ]);

            // Remove only ordered items from cart to preserve items concurrently added in other tabs.
            $orderedItemIds = array_values(array_unique(array_map(
                fn (array $line): int => (int) $line['item_id'],
                $lines,
            )));
            if ($orderedItemIds !== []) {
                $cart->items()->whereIn('id', $orderedItemIds)->delete();
            }
            $cart->update(['coupon_id' => null]);

            $created = $order->fresh(['items', 'statusHistories']);
            OrderCreated::dispatch($created);

            if ($phoneDayKey !== null) {
                DB::afterCommit(fn () => RateLimiter::hit($phoneDayKey, 24 * 3600));
            }

            return $created;
        });

        return $created;
    }

    /**
     * Replays an idempotent checkout only when the new request still describes the stored order.
     */
    private function assertMatchingIdempotentReplay(Order $existing, array $data, Cart $cart): Order
    {
        $existing->loadMissing('items');
        $cart->loadMissing('items');
        $mismatched = false;

        if (array_key_exists('payment_method', $data) && (string) $data['payment_method'] !== (string) $existing->payment_method) {
            $mismatched = true;
        }
        if (array_key_exists('city_id', $data) && (int) $data['city_id'] !== (int) $existing->city_id) {
            $mismatched = true;
        }
        if (array_key_exists('shipping_address_line', $data)
            && trim((string) $data['shipping_address_line']) !== trim((string) $existing->shipping_address_line)) {
            $mismatched = true;
        }
        if (array_key_exists('recipient_name', $data)
            && trim((string) $data['recipient_name']) !== trim((string) $existing->guest_name)) {
            $mismatched = true;
        }
        if (array_key_exists('recipient_phone', $data)) {
            $incoming = Customer::normalizePhone((string) $data['recipient_phone']);
            $stored = $existing->guest_phone_normalized
                ?? ($existing->guest_phone !== null ? Customer::normalizePhone((string) $existing->guest_phone) : '');
            if ($incoming !== $stored) {
                $mismatched = true;
            }
        }
        if ($this->expectedTotalChanged($data, (float) $existing->grand_total)) {
            $mismatched = true;
        }

        if ($cart->items->isNotEmpty()) {
            $cartSignature = $cart->items
                ->map(fn ($item): string => $item->product_variant_id.':'.(int) $item->qty)
                ->sort()->values()->all();
            $orderSignature = $existing->items
                ->map(fn ($item): string => $item->product_variant_id.':'.(int) $item->qty)
                ->sort()->values()->all();
            if ($cartSignature !== $orderSignature) {
                $mismatched = true;
            }
        }

        if ($mismatched) {
            throw new BusinessException(
                'هذا المفتاح مستخدم لطلب ببيانات مختلفة.',
                [],
                409,
                'idempotency_conflict',
            );
        }

        return $existing->load('items');
    }

    private function expectedTotalChanged(array $data, float $actualTotal): bool
    {
        return isset($data['expected_total']) && is_numeric($data['expected_total'])
            && round((float) $data['expected_total'], 2) !== $actualTotal;
    }

    /**
     * Executes an order status transition and triggers corresponding inventory and payment side-effects.
     *
     * @param  array<int, OrderStatus>|null  $expectedFrom  Expected previous statuses to prevent race conditions.
     * @param  bool  $returnEffects  Whether to generate automatic stock and refund side effects for returns.
     * @param  bool  $allowNoticesLoss  Allows cancelling credit orders with approved wholesale payment notices.
     */
    public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null, ?array $expectedFrom = null, bool $returnEffects = true, bool $allowNoticesLoss = false): Order
    {
        $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);

        return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom, $returnEffects, $allowNoticesLoss): Order {
            // Lock order row to serialize status transitions and guard against stale client snapshots.
            $order = Order::query()->lockForUpdate()->findOrFail($order->id);
            $from = $order->status;

            if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
                throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
            }

            if ($from === $to) {
                return $order;
            }

            if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
                throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
            }

            $actorId = $this->inventoryActorId($actor);

            if ($to === OrderStatus::Returned && $returnEffects && $order->channel === 'pos') {
                throw new BusinessException('استخدم مرتجع POS لتسوية المخزون والنقدية معًا.');
            }

            if ($to === OrderStatus::Returned && $returnEffects
                && ReturnRequest::query()->where('order_id', $order->id)->whereNotIn('status', [
                    ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value,
                ])->exists()) {
                throw new BusinessException('للطلب مرتجعات قائمة؛ أكمل الاستلام والاسترداد من إدارة المرتجعات لمنع تكرار المخزون.');
            }

            // Prevent silent cancellation of credit orders that hold approved wholesale treasury notices.
            if ($to === OrderStatus::Cancelled && ! $allowNoticesLoss
                && $order->payment_method === 'credit'
                && WholesalePaymentNotice::query()->where('order_id', $order->id)
                    ->where('status', WholesalePaymentNoticeStatus::Approved->value)->exists()) {
                throw new BusinessException('للطلب الآجل إشعارات سداد معتمدة مقيدة في الخزينة؛ سوِّها أولًا (رد أو تحويلها لائتمان حر) قبل الإلغاء.');
            }

            $extraNote = null;
            if ($to === OrderStatus::Shipped) {
                $this->shipOrder($order, $actorId);
            } elseif ($to === OrderStatus::Cancelled
                && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
                // Stock is reserved from creation time, so release reservations on cancellation.
                $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
            } elseif ($to === OrderStatus::Returned
                && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)
                && $returnEffects) {
                // Reverse sales in stock ledger unless handled by the warehouse RMA intake process.
                if (! $this->returnSalesToStock($order, $actorId)) {
                    $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
                }
            }

            if ($to === OrderStatus::Cancelled) {
                // Restore coupon usage quota upon order cancellation.
                $this->reverseCouponUsage($order);
                if ($order->payment_status === 'paid') {
                    $order->update(['requires_refund' => true]);
                }
            }

            // Flag paid returned order for refund processing.
            if ($to === OrderStatus::Returned && $order->payment_status === 'paid' && $returnEffects) {
                $order->update(['requires_refund' => true]);
            }

            if ($order->payment_method === 'wallet' && $order->payment_status === 'paid'
                && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
                $payment = CustomerWalletTransaction::query()->where('reference_type', 'order')->where('reference_id', $order->id)
                    ->where('type', 'checkout_payment')->first();
                if ($payment !== null) {
                    app(WalletService::class)->record($payment->customer_id, -(float) $payment->amount,
                        'order_reversal', 'order', $order->id, $actorId);
                    $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
                }
            }

            $order->update(['status' => $to]);

            // Auto-settle COD payment status upon delivery.
            if ($to === OrderStatus::Delivered
                && $order->payment_method === 'cod'
                && $order->payment_status !== 'paid') {
                $order->update(['payment_status' => 'paid']);
            }

            // Truncate notes to fit the varchar(500) database column limit.
            $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;

            $order->statusHistories()->create([
                'from_status' => $from,
                'to_status' => $to,
                'changed_by_type' => $actor?->getMorphClass(),
                'changed_by_id' => $actor?->getKey(),
                'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
            ]);

            // Trigger item allocation if the order transitioned to confirmed without full allocation.
            if ($to === OrderStatus::Confirmed && ! $this->isAllocated($order)) {
                $this->allocationService->allocate($order, performedBy: $actorId);
            }

            return $order->fresh(['items', 'statusHistories']);
        });
    }

    /**
     * Checks whether all order items have been allocated to fulfillment branches.
     */
    private function isAllocated(Order $order): bool
    {
        if ($order->allocated_branch_id !== null) {
            return true;
        }

        $distribution = $order->items()
            ->selectRaw('COUNT(*) AS total, COUNT(allocated_branch_id) AS allocated')
            ->first();

        if ($distribution === null || (int) $distribution->total === 0) {
            return false;
        }

        return (int) $distribution->total === (int) $distribution->allocated;
    }

    /**
     * Checks if customer has approved wholesale/distributor status exempt from retail limits.
     */
    private function isWholesaleApproved(?Customer $customer): bool
    {
        return $customer !== null
            && $customer->status === CustomerStatus::Approved
            && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
    }

    /**
     * Distributes a total currency amount across weights using Hare-Niemeyer (largest remainder) algorithm.
     *
     * @param  array<int, float>  $weights
     * @return array<int, float>
     */
    private function distributeLargestRemainder(float $total, array $weights): array
    {
        return ProportionalDistribution::distribute($total, $weights);
    }

    /**
     * Releases reservations and records sale stock movements for all items in the order.
     */
    private function shipOrder(Order $order, ?int $actorId): void
    {
        $net = $this->netReservations($order);
        if ($net->isEmpty()) {
            throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
        }

        $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
            'product_variant_id' => $row['product_variant_id'],
            'branch_id' => $row['branch_id'],
            'location_id' => $row['location_id'],
        ])->all());

        $costs = ProductVariant::withTrashed()->whereIn('id', $net->pluck('product_variant_id'))->pluck('cost_price', 'id');
        foreach ($net as $row) {
            $base = [
                'product_variant_id' => $row['product_variant_id'],
                'branch_id' => $row['branch_id'],
                'location_id' => $row['location_id'],
                'reference_type' => Order::class,
                'reference_id' => $order->id,
                'created_by' => $actorId,
            ];
            $level = $levels->get($this->inventoryService->levelKey($row));
            $this->inventoryService->recordMovement([...$base,
                'type' => StockMovementType::ReleaseReserve,
                'affected_bucket' => StockBucket::Reserved,
                'quantity' => -1 * (float) $row['net_qty'],
                'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
            ], $level);
            $this->inventoryService->recordMovement([...$base,
                'type' => StockMovementType::Sale,
                'unit_cost' => $costs[$row['product_variant_id']] ?? null,
                'affected_bucket' => StockBucket::OnHand,
                'quantity' => -1 * (float) $row['net_qty'],
                'notes' => "بيع عند شحن الطلب {$order->order_number}",
            ], $level);
        }

        foreach ($order->items as $item) {
            $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
        }
    }

    /**
     * Releases active stock reservations for cancelled orders back into available inventory.
     */
    private function releaseReservations(Order $order, ?int $actorId, string $reason): void
    {
        $net = $this->netReservations($order);
        if ($net->isEmpty()) {
            return;
        }

        $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
            'product_variant_id' => $row['product_variant_id'],
            'branch_id' => $row['branch_id'],
            'location_id' => $row['location_id'],
        ])->all());

        foreach ($net as $row) {
            $this->inventoryService->recordMovement([
                'product_variant_id' => $row['product_variant_id'],
                'branch_id' => $row['branch_id'],
                'location_id' => $row['location_id'],
                'type' => StockMovementType::ReleaseReserve,
                'affected_bucket' => StockBucket::Reserved,
                'quantity' => -1 * (float) $row['net_qty'],
                'reference_type' => Order::class,
                'reference_id' => $order->id,
                'created_by' => $actorId,
                'notes' => "{$reason} {$order->order_number}",
            ], $levels->get($this->inventoryService->levelKey($row)));
        }
    }

    /**
     * Restores delivered/shipped goods to on-hand inventory via SaleReturn stock movements.
     */
    private function returnSalesToStock(Order $order, ?int $actorId): bool
    {
        $net = StockMovement::query()
            ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
            ->where('reference_id', $order->id)
            ->whereIn('type', [StockMovementType::Sale->value, StockMovementType::SaleReturn->value])
            ->groupBy('product_variant_id', 'branch_id', 'location_id')
            ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty, MAX(unit_cost) FILTER (WHERE type = \'sale\') AS sale_unit_cost')
            ->get()
            // Negative net represents un-returned sales (Sale is negative, SaleReturn is positive).
            ->map(fn ($row): array => [
                'product_variant_id' => (int) $row->product_variant_id,
                'branch_id' => (int) $row->branch_id,
                'location_id' => $row->location_id === null ? null : (int) $row->location_id,
                'net_qty' => (float) $row->net_qty,
                'sale_unit_cost' => $row->sale_unit_cost,
            ])
            ->filter(fn (array $row): bool => $row['net_qty'] < -1e-9)
            ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
            ->values();

        if ($net->isEmpty()) {
            return false;
        }

        $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
            'product_variant_id' => $row['product_variant_id'],
            'branch_id' => $row['branch_id'],
            'location_id' => $row['location_id'],
        ])->all());

        foreach ($net as $row) {
            $this->inventoryService->recordMovement([
                'product_variant_id' => $row['product_variant_id'],
                'branch_id' => $row['branch_id'],
                'location_id' => $row['location_id'],
                'type' => StockMovementType::SaleReturn,
                'affected_bucket' => StockBucket::OnHand,
                'quantity' => -1 * (float) $row['net_qty'],
                'unit_cost' => $row['sale_unit_cost'],
                'reference_type' => Order::class,
                'reference_id' => $order->id,
                'created_by' => $actorId,
                'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
            ], $levels->get($this->inventoryService->levelKey($row)));
        }

        foreach ($order->items as $item) {
            if ($item->variant?->product_id) {
                Product::query()->whereKey($item->variant->product_id)
                    ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round((float) $item->qty).', 0)')]);
            }
        }

        return true;
    }

    /**
     * Computes net active stock reservations per variant/location for an order.
     *
     * @return Collection<int, array{product_variant_id: int, branch_id: int, location_id: int|null, net_qty: float}>
     */
    private function netReservations(Order $order): Collection
    {
        return StockMovement::query()
            ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
            ->where('reference_id', $order->id)
            ->whereIn('type', [StockMovementType::Reserve->value, StockMovementType::ReleaseReserve->value])
            ->groupBy('product_variant_id', 'branch_id', 'location_id')
            ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty')
            ->get()
            ->map(fn ($row): array => [
                'product_variant_id' => (int) $row->product_variant_id,
                'branch_id' => (int) $row->branch_id,
                'location_id' => $row->location_id === null ? null : (int) $row->location_id,
                'net_qty' => (float) $row->net_qty,
            ])
            ->filter(fn (array $row): bool => $row['net_qty'] > 1e-9)
            ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
            ->values();
    }

    /**
     * Reverses recorded coupon usage and decrements used_count on order cancellation.
     */
    private function reverseCouponUsage(Order $order): void
    {
        foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
            Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
            $usage->delete();
        }
    }

    /**
     * Retrieves original stock reserve movements associated with an order.
     */
    private function reserveMovements(Order $order): Collection
    {
        return StockMovement::query()
            ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
            ->where('reference_id', $order->id)
            ->where('type', StockMovementType::Reserve)
            ->orderBy('id')
            ->get();
    }

    // Instance-level cache avoids cross-test/Octane bleed of static properties.
    private ?int $systemActorId = null;

    private bool $systemActorResolved = false;

    /**
     * Resolves the user identity responsible for stock ledger entries.
     *
     * Falls back to dedicated system user for automated actions (webhooks, guest checkout).
     */
    private function inventoryActorId(?Model $actor): ?int
    {
        if ($actor instanceof User) {
            return (int) $actor->getKey();
        }

        if (! $this->systemActorResolved) {
            $this->systemActorResolved = true;
            $systemId = User::query()
                ->where('is_system', true)
                ->value('id');
            $this->systemActorId = $systemId !== null ? (int) $systemId : null;
        }
        if ($this->systemActorId !== null) {
            return $this->systemActorId;
        }

        throw new \LogicException('The System audit identity is missing; run the system-user migration before processing automated order effects.');
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Exceptions\BusinessException;
use App\Http\Requests\Api\V1\Admin\UpdateSettingsRequest;
use App\Models\Setting;
use Brick\Math\BigDecimal;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use InvalidArgumentException;
use JsonException;

/**
 * Central settings and document numbering configuration service.
 *
 * Caches static system settings and manages atomic generation of sequential document identifiers
 * (orders, transfers, movements, invoices) via PostgreSQL sequences and optimistic concurrency locking.
 */
class SettingService
{
    /** @var array<string, array{0: string, 1: int}> Cached numbering prefix and padding config per request to avoid repeated lookups. */
    private array $numberingConfig = [];

    private ?array $transactionSnapshot = null;

    private bool $uncommittedSettings = false;

    /** @var array<string, mixed>|null Per-request in-memory cache to avoid repeated serialization and cache lookups. */
    private ?array $requestCache = null;

    public function resetReadSnapshot(bool $transactionBoundary = false): void
    {
        $this->transactionSnapshot = null;
        if ($transactionBoundary) {
            $this->uncommittedSettings = false;
            $this->requestCache = null;
        }
    }

    /** @var array<string, mixed> */
    private const DEFAULTS = [
        'ai_catalog_tools_enabled' => false,
        'ai_catalog_vision_enabled' => false,
        'ai_catalog_bulk_price_max_items' => 200,
        'ai_catalog_copywriting_enabled' => false,
        'ai_inventory_tools_enabled' => false,
        'ai_inventory_vision_enabled' => false,
        'ai_inventory_share_cost_with_model' => false,
        'ai_inventory_high_risk_value' => 50000,
        'ai_inventory_proactive_enabled' => false,
        'ai_pricing_tools_enabled' => false,
        'ai_promotions_tools_enabled' => false,
        'ai_pricing_max_items_per_action' => 200,
        'ai_coupon_high_risk_percent' => 30,
        'ai_price_below_cost_policy' => 'block',
        'ai_pricing_vision_enabled' => false,
        'ai_shipping_tools_enabled' => false,
        'ai_storefront_tools_enabled' => false,
        'ai_storefront_place_order_enabled' => false,
        'ai_max_steps' => 6,
        'ai_whatsapp_enabled' => false,
        'ai_whatsapp_allow_writes' => false,
        'ai_whatsapp_max_risk' => 'medium',
        'ai_whatsapp_disabled_tools' => ['create_staff_user', 'create_role', 'update_role_permissions', 'delete_role', 'assign_roles', 'revoke_user_sessions', 'update_settings', 'update_document_numbering'],
        'ai_whatsapp_idle_rotate_hours' => 12,
        'ai_whatsapp_link_token_ttl_minutes' => 10,
        'ai_whatsapp_pin_required' => false,
    ];

    /** @var list<string> */
    public array $warnings = [];

    private const CACHE_KEY = 'app_settings_static';

    private const CACHE_VERSION_KEY = 'app_settings_static_version';

    private const CACHE_TTL_SECONDS = 3600;

    /** @var list<string> */
    private const NUMBERING_COUNTER_KEYS = [
        'shift_next_number',
        'expense_next_number',
        'treasury_transfer_next_number',
        'payment_notice_next_number',
        'pos_invoice_next_number',
        'invoice_next_number',
        'order_next_number',
        'purchase_order_next_number',
        'quotation_next_number',
        'movement_next_number',
        'transfer_next_number',
        'stocktake_next_number',
        'return_next_number',
        'purchase_request_next_number',
        'delivery_next_number',
        'supplier_invoice_next_number',
        'supplier_payment_next_number',
    ];

    /** Internal documents numbered via dedicated PostgreSQL sequences to prevent long transaction row locks. */
    private const SEQUENCE_TYPES = [
        'order' => 'order_next_number',
        'purchase_order' => 'purchase_order_next_number',
        'quotation' => 'quotation_next_number',
        'transfer' => 'transfer_next_number',
        'stocktake' => 'stocktake_next_number',
        'return' => 'return_next_number',
        'purchase_request' => 'purchase_request_next_number',
        'delivery' => 'delivery_next_number',
        'supplier_invoice' => 'supplier_invoice_next_number',
        'supplier_payment' => 'supplier_payment_next_number',
        // High-volume POS entities use database sequences where gaps are acceptable to avoid single-row lock contention.
        'shift' => 'shift_next_number',
        'pos_invoice' => 'pos_invoice_next_number',
        'expense' => 'expense_next_number',
        'treasury_transfer' => 'treasury_transfer_next_number',
        'payment_notice' => 'payment_notice_next_number',
    ];
    // Tax invoices remain row-locked because continuous sequential numbering without gaps is a legal requirement.

    /** @var array<string, array{0: string, 1: string}> */
    private const NUMBERING_TARGETS = [
        'order' => ['orders', 'order_number'],
        'purchase_order' => ['purchase_orders', 'po_number'],
        'quotation' => ['quotations', 'quotation_number'],
        'transfer' => ['stock_transfers', 'transfer_number'],
        'stocktake' => ['stocktakes', 'stocktake_number'],
        'return' => ['return_requests', 'return_number'],
        'purchase_request' => ['purchase_requests', 'request_number'],
        'delivery' => ['supplier_deliveries', 'delivery_number'],
        'supplier_invoice' => ['supplier_invoices', 'invoice_number'],
        'supplier_payment' => ['supplier_payments', 'payment_number'],
        'shift' => ['pos_shifts', 'shift_number'],
        'expense' => ['expenses', 'expense_number'],
        'treasury_transfer' => ['treasury_transfers', 'transfer_number'],
        'payment_notice' => ['wholesale_payment_notices', 'notice_number'],
        'movement' => ['stock_movements', 'reference_number'],
    ];

    /**
     * M9: تصفير الحالة الداخلية للخدمة (نفسها snapshot/عداد/عداد الوكيل).
     */
    public function forgetMemoryState(): void
    {
        $this->numberingConfig = [];
        $this->resetReadSnapshot(true);
    }

    /**
     * Return all settings grouped by their group name, with values cast to their declared types.
     * Numbering counters are read fresh because they change for every generated document number.
     *
     * @return array<string, array<string, mixed>>
     */
    public function getAllGrouped(): array
    {
        $grouped = $this->staticSettings();

        $counters = Setting::query()
            ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
            ->orderBy('key')
            ->get()
            ->mapWithKeys(fn (Setting $setting): array => [
                $setting->key => $this->castValue($setting->value, $setting->type),
            ])
            ->all();

        if (isset($counters['movement_next_number'])) {
            $counters['movement_next_number'] = $this->nextMovementNumber();
        }
        foreach (self::SEQUENCE_TYPES as $type => $key) {
            if (isset($counters[$key])) {
                $counters[$key] = $this->nextDocumentNumber($type);
            }
        }

        if ($counters !== []) {
            $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
            ksort($grouped['numbering']);
        }

        return $grouped;
    }

    private function staticSettings(): array
    {
        $read = function (): array {
            return Setting::query()
                ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
                ->orderBy('group')
                ->orderBy('key')
                ->get()
                ->groupBy('group')
                ->map(fn ($settings): array => $settings
                    ->mapWithKeys(fn (Setting $setting): array => [
                        $setting->key => $this->castValue($setting->value, $setting->type),
                    ])
                    ->all())
                ->all();
        };

        $inTransaction = DB::transactionLevel() > 0;
        if ($inTransaction && $this->transactionSnapshot !== null) {
            return $this->transactionSnapshot;
        }
        if ($inTransaction && $this->uncommittedSettings) {
            return $this->transactionSnapshot = $read();
        }
        $version = Cache::get(self::CACHE_VERSION_KEY);
        if (! is_string($version)) {
            Cache::add(self::CACHE_VERSION_KEY, (string) Str::uuid());
            $version = Cache::get(self::CACHE_VERSION_KEY);
        }

        // Cache resolved settings in request memory to avoid repeated cache roundtrips and deserialization overhead.
        if ($this->requestCache !== null) {
            return $this->requestCache;
        }
        $key = self::CACHE_KEY.':'.$version;
        if ($inTransaction) {
            // Reuse committed cache values, but never publish an uncommitted cache miss.
            return $this->transactionSnapshot = Cache::get($key) ?? $read();
        }

        $result = Cache::remember($key, self::CACHE_TTL_SECONDS, $read);
        // Guard against concurrent version bump during read to prevent pinning stale snapshots in request cache.
        if (Cache::get(self::CACHE_VERSION_KEY) === $version) {
            $this->requestCache = $result;
        }

        return $result;
    }

    public function get(string $key, mixed $default = null): mixed
    {
        if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
            if ($key === 'movement_next_number') {
                return $this->nextMovementNumber();
            }
            $type = array_search($key, self::SEQUENCE_TYPES, true);
            if (is_string($type)) {
                return $this->nextDocumentNumber($type);
            }
            $setting = Setting::query()->where('key', $key)->first();

            return $setting ? $this->castValue($setting->value, $setting->type) : $default;
        }
        foreach ($this->staticSettings() as $settings) {
            if (array_key_exists($key, $settings)) {
                return $settings[$key];
            }
        }

        if ($default === null && array_key_exists($key, self::DEFAULTS)) {
            return self::DEFAULTS[$key];
        }

        return $default;
    }

    public function getBool(string $key, bool $default = false): bool
    {
        return filter_var($this->get($key, $default), FILTER_VALIDATE_BOOLEAN);
    }

    /** @return array{name: string, logo: ?string, email: ?string, phone: ?string, address: ?string} */
    public function publicBranding(): array
    {
        // Read branding from in-memory settings to avoid repetitive database queries on public storefront hits.
        $company = $this->staticSettings()['company'] ?? [];

        return [
            'name' => trim((string) ($company['company_name'] ?? '')) ?: 'Alfarid',
            'logo' => $company['company_logo'] ?? null,
            'email' => $company['company_email'] ?? null,
            'phone' => $company['company_phone'] ?? null,
            'address' => $company['company_address'] ?? null,
        ];
    }

    private function assertNumberingDoesNotCollide(array $settings, array $after): void
    {
        foreach ($this->numberingDefinitions() as $type => $definition) {
            $keys = [$definition['prefix'], $definition['next'], $definition['padding']];
            $target = self::NUMBERING_TARGETS[$type] ?? null;
            if ($target === null || array_intersect($keys, array_keys($settings)) === []) {
                continue;
            }

            $prefix = array_key_exists($definition['prefix'], $after)
                ? (string) $after[$definition['prefix']]
                : (string) $this->get($definition['prefix'], '');
            $padding = array_key_exists($definition['padding'], $after)
                ? max(0, (int) $after[$definition['padding']])
                : max(0, (int) $this->get($definition['padding'], 0));
            $next = array_key_exists($definition['next'], $after)
                ? (int) $after[$definition['next']]
                : ($type === 'movement' ? $this->nextMovementNumber() : $this->nextDocumentNumber($type));

            // Collision scan covers the next number AND any future number:
            // any existing document sharing this prefix whose numeric suffix
            // is >= the proposed counter would collide now or later.
            $escaped = addcslashes($prefix, '\\%_');
            $existing = DB::table($target[0])->where($target[1], 'like', $escaped.'%')->pluck($target[1]);
            $max = null;
            foreach ($existing as $number) {
                // The remainder after the prefix must be purely numeric:
                // that numeric suffix is what future counters would reproduce.
                $tail = trim(substr((string) $number, strlen($prefix)));
                if ($tail === '' || ! ctype_digit($tail)) {
                    continue;
                }
                $max = max($max ?? 0, (int) $tail);
            }

            if ($max !== null && $max >= $next) {
                throw ValidationException::withMessages([
                    $definition['next'] => 'الرقم '.$prefix.str_pad((string) $next, $padding, '0', STR_PAD_LEFT).' مستخدم بالفعل في '.$target[0].'. غيّر البداية أو البادئة أو الطول.',
                ]);
            }
        }
    }

    /**
     * Update a flat key/value map atomically and invalidate the cached settings after commit.
     *
     * @param  array<string, mixed>  $settings
     *
     * @throws JsonException
     */
    public function updateBatch(array $settings, ?array $expected = null, array $via = []): void
    {
        $this->warnings = [];
        DB::transaction(function () use ($settings, $expected, $via): void {
            $this->uncommittedSettings = true;
            $this->resetReadSnapshot();
            $movementSequenceTarget = null;
            /** @var array<string, int> $documentSequenceTargets */
            $documentSequenceTargets = [];
            $lockedSettings = Setting::query()
                ->whereIn('key', array_keys($settings))
                ->orderBy('key')
                ->lockForUpdate()
                ->get()
                ->keyBy('key');

            $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());

            if ($missingKeys !== []) {
                throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
            }

            $before = [];
            $after = [];
            foreach ($settings as $key => $value) {
                /** @var Setting $setting */
                $setting = $lockedSettings->get($key);
                $current = $this->castValue($setting->value, $setting->type);
                if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
                    $current = $this->get($key);
                }
                // Dynamic sequence counters increment continuously under concurrent traffic; enforce monotonic increase rather than exact equality on optimistic concurrency.
                $isCounter = in_array($key, self::NUMBERING_COUNTER_KEYS, true);
                if (! $isCounter && $expected !== null && (! array_key_exists($key, $expected)
                    || $this->comparisonValue($current, $setting->type) !== $this->comparisonValue($expected[$key], $setting->type))) {
                    abort(409, 'تم تغيير إعداد أو عداد منذ فتح الصفحة؛ أعد تحميل الإعدادات قبل الحفظ.');
                }
                $before[$key] = $current;

                if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
                    $requested = $this->counterValue($value);
                    if ($requested > 999999999) {
                        throw ValidationException::withMessages([$key => 'الحد الأقصى للعداد هو 999999999.']);
                    }
                    $value = max($this->counterValue($setting->value), $requested);
                    if ($key === 'movement_next_number') {
                        $value = max($value, $this->nextMovementNumber());
                        $movementSequenceTarget = $value;
                    }
                    $sequenceType = array_search($key, self::SEQUENCE_TYPES, true);
                    if (is_string($sequenceType)) {
                        $value = max($value, $this->nextDocumentNumber($sequenceType));
                        $documentSequenceTargets[$sequenceType] = $value;
                    }
                    if ($requested < $value) {
                        throw ValidationException::withMessages([$key => 'لا يمكن خفض عداد الترقيم عن قيمته الحالية.']);
                    }
                }

                $setting->value = $value === null && str_ends_with($key, '_prefix')
                    ? ''
                    : $this->serializeValue($value, $setting->type);
                $setting->save();
                $after[$key] = $this->castValue($setting->value, $setting->type);
            }

            $this->assertNumberingDoesNotCollide($settings, $after);
            // Changing prefix or padding can collide with previously issued numbers; assert next formatted number is unused in target document table.
            $this->assertNoNumberingCollision(array_keys($settings));

            StaffAdministration::audit(request()->user('staff'), 'settings.updated', 'settings', null, array_keys($settings),
                ['settings' => $this->auditableSettings($before)], ['settings' => $this->auditableSettings($after)], $via);
            DB::afterCommit(fn () => $this->clearCache());

            // Synchronize sequence within transaction: non-transactional sequence advance may leave gaps on rollback, but prevents duplicate document numbers.
            if ($movementSequenceTarget !== null) {
                DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]);
            }
            foreach ($documentSequenceTargets as $type => $minimum) {
                DB::selectOne('SELECT document_next_number(?, ?) AS number', [$type, $minimum]);
            }
        }, attempts: 3);
    }

    /**
     * Atomically return and increment the next document number for the requested type.
     *
     * @throws JsonException
     */
    public function generateNextNumber(string $type): string
    {
        if ($type === 'movement') {
            [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
            $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;

            return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
        }
        if (isset(self::SEQUENCE_TYPES[$type])) {
            $definitions = $this->numberingDefinitions();
            $definition = $definitions[$type];
            [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
            $number = DB::selectOne('SELECT document_next_number(?) AS number', [$type])->number;

            return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
        }
        $definitions = $this->numberingDefinitions();

        if (! isset($definitions[$type])) {
            throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
        }

        $definition = $definitions[$type];
        [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);

        return DB::transaction(function () use ($definition, $prefix, $padding): string {
            // Counter row is locked and read fresh; prefix and padding are cached in request memory
            $nextSetting = Setting::query()
                ->where('key', $definition['next'])
                ->lockForUpdate()
                ->first();

            if ($nextSetting === null) {
                throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
            }

            $nextValue = $this->counterValue($nextSetting->value);

            $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
            $nextSetting->value = (string) ($nextValue + 1);
            $nextSetting->save();

            return $formatted;
        }, attempts: 3);
    }

    /**
     * Cache numbering prefix and padding per request to reduce query overhead.
     *
     * @return array{0: string, 1: int}
     */
    private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
    {
        return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
            $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');

            foreach ([$prefixKey, $paddingKey] as $key) {
                if (! $settings->has($key)) {
                    throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
                }
            }

            return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
        })();
    }

    public function clearCache(): void
    {
        Cache::forever(self::CACHE_VERSION_KEY, (string) Str::uuid());
        Cache::forget(self::CACHE_KEY); // Retire the cache key used before versioning.
        $this->numberingConfig = [];
        $this->requestCache = null;
        $this->resetReadSnapshot();
    }

    private function comparisonValue(mixed $value, string $type): ?string
    {
        if ($type === 'float' && $value !== null && is_numeric($value)) {
            return (string) BigDecimal::of((string) $value)->strippedOfTrailingZeros();
        }

        return $type === 'string' ? (string) ($value ?? '') : $this->serializeValue($value, $type);
    }

    private function auditableSettings(array $settings): array
    {
        // Only the public administrative settings schema is safe to audit as values.
        $allowed = array_keys((new UpdateSettingsRequest)->rules());

        return array_intersect_key($settings, array_flip($allowed));
    }

    /**
     * M-4: نوع المستند → [جدول، عمود الرقم] لفحص تصادم الترقيم.
     * invoice وpos_invoice بلا جدول مستندات خاص (فواتير الجملة طلبات،
     * وفواتير POS بلا عمود رقم مستقل) فيُتجاوزان من الفحص.
     *
     * @var array<string, array{0: string, 1: string}>
     */
    private const DOCUMENT_NUMBER_TARGETS = [
        'order' => ['orders', 'order_number'],
        'purchase_order' => ['purchase_orders', 'po_number'],
        'quotation' => ['quotations', 'quotation_number'],
        'transfer' => ['stock_transfers', 'transfer_number'],
        'stocktake' => ['stocktakes', 'stocktake_number'],
        'return' => ['return_requests', 'return_number'],
        'purchase_request' => ['purchase_requests', 'request_number'],
        'delivery' => ['supplier_deliveries', 'delivery_number'],
        'supplier_invoice' => ['supplier_invoices', 'invoice_number'],
        'supplier_payment' => ['supplier_payments', 'payment_number'],
        'shift' => ['pos_shifts', 'shift_number'],
        'expense' => ['expenses', 'expense_number'],
        'treasury_transfer' => ['treasury_transfers', 'transfer_number'],
        'payment_notice' => ['wholesale_payment_notices', 'notice_number'],
        'movement' => ['stock_movements', 'reference_number'],
    ];

    /**
     * M-4: لكل نوع مستند اتعدّلت بادئته أو طوله أو عداده، تأكد أن الرقم
     * التالي المُنسَّق بالصيغة الجديدة غير موجود أصلًا في جدول المستند.
    /**
     * Assert that formatted next number does not collide with existing document rows.
     *
     * @param  list<string>  $changedKeys
     */
    private function assertNoNumberingCollision(array $changedKeys): void
    {
        foreach (self::DOCUMENT_NUMBER_TARGETS as $type => [$table, $column]) {
            // Numbering settings follow a uniform {type}_prefix/_next_number/_padding naming convention.
            $keys = [$type.'_prefix', $type.'_next_number', $type.'_padding'];
            if (array_intersect($keys, $changedKeys) === []) {
                continue;
            }
            // Read current values within transaction to combine freshly saved overrides with untouched defaults.
            $rows = Setting::query()->whereIn('key', $keys)->get()->keyBy('key');
            if ($rows->count() !== count($keys)) {
                continue;
            }
            $prefix = (string) $this->castValue($rows[$keys[0]]->value, $rows[$keys[0]]->type);
            $next = (int) $this->castValue($rows[$keys[1]]->value, $rows[$keys[1]]->type);
            $padding = (int) $this->castValue($rows[$keys[2]]->value, $rows[$keys[2]]->type);
            $candidate = $prefix.str_pad((string) $next, $padding, '0', STR_PAD_LEFT);
            if (DB::table($table)->where($column, $candidate)->exists()) {
                throw ValidationException::withMessages([$keys[0] => "الرقم التالي المُنسَّق ({$candidate}) صدر من قبل لنوع {$type}؛ غيّر البادئة أو الطول أو ارفع العداد."]);
            }
        }
    }

    /**
     * @return array<string, array{prefix: string, next: string, padding: string}>
     */
    private function numberingDefinitions(): array
    {
        return [
            'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
            'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
            'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
            'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
            'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
            'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
            'return' => ['prefix' => 'return_prefix', 'next' => 'return_next_number', 'padding' => 'return_padding'],
            'purchase_request' => ['prefix' => 'purchase_request_prefix', 'next' => 'purchase_request_next_number', 'padding' => 'purchase_request_padding'],
            'delivery' => ['prefix' => 'delivery_prefix', 'next' => 'delivery_next_number', 'padding' => 'delivery_padding'],
            'supplier_invoice' => ['prefix' => 'supplier_invoice_prefix', 'next' => 'supplier_invoice_next_number', 'padding' => 'supplier_invoice_padding'],
            'supplier_payment' => ['prefix' => 'supplier_payment_prefix',    'next' => 'supplier_payment_next_number',    'padding' => 'supplier_payment_padding'],
            'movement' => ['prefix' => 'movement_prefix', 'next' => 'movement_next_number', 'padding' => 'movement_padding'],
            'shift' => ['prefix' => 'shift_prefix',               'next' => 'shift_next_number',               'padding' => 'shift_padding'],
            'pos_invoice' => ['prefix' => 'pos_invoice_prefix',      'next' => 'pos_invoice_next_number',      'padding' => 'pos_invoice_padding'],
            'expense' => ['prefix' => 'expense_prefix',             'next' => 'expense_next_number',             'padding' => 'expense_padding'],
            'treasury_transfer' => ['prefix' => 'treasury_transfer_prefix',   'next' => 'treasury_transfer_next_number',   'padding' => 'treasury_transfer_padding'],
            'payment_notice' => ['prefix' => 'payment_notice_prefix',      'next' => 'payment_notice_next_number',      'padding' => 'payment_notice_padding'],
        ];
    }

    private function nextMovementNumber(): int
    {
        $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');

        return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
    }

    private function nextDocumentNumber(string $type): int
    {
        if (! isset(self::SEQUENCE_TYPES[$type])) {
            throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
        }
        $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");

        return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
    }

    private function counterValue(mixed $value): int
    {
        $number = (is_int($value) || is_string($value))
            ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
            : false;
        if ($number === false) {
            throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
        }

        return $number;
    }

    private function castValue(?string $value, string $type): mixed
    {
        if ($value === null) {
            return null;
        }

        if ($type === 'json') {
            try {
                return json_decode($value, true, 512, JSON_THROW_ON_ERROR);
            } catch (JsonException) {
                return null;
            }
        }

        return match ($type) {
            'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
            'integer' => (int) $value,
            'float' => (float) $value,
            default => $value,
        };
    }

    /** @throws JsonException */
    private function serializeValue(mixed $value, string $type): ?string
    {
        if ($value === null) {
            return null;
        }

        if ($type === 'json') {
            return json_encode($value, JSON_THROW_ON_ERROR);
        }

        if ($type === 'boolean') {
            return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
        }

        return (string) $value;
    }
}<?php

